class Solution {
    LL g(LL l, LL r, VVL &ct) {
        LL MAXLEVEL = 32, i, j, k, ans = 0, n = r - l + 1, x;
        FOR(i, MAXLEVEL) {
            x = ct[r][i] - ct[l - 1][i];
            if (x == n) ans += 1LL << i;
        }
        return ans;
    }

public:
    long long countSubarrays(vector<int>& nums, int k) {
        LL n = nums.size(), i, j, l, r, MAXLEVEL = 32, ans, xl, xr;
        VVL ct(n + 1, VL(MAXLEVEL, 0));
        FOR1(i,n) {
            ct[i] = ct[i - 1];
            FOR(j, MAXLEVEL) {
                if ((1LL << j) & nums[i - 1]) ct[i][j]++;
            }
        }

        ans = 0;
        l = 1; r = 1;
        FOR1(i, n) {
            while ((l <= n) && (g(i, l, ct) > k)) l++;
            while ((r <= n) && (g(i, r, ct) >= k)) r++;

            if ((l <= n) && (g(i, l, ct) == k)) ans += r - l;
        }

        return ans;
    }
};

