template<class T>
struct RMQ {
	vector<vector<T>> jmp;
	RMQ(const vector<T>& V) : jmp(1, V) {
		for (int pw = 1, k = 1; pw * 2 <= sz(V); pw *= 2, ++k) {
			jmp.emplace_back(sz(V) - pw * 2 + 1);
			rep(j,0,sz(jmp[k]))
				jmp[k][j] = jmp[k - 1][j]&jmp[k - 1][j + pw];
		}
	}
	T query(int a, int b) {
		assert(a < b); // or return inf if a == b
		int dep = 31 - __builtin_clz(b - a);
		return jmp[dep][a]&jmp[dep][b - (1 << dep)];
	}
};
class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        RMQ rmq(nums);
        ll ans = 0;
        for(int i = 0; i < n; i++){
            int lo = i, hi = n-1;
            while(lo < hi){
                int mid = (lo+hi)/2;
                if(rmq.query(i,mid+1) <= k) hi = mid;
                else lo = mid+1;
            }
            if(rmq.query(i,lo+1) != k) continue;
            int st = lo;
            lo = i, hi = n-1;
            while(lo < hi){
                int mid = (lo+hi)/2;
                if(rmq.query(i,mid+1) <= k-1) hi = mid;
                else lo = mid+1;
            }
            if(rmq.query(i,lo+1) > k-1) lo++;
            //cout << st << " " << i << " " << lo << "\n";
            ans += lo-st;
        }
        return ans;
    }
};

