template<typename I> vector<int> get_substring_occurrences(I f_pattern, I l_pattern, I f_text, I l_text) {const size_t n = std::distance(f_pattern, l_pattern); const size_t m = std::distance(f_text, l_text); assert(n); auto cmp = [&](size_t i, size_t j) {if (i == n || j == n) return i == j; return (i < n ? *(f_pattern + i) : *(f_text + i - n - 1)) == (j < n ? * (f_pattern + j) : * (f_text + j - n - 1));}; vector<int> pf(n), res; for (size_t i = 1, ppf = 0; i < n + 1 + m; ++i) {size_t p = 0; for (size_t j = ppf; j && !p; j = pf[j - 1]) {if (cmp(i, j)) p = j + 1;} p += !p && cmp(i, 0); ppf = p; if (i < n) pf[i] = p; if (p == n) res.push_back(i - n * 2);} return res;}
template<typename T> T integral_tersearch_argmin(auto f, T l, T r) {static_assert(is_integral_v<decltype(l)>); using U = decltype(f(l)); const ld FI = 1.6180339887498948482045868343656381177203; T p1 = l + (r - l) / (FI + 1), p2 = r - (r - l) / (FI + 1); U v1 = f(p1), v2 = f(p2); while (r - l > 7) {if (v1 < v2) {r = p2; p2 = p1, v2 = v1; p1 = l + (r - l) / (FI + 1), v1 = f(p1);} else {l = p1; p1 = p2, v1 = v2; p2 = r - (r - l) / (FI + 1), v2 = f(p2);}} T best_arg = l; U best_val = f(l), prv = best_val; while (++l <= r) {U tyt = l == p1 ? v1 : l == p2 ? v2 : f(l); if (tyt > prv) break; if (chmin(best_val, tyt)) best_arg = l; prv = tyt;} return best_arg;};
template<typename T> T integral_binary_search_last_when_true(auto f, T l, T r) {static_assert(is_same<decltype(l), decltype(r)>::value); while (l + 1 < r) {T md = l + (r - l) / 2; if (f(md))l = md; else r = md;} return l;};
template<typename T> T integral_binary_search_last_when_true(auto f, T l) {T d = 1; while (f(l + d)) d *= 2; d /= 2; for (T u = d; u; u /= 2) if (f(l + d + u)) d += u; return l + d;};
template<typename T> T get_kth_statistic_by_binary_search(T n, T k, T val_l, T val_r, auto cnt_leq) {assert(0 <= k && k < n); assert(val_l <= val_r); return integral_binary_search_last_when_true<T>([&](T x){return cnt_leq(x) <= k;}, val_l - 1, val_r) + 1;}

//Binary function merge() must be associative, commutative and idempotent
//<O(nlog(n)T(merge)), O(nlog(n))> preprocessing, O(T(merge)) per query
template<typename T, auto merge = [](const T& l, const T& r) -> T{return l & r;}>
class sparse_table {
    size_t n, K;
    vector<vector<T>> m;

public:
    sparse_table() = default;
    template<typename I>
    sparse_table(I first, I last): n(std::distance(first, last)), K(n ? __lg(n) + 1 : 0), m(K) {
        if (!n) return;
        for (size_t i = 0; i < K; ++i) m[i].resize(max<size_t>(0, n + 1 - (1 << i)));
        std::copy(first, last, m[0].begin());
        for (size_t i = 1; i < K; ++i) {
            for (size_t j = 0; j + (1 << i) <= n; ++j) {
                m[i][j] = merge(m[i - 1][j], m[i - 1][j + (1 << (i - 1))]);
            }
        }
    }
    template<typename T_arr>
    sparse_table(const T_arr& arr) {*this = sparse_table(arr.begin(), arr.end());}

    T query(size_t l, size_t r) const {
        assert(l <= r && r < n);
        const int u = __lg(r - l + 1);
        return merge(m[u][l], m[u][r - (1 << u) + 1]);
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& m, int k) {
        ll a = m.size();
        ll o = 0;
        sparse_table<int> kek(all(m));
        for (int i = 0; i < a; ++i) {
            auto f1 = [&](int r) {return kek.query(i, r) > k;};
            auto f2 = [&](int r) {return kek.query(i, r) >= k;};
            int c1 = integral_binary_search_last_when_true<int>(f1, i - 1, a);
            int c2 = integral_binary_search_last_when_true<int>(f2, i - 1, a);
            o += c2 - c1;
        }
        return o;
    }
};

template<class T>
class sparse{
	public:
	int N, LG;
	vector<vector<T>>spt;
	vector<int>lg;
	sparse(){}
	sparse(vector<T> &a){
		N = a.size();
		LG = 32 - __builtin_clz(std::max(N - 1, 1));
		spt.resize(N+1, vector<T>(LG+1));
		lg.resize(N + 5,0);
		for(int i = 2;i <= N;i++)
			lg[i] = lg[i/2] + 1;
		build(a);
	}
	void build(vector<T> &a){
		for(int i = 0;i < N;i++)
			spt[i][0] = a[i];
		for(int j = 1;j <= LG;j++){
			int len = (1 << j), half = (1 << (j-1));
			for(int i = 0;i + len <= N;i++)
				spt[i][j] = combine(spt[i][j-1],spt[i+half][j-1]);
		}
	}
	T find(int l, int r){ // For idempotent operations in O(1)
		assert(l <= r && l >= 0 && r <= N-1);
		int lgg = lg[r-l+1], len = (1<<lgg);
		return combine(spt[l][lgg], spt[r-len+1][lgg]);
	}
	T query(int L, int R){ // For other operations in O(log n)
		T answer = 0;
		for (int j = LG; j >= 0; j--) {
			if (L + (1 << j) - 1 <= R) {
				answer = combine(answer,spt[L][j]);
				L += 1 << j;
			}
		}
		return answer;
	}
	T combine(T x,T y){
		return x & y;
	}
};


