class Solution:
    def countSubarrays(self, arr, k):
        n = len(arr)

        log_n = int(log2(n)) + 1
        st = [[0] * n for _ in range(log_n)]
        st[0] = arr[:]

        for j in range(1, log_n):
            for i in range(n - (1 << j) + 1):
                st[j][i] = st[j - 1][i] & st[j - 1][i + (1 << (j - 1))]

        def query(l, r):
            exp = int(log2(r - l + 1))
            return st[exp][l] & st[exp][r - (1 << exp) + 1]

        ans = 0
        for i in range(n):
            l, r = i, n
            while l + 1 < r:
                mid = (l + r) // 2
                if query(i, mid) >= k:
                    l = mid
                else:
                    r = mid

            if query(i, l) != k:
                continue

            temp = l
            l, r = i - 1, n
            while l + 1 < r:
                mid = (l + r) // 2
                if query(i, mid) > k:
                    l = mid
                else:
                    r = mid

            ans += temp - l

        return ans

