template <class T> struct sparseTable { // 0-indexed
    T op(T a, T b) {
        return a & b;
    } 

    int n;
    vector<vector<T>> st;

    sparseTable() {}

    sparseTable(vector<T> v) {
        n = v.size();
        st = vector<vector<T>>(__lg(n)+1, vector<T>(n, 0));
        st[0] = v;
        for (int i=1; i<st.size(); i++) {
            for (int j=0; j+(1<<i)<=n; j++) st[i][j] = op(st[i-1][j], st[i-1][j+(1<<(i-1))]);
        }
    } 

    T query(int l, int r) { // inclusive range
        int sz = __lg(r-l+1);
        return op(st[sz][l], st[sz][r-(1<<sz)+1]);
    }
};

long long res(vector<int>& nums, int k) {
    // >= k
    sparseTable<int> st(nums);
    long long res = 0;
    for (int i=0; i<nums.size(); i++) {
        if (nums[i] < k) continue;
        int low = i, high = nums.size() - 1, mid;
        while (low != high) {
            mid = (low + high + 1) / 2;
            if (st.query(i, mid) >= k) low = mid;
            else high = mid - 1;
        }
        res += low - i + 1;
    }
    return res;
}

