public:
    long long countSubarrays(vector<int>& nums, int k) {
        return res(nums, k) - res(nums, k + 1);
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size(), LOG = 18;
        vector<vector<int>> dp(n, vector<int> (LOG));
        for(int i=0;i<n;i++) dp[i][0] = nums[i];
        for(int j=1;j<LOG;j++) {
            for(int i=0;i<=n-(1<<j);i++) {
                dp[i][j] = dp[i][j - 1] & dp[i + (1 << (j - 1))][j - 1];
            }
        }
        long long ans = 0;
        vector<int> arr(n + 10);
        arr[1] = 0;
        for(int i=2;i<=n;i++) arr[i] = arr[i / 2] + 1;
        function<int(int,int)> get = [&](int x, int y) {
            int dist = y - x + 1;
            int l = arr[dist];
            return (dp[x][l] & dp[y - (1 << l) + 1][l]);
        };
        for(int i=0;i<n;i++) {
            int l = i, r = n - 1;
            int left = i + 1, right = i;
            while(l <= r) {
                int mid = (l + r) / 2;
                int now = get(i, mid);
                if(now > k) {
                    l = mid + 1;
                }
                else if(now < k) r = mid - 1;
                else left = mid, r = mid - 1;
            }
            l = i, r = n - 1;
            while(l <= r) {
                int mid = (l + r) / 2;
                int now = get(i, mid);
                if(now > k) {
                    l = mid + 1;
                }
                else if(now < k) r = mid - 1;
                else right = mid, l = mid + 1;
            }
            ans += right - left + 1;
        }
        return ans;
    }
};

