class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        j1 = -1
        j2 = -1
        d1 = [0]*32
        d2 = [0]*32
        ans = 0

        def f(d, i, j):
            ret = 0
            for b in range(32):
                if d[b] == (i-j):
                    ret += 1<<b
            return ret


        for i in range(len(nums)):
            for b in range(32):
                if (1<<b)&nums[i]:
                    d1[b] += 1
                    d2[b] += 1
            while j1 < i and f(d1, i, j1) <= k:
                j1 += 1
                for b in range(32):
                    if (1<<b)&nums[j1]:
                        d1[b] -= 1
            while j2 < i and f(d2, i, j2) < k:
                j2 += 1
                for b in range(32):
                    if (1<<b)&nums[j2]:
                        d2[b] -= 1
            ans += (j1-j2)
