class Solution {
public:
    struct segtree {
    using T = int; 
    using U = int; 

    int sz;
    vector<T> vals; 

    inline T single(U a) {
        return a;
    }

    inline T combine(T a, T b) {
        return(a&b); 
    }

    T NEUTRAL_ELEMENT = INT_MAX;

    void init(int _sz) {
        sz = _sz;
        vals.assign(2 * sz, NEUTRAL_ELEMENT); 
    }

    void build(vector<U> &v) {
        for(int i = 0; i < v.size(); ++i)
            vals[sz + i] = single(v[i]);
        for(int i = sz - 1; i > 0; --i)
            vals[i] = combine(vals[i << 1], vals[i << 1 | 1]);  
    }

    void set(int idx, U val) {  
        for(vals[idx += sz] = single(val); idx >>= 1; )
            vals[idx] = combine(vals[idx<<1], vals[idx<<1|1]); 
    }

    T query(int l, int r) {
        T resl = NEUTRAL_ELEMENT, resr = NEUTRAL_ELEMENT; 
        for(l += sz, r += sz; l < r; l >>= 1, r >>= 1) {
            if (l&1) resl = combine(resl, vals[l++]); 
            if (r&1) resr = combine(vals[--r], resr); 
        }
        return combine(resl, resr); 
    }    
};

    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size(); 
        segtree st; 
        st.init(n); 
        st.build(nums); 
        long long ans = 0; 
        for(int i = 0; i < n; ++i)
        {
            int left = n + 1, right = -1; 
            int l = i, r = n - 1; 
            while(r - l >= 0)
            {
                int mid = l + (r - l)/2; 
                int d = st.query(i, mid + 1); 
                if(d > k) 
                    l = mid + 1; 
                else if(d < k) 
                    r = mid - 1; 
                else 
                {
                    left = min(left, mid); 
                    r = mid - 1; 
                }
            }
            l = i, r = n-1; 
            while(r - l >= 0)
            {
                int mid = l + (r - l)/2; 
                int d = st.query(i, mid + 1); 
                if(d > k) 
                    l = mid + 1; 
                else if(d < k) 
                    r = mid - 1; 
                else 
                {
                    right = max(right, mid); 
                    l = mid + 1; 
                }
            }
            if(right != -1) 
                ans += (right - left + 1); 
        }
        return ans; 

    }
};

