template<typename T>
struct SparseTable {
    int n;
    vector<vector<T>> dp;
    vector<int> prec;

    SparseTable(vector<T>& a) {
        n = a.size();
        int len = 1;
        int k = 0;
        while (len <= 2 * n) {
            len <<= 1;
            ++k;
        }
        dp.assign(len, vector<T>(k, 0));
        prec.assign(len, 0);
        for (int i = 2; i < 2 * n; i++) {
            prec[i] = prec[i >> 1] + 1;
        }
        for (int i = 0; i < n; i++) {
            dp[i][0] = a[i];
        }
        for (int j = 1; (1 << j) <= n; j++) {
            for (int i = 0; i < n; i++) {
                dp[i][j] = combine(dp[i][j - 1], dp[i + (1 << (j - 1))][j - 1]);
            }
        }
    }

    T combine(const T& a, const T& b) {
        return (a & b);
    }

    T query(int l, int r) {
        int k = prec[r - l + 1];
        return combine(dp[l][k], dp[r - (1 << k) + 1][k]);
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& a, int k) {
        SparseTable<int> sp(a);
        int n = (int) a.size();
        long long ans = 0;
        for (int i = 0; i < n; i++) {
            int lft = -1;
            {
                int l = 0, r = i;
                while (l <= r) {
                    int mid = (l + r) >> 1;
                    if (sp.query(mid, i) >= k) {
                        r = mid - 1;
                        lft = mid;
                    } else {
                        l = mid + 1;
                    }
                }
                if (lft != -1 && sp.query(lft, i) != k) {
                    lft = -1;
                }
            }
            if (lft != -1) {
                int l = 0, r = i, rgt = -1;
                while (l <= r) {
                    int mid = (l + r) >> 1;
                    if (sp.query(mid, i) <= k) {
                        l = mid + 1;
                        rgt = mid;
                    } else {
                        r = mid - 1;
                    }
                }
                ans += 1LL * (rgt - lft + 1);
            }
        }
        return ans;
    }
};

template <class B>
struct SparseTable : public B {
    using T = typename B::T;
    int n; vector<vector<T>> st;
    SparseTable(vector<T> & a): n((int) a.size()), st(__lg(n) + 1, vector<T>(n, B::e)) {
        for(int i = 0; i < n; i++) {
            st[0][i] = a[i];
        }
        int lev = __lg(n);
        for(int i = 1; i <= lev; i++) {
            for(int j = 0; j < n; j++) {
                st[i][j] = B::comb(st[i - 1][j], st[i - 1][min(n - 1, j + (1 << (i - 1)))]);
            }
        }
    }
    T qry(int l, int r) {
        int lev = __lg(r - l + 1);
        return B::comb(st[lev][l], st[lev][r - (1 << lev) + 1]);
    }
};

