class Solution {
public:
    int n, h[20][100005], lg[100005];
    inline int get(int l, int r){
        int t = lg[r - l + 1];
        return h[t][l] & h[t][r - (1 << t) + 1];
    }
    long long countSubarrays(vector<int>& nums, int k) {
        n = nums.size();
        for(int i = 1; i <= n; ++i) h[0][i] = nums[i - 1];
        int now = 0;
        for(int i = 1; i <= n; ++i){
            lg[i] = now;
            if(i == (1 << now + 1)) ++now;
        }
        for(int i = 1; i <= lg[n]; ++i)
            for(int j = 1; j + (1 << i) - 1 <= n; ++j)
                h[i][j] = h[i - 1][j] & h[i - 1][j + (1 << i - 1)];
        long long ans = 0ll;
        for(int i = 1; i <= n; ++i){
            int l = 1, r = i, mid;
            while(l < r){
                mid = l + r + 1 >> 1;
                int s = get(mid, i);
                if(s <= k) l = mid;
                else r = mid - 1;
            }
            if(get(l, i) != k) continue;
            int tmp = l;
            l = 1, r = i;
            while(l < r){
                mid = l + r >> 1;
                int s = get(mid, i);
                if(s >= k) r = mid;
                else l = mid + 1;
            }
            ans += 1ll * (tmp - l + 1);
        }
        return ans;
    }
};

