class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {

        int n = len(nums);

        Sparse_Table<Monoid_And<int>> St(nums);
        long long ret = 0;
        For(x, n){
            int lid = St.max_right(x, [&](int y){ return y > k; });
            int rid = St.max_right(x, [&](int y){ return y >= k; });
            ret += abs(rid - lid);
        }
        return ret;
    }
};

