class RangeQuery:
    def __init__(self, data, func=min):
        self.func = func
        self._data = _data = [list(data)]
        i, n = 1, len(_data[0])
        while 2 * i <= n:
            prev = _data[-1]
            _data.append([func(prev[j], prev[j + i]) for j in range(n - 2 * i + 1)])
            i <<= 1

    def query(self, start, stop):
        """func of data[start, stop)"""
        depth = (stop - start).bit_length() - 1
        return self.func(self._data[depth][start], self._data[depth][stop - (1 << depth)])

    def __getitem__(self, idx):
        return self._data[0][idx]
class Solution:
    def countSubarrays(self, a: List[int], k: int) -> int:
        s = RangeQuery(a, lambda x, y: x & y)
        ans = 0
        n = len(a)
        for i in range(n):
            left = i
            right = i
            L = i
            U = n - 1
            while L <= U:
                m = (L + U) >> 1
                if(s.query(i, m + 1) <= k):
                    left = m
                    U = m - 1
                else:
                    L = m + 1
            L = i
            U = n - 1
            while L <= U:
                m = (L + U) >> 1
                if(s.query(i, m + 1) >= k):
                    right = m
                    L = m + 1
                else:
                    U = m -1
            if(s.query(i, left + 1) == k):
                ans += right - left + 1
        return ans

class Solution {
public:
    int bz[100005][18], n, K;
    vector<int> a;

    void calc_bz(){
        int i, j, k;
        for (i = 0; i < n; ++i) bz[i][0] = a[i];
        for (j = 1; (1<<j) <= n; ++j)
            for (i = 0; i < n; ++i){
                bz[i][j] = bz[i][j - 1];
                k = i + (1<<(j - 1));
                if (k < n) bz[i][j] &= bz[k][j - 1];
            }
    }

    int suan(int x, int y){
        int t = (int)(log(y - x + 1.0) / log(2.0));
        while ((1<<(t + 1)) <= (y - x + 1)) ++t;
        return bz[x][t] & bz[y - (1<<t) + 1][t];
    }

    long long calc_yh(){
        int i, j, t, st, ed, mid, l, r;
        long long res = 0;
        for (i = 0; i < n; ++i){
            l = r = -1;
            st = 0; ed = i;
            while (st <= ed){
                mid = (st + ed) / 2;
                t = suan(mid, i);
                if (t == K) r = mid;
                if (t <= K) st = mid + 1;
                else ed = mid - 1;
            }

            if (r == -1) continue;

            st = 0; ed = i;
            while (st <= ed){
                mid = (st + ed) / 2;
                t = suan(mid, i);
                if (t == K) l = mid;
                if (t >= K) ed = mid - 1;
                else st = mid + 1;
            }

            res += r - l + 1;
        }

        return res;
    }

    long long countSubarrays(vector<int>& aa, int KK) {
        a = aa;
        K = KK;
        n = a.size();
        calc_bz();
        return calc_yh();
    }
};

