    {
        if (low == high)
        {
            seg_tree[seg_index] = arr[low];
            return;
        }

        int mid = low + (high - low) / 2;
        buildUtil(low, mid, 2 * seg_index + 1, arr);
        buildUtil(mid + 1, high, 2 * seg_index + 2, arr);
        seg_tree[seg_index] = seg_tree[2 * seg_index + 1] & seg_tree[2 * seg_index + 2];
    }

    void assign(int low, int high, int seg_index, int index, int value)
    {
        if (low == high)
        {
            seg_tree[seg_index] = value;
            return;
        }

        int mid = low + (high - low) / 2;
        if (index >= low && index <= mid)
            assign(low, mid, 2 * seg_index + 1, index, value);
        else
            assign(mid + 1, high, 2 * seg_index + 2, index, value);

        seg_tree[seg_index] = seg_tree[2 * seg_index + 1] & seg_tree[2 * seg_index + 2];
    }

    void increment(int low, int high, int seg_index, int index, int value)
    {
