class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        vector<vector<int>> state(n + 1, vector<int>(30, 0));
        for (int i = 0; i < n; i++){
            for (int j = 0; j < 30; j++){
                state[i + 1][j] = state[i][j] + (1 & (nums[i] >> j));
            }
        }
        auto check = [&](int l, int r) -> int {
            int cur = 0;
            for (int i = 0; i < 30; i++){
                if (state[r + 1][i] - state[l][i] == r - l + 1) cur |= (1 << i);
            }
            return cur;
        };

        i64 res = 0;
        for (int i = 0; i < n; i++){
            //rightmost
            int l = i, r = n - 1;
            while(l < r){
                int mid = (l + r + 1) / 2;
                if (check(i, mid) < k){
                    r = mid - 1;
                }
                else {
                    l = mid;
                }
            }
            if (check(i, l) != k) continue;

            int RIGHTMOST = l;
            //left most
            l = i, r = RIGHTMOST;
            while(l < r){
                int mid = (l + r) / 2;
                if (check(i, mid) <= k){
                    r = mid;
                }
                else {
                    l = mid + 1;
                }
            }
            res += (RIGHTMOST - l + 1);




        }
        return res;



    }
};

