int neut = 0xffffffff;
struct it {
	vector<int>t;
	int n; 
	it(int n) : n(n), t(2 * n) {}
	void st(int x, int y) {
		x += n;
		t[x] = y;
		while (x > 1) t[x >> 1] = t[x] & t[x ^ 1], x >>= 1;
	}
	int get(int l, int r) {
		int res = neut;
		for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
			if (l & 1) res &= t[l++];
			if (r & 1) res &= t[--r];
		}
		return res;
	}
};


class Solution {
public:
	long long countSubarrays(vector<int>& nums, int k) {
		int n = nums.size();
		it st(n);
		for (int i = 0; i < n; ++i) st.st(i, nums[i]);
		long long ans = 0;
		for (int i = 0; i < n; ++i) {
			int L = i, R = n + 1;
			while (R - L > 1) {
				int M = (L + R) / 2;
				if (st.get(i, M) < k)
					R = M;
				else
					L = M;
			}
			int LL = i, RR = n + 1;
			while (RR - LL > 1) {
				int M = (LL + RR) / 2;
				if (st.get(i, M) <= k)
					RR = M;
				else
					LL = M;
			}
			ans += L - LL;
		}
		return ans;
    }
};

class sparsetable:

    def __init__(self , function , bound):
        self.b = None
        self.block = None
        self.n = None
        self.size = None
        self.bound = bound
        self.function = function

    def construct(self , a):

        self.n = len(a)
        for i in range(30):
            if(self.n < (1 << i)):
                self.size = i
                break

        self.b = [[self.bound for i in range(self.size)] for j in range(self.n)]
        self.block = [-1 for i in range(self.n + 1)]

        for i in range(self.n):
            self.b[i][0] = a[i]

        for j in range(1 , self.size):
            for i in range(self.n - (1 << (j - 1))):
                self.b[i][j] = self.function(self.b[i][j - 1] , self.b[i + (1 << (j - 1))][j - 1])

        for i in range(1 , self.n + 1):
            for j in range(self.size - 1 , -1 , -1):
                if(i >= (1 << j)):
                    self.block[i] = j
                    break

    def query(self , l , r):

        #handle cases if required
        dist = r - l + 1

        ans = self.function(self.b[l][self.block[dist]] , self.b[r - (1 << self.block[dist]) + 1][self.block[dist]])
        return ans


    def log_query(self , l , r):

        #handle cases if required
        dist = r - l + 1

        ans = self.bound
        for i in range(self.size - 1 , -1 , -1):
            if(dist >> i & 1):
                ans = self.function(ans , self.b[l][i])
                l += (1 << i)

        return ans

def AND(a , b):
    return (a & b)

class Solution:
    def countSubarrays(self, a: List[int], k: int) -> int:

        n = len(a)
        ans = 0

        sp = sparsetable(AND , (1 << 31) - 1)
        sp.construct(a)

        for i in range(n):

            right = -1
            l , h = i , n - 1
            while(l <= h):
                mid = (l + h) // 2
                if(sp.query(i , mid) < k):
                    h = mid - 1
                else:
                    right = mid
                    l = mid + 1

            left = n
            l , h = i , n - 1
            while(l <= h):
                mid = (l + h) // 2
                if(sp.query(i , mid) <= k):
                    left = mid
                    h = mid - 1
                else:
                    l = mid + 1


            if(right != -1):
                if(sp.query(i , right) == k):
                    ans += max(0 , right - left + 1)


        return ans

class Solution {
public:
    vector<vector<int>>ct;
    int max_pos(int n, int start, int k) {
        int l = start, r = n - 1;
        int ret = -1;
        while (l <= r) {
            int mid = (l + r) / 2;
            int val = 0;
            for (int i = 0; i < 32; i++) {
                if (ct[mid + 1][i] - ct[start][i] == mid - start + 1)val += (1 << i);
            }
            if (val > k)l = mid + 1;
            else if (val == k)l = mid + 1, ret = max(ret, mid);
            else r = mid - 1;
        }
        return ret;
    }

    int min_pos(int n, int start, int k) {
        int l = start, r = n - 1;
        int ret = 2e9;
        while (l <= r) {
            int mid = (l + r) / 2;
            int val = 0;
            for (int i = 0; i < 32; i++) {
                if (ct[mid + 1][i] - ct[start][i] == mid - start + 1)val += (1 << i);
            }
            if (val > k)l = mid + 1;
            else if (val == k)r = mid - 1, ret = min(ret, mid);
            else r = mid - 1;
        }
        return ret;
    }

    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        ct.assign(n + 1, vector<int>(32, 0));
        for (int i = 0; i < n; i++) {
            ct[i + 1] = ct[i];
            for (int j = 0; j < 32; j++) {
                if (nums[i] & (1 << j))ct[i + 1][j]++;
            }
        }

        long long ret = 0;
        for (int i = 0; i < n; i++) {
            int l = min_pos(n, i, k), r = max_pos(n, i, k);
