class Solution {
public:
    vector<vector<int>>ct;
    int max_pos(int n, int start, int k) {
        int l = start, r = n - 1;
        int ret = -1;
        while (l <= r) {
            int mid = (l + r) / 2;
            int val = 0;
            for (int i = 0; i < 32; i++) {
                if (ct[mid + 1][i] - ct[start][i] == mid - start + 1)val += (1 << i);
            }
            if (val > k)l = mid + 1;
            else if (val == k)l = mid + 1, ret = max(ret, mid);
            else r = mid - 1;
        }
        return ret;
    }

    int min_pos(int n, int start, int k) {
        int l = start, r = n - 1;
        int ret = 2e9;
        while (l <= r) {
