class Solution {
public:
    long long int solve(vector<int> &a, int k) {
        int n = a.size();
        int m = 30;
        vector<vector<int>> dp(n, vector<int>(m, n));
        for (int i = n - 1; i >= 0; i--) {
            for (int j = 0; j < m; j++) {
                if (i + 1 < n) dp[i][j] = dp[i + 1][j];
                if (!(a[i] & (1 << j))) dp[i][j] = i;
            }
        }

        long long int ans = 0;
        for (int i = 0; i < n; i++) {
            int check = i;
            for (int j = 0; j < m; j++) {
                if (k & (1 << j)) continue;
                check = max(check, dp[i][j]);
            }
            ans += (n - 1) - check + 1;
        }
        return ans;
    }

    long long countSubarrays(vector<int>& nums, int k) {
        vector<vector<int>> a;
        vector<int> temp;
        for (auto i: nums) {
            if ((i & k) != k) {
                if (temp.size() > 0) a.push_back(temp);
                temp = move(vector<int>());
            } else {
                temp.push_back(i);
            }
        }
        if (temp.size() > 0) a.push_back(temp);

        long long int ans = 0;
        for (auto i: a) ans += solve(i, k);
        return ans;
    }
};

