struct Tree {
	typedef int T;
	static constexpr T unit = INT_MAX;
	T f(T a, T b) { return a & b; } // (any associative fn)
	vector<T> s; int n;
	Tree(int n = 0, T def = unit) : s(2*n, def), n(n) {}
	void update(int pos, T val) {
		for (s[pos += n] = val; pos /= 2;)
			s[pos] = f(s[pos * 2], s[pos * 2 + 1]);
	}
	T query(int b, int e) { // query [b, e)
		T ra = unit, rb = unit;
		for (b += n, e += n; b < e; b /= 2, e /= 2) {
			if (b % 2) ra = f(ra, s[b++]);
			if (e % 2) rb = f(s[--e], rb);
		}
		return f(ra, rb);
	}
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        Tree tree(n);
        for(int i = 0; i < n; i++) {
            tree.update(i,nums[i]);
        }
        ll res = 0;
        for(int i = 0; i < n; i++) {
            if((nums[i] & k) == k) {
                int l1 = i + 1, r1 = n+1, l2 = i + 1, r2 = n;
                //l1 and r1 find first index s.t. <= k
                //l2 and r2 find last index s.t. >= k
                while(l1 != r1) {
                    int m = (l1 + r1) / 2;
                    if(tree.query(i,m) <= k) {
                        r1 = m;
                    } else {
                        l1 = m + 1;
                    }
                }
                while(l2 != r2) {
                    int m = (l2 + r2 + 1) / 2;
                    if(tree.query(i,m) >= k) {
                        l2 = m;
                    } else {
                        r2 = m - 1;
                    }
                }
                // cout << "i : " << i << " l1 : " << l1 << " l2 : " << l2 << '\n';
                res += l2 - l1 + 1;
            }
        }
        return res;
    }
};

