        if (l==r){
            t[id].sum=a[l];
            return;
        }
        ll mid=(l+r)/2;
        build(2*id,l,mid,a);
        build(2*id+1,mid+1,r,a);
        t[id]=merge(t[2*id],t[2*id+1]);

    }
    void update(ll id,ll l,ll r,ll pos,ll val){
        if (pos<l || pos>r){
            return;
        }
        if (l==r){
            t[id].sum+=val;
            return;
        }

        ll mid=(l+r)/2;
        update(2*id,l,mid,pos,val);
        update(2*id+1,mid+1,r,pos,val);
        t[id]=merge(t[2*id],t[2*id+1]);

