    node query(ll id,ll l,ll r,ll lq,ll rq){
        if (lq>r || rq<l){
            return node();
        }
        if (lq<=l && r<=rq){
            return t[id];

        }
        ll mid=(l+r)/2;
        return merge(query(2*id,l,mid,lq,rq),query(2*id+1,mid+1,r,lq,rq));

