template <typename ValueType>
class RMQ {
 private:
  using Operator = std::function<ValueType(const ValueType&, const ValueType&)>;

  int n_;
  std::vector<std::vector<ValueType>> a_;
  std::vector<int> lg_;
  Operator op_;

 public:
  RMQ(const std::vector<ValueType>& a, const Operator& op)
      : n_(a.size()), op_(op) {
    lg_.resize(n_ + 1);
    lg_[1] = 0;
    for (int i = 2; i <= n_; ++i)
      lg_[i] = lg_[i >> 1] + 1;

    a_.resize(n_);
    for (int i = 0; i < n_; ++i) {
      a_[i].resize(lg_[n_] + 1);
      a_[i][0] = a[i];
    }
    for (int j = 1; j <= lg_[n_]; ++j) {
      int w = (1 << (j - 1));
      for (int i = 0; i + w < n_; ++i) {
        a_[i][j] = op_(a_[i][j - 1], a_[i + w][j - 1]);
      }
    }
  }

  const ValueType Query(int l, int r) const {
    int k = lg_[r - l + 1];
    return op_(a_[l][k], a_[r - (1 << k) + 1][k]);
  }
};

class Solution {
public:
    long long countSubarrays(vector<int>& a, int k) {
        const int n = a.size();
        RMQ<int> rmq(a, [](int x, int y) { return x & y; });

        auto get_l = [&](int i) {
            int l = 0, r = i, res = n;
            while (l <= r) {
                int mid = (l + r) >> 1;
                if (rmq.Query(mid, i) >= k)
                    r = mid - 1, res = mid;
                else
                    l = mid + 1;
            }

            return res;
        };

        auto get_r = [&](int i) {
            int l = 0, r = i, res = -1;
            while (l <= r) {
                int mid = (l + r) >> 1;
                if (rmq.Query(mid, i) <= k)
                    l = mid + 1, res = mid;
                else
                    r = mid - 1;
            }
            return res;
        };

        long long ans = 0;
        for (int i = 0; i < n; ++i) {
            int l = get_l(i);
            int r = get_r(i);

            if (l <= r) ans += r - l + 1;
        }
        return ans;
    }
};

class Solution {
public:
    static constexpr int MAX_LOG = 30;
    deque<int> s[MAX_LOG];

    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();

        long long res = 0;

        for (int i = 0; i < MAX_LOG; i++) s[i].clear();


        for (int i = 0; i < n; i++) {
            for (int j = 0; j < MAX_LOG; j++) {
                if (nums[i] & (1 << j)) continue;
                s[j].push_back(i);
            }
        }

        for (int i = 0; i < n; i++) {
            if ((nums[i] & k) != k) continue;

            int high = n;
            int low = i;

            for (int j = 0; j < MAX_LOG; j++) {
                if (k & (1 << j)) {
                    while (!s[j].empty() && s[j].front() < i) {
                        s[j].pop_front();
                    }
                    if (!s[j].empty()) {
                        high = min(high, s[j].front());
                    }
                } else {
                    while (!s[j].empty() && s[j].front() < i) {
                        s[j].pop_front();
                    }
                    if (!s[j].empty()) {
                        low = max(low, s[j].front());
                    } else {
                        low = n;
                    }
                }
            }
            res += max(0, high - low);
        }

        return res;
    }
};

