class Solution {
public:
    long long countSubarrays(vector<int>& A, int K) {
        ll N = A.size();
        vector<vector<ll>> pre(N, vector<ll>(30));
        for(ll i = 0; i < N; ++i) {
            for(ll bit = 0; bit < 30; ++bit) if(A[i] & (1LL << bit)) {
                pre[i][bit]++;
            }
            if(i == 0) continue;
            for(ll bit = 0; bit < 30; ++bit)
                pre[i][bit] += pre[i - 1][bit];
        }
        auto g = [&] (ll l, ll r) -> ll {
            if(r < l) return -1;
            ll ret = 0;
            for(ll bit = 0; bit < 30; ++bit) {
                ll cnt = pre[r][bit];
                if(l)
                    cnt -= pre[l - 1][bit];
                if(cnt == r - l + 1) ret ^= (1LL << bit);
            }
            return ret;
        };
        ll ans = 0;
        for(ll i = 0; i < N; ++i) {
            ll low = 0, high = i;
            ll id = -1;
            while(low <= high) {
                ll mid = (low + high) >> 1;
                if(g(mid, i) >= K) {
                    id = mid;
                    high = mid - 1;
                } else {
                    low = mid + 1;
                }
            }
            low = 0, high = i;
            ll id1 = -1;
            while(low <= high) {
                ll mid = (low + high) >> 1;
                if(g(mid, i) <= K) {
                    id1 = mid;
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }
            if(id != -1) 
                ans += (id1 - id + 1);
        }
        return ans;
    }
};

