class Solution {

    private int and(int l , int r) {
        int ans = 0;
        for (int i = 0;i <= 30;i ++) {
            long all = countAcc[r][i];
            if (l - 1 >= 0) {
                all -= countAcc[l - 1][i];
            }
            if (all == r - l + 1) {
                ans = ans | (1 << i);
            }
        }
        return ans;
    }

    private int lower(int cur , int k) {
        int l = 0 , r = cur + 1;
        while (l < r) {
            int mid = (l + r) / 2;
            if (and(mid , cur) < k) {
                l = mid + 1;
            } else {
                r = mid;
            }
        }
        if (l <= cur && and(l, cur) == k) {
            return l;
        } else {
            return - 1;
        }
    }

    private int upper(int cur , int k) {
        int l = 0 , r = cur + 1;
        while (l < r) {
            int mid = (l + r) / 2;
            if (and(mid , cur) <= k) {
                l = mid + 1;
            } else {
                r = mid;
            }
        }
        if (r - 1 >= 0 && and(r - 1 , cur) == k) {
            return r - 1;
        } else {
            return - 1;
        }
    }

    private long[][] countAcc;

    public long countSubarrays(int[] nums, int k) {
        int i , j , n = nums.length;
        countAcc = new long[n][31];
        for (i = 0;i < n;i ++) {
            for (j = 0;j <= 30;j ++) {
                if ((nums[i] & (1 << j)) != 0) {
                    countAcc[i][j] ++;
                }
            }
            if (i > 0) {
                for (j = 0;j <= 30;j ++) {
                    countAcc[i][j] += countAcc[i - 1][j];
                }
            }
        }
        // check result
        long ans = 0;
        for (i = 0;i < n;i ++) {
            int l = lower(i , k) , r = upper(i , k);
            if (l >= 0 && r >= 0) {
                ans += (r - l + 1);
            }
        }
        return ans;
    }


}

