class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        ll n = nums.size();
        ll count = 0;
        map<ll, ll> freq;

        for (int i = 0; i < n; ++i) {
            map<ll, ll> newFreq;

            if (nums[i] == k) {
                count++;
            }

            newFreq[nums[i]]++;

            for (auto& [key, val] : freq) {
                ll newKey = key & nums[i];
                newFreq[newKey] += val;
                if (newKey == k) {
                    count += val;
                }
            }

            freq = move(newFreq);
        }

        return count;
    }
};

