struct SWAG {
    std::vector<S> ar, sl, sr;
    SWAG() : sl{e()}, sr{e()} {}
    explicit SWAG(const std::vector<S>& v) : sr{e()} {
        const int n = v.size();
        S x = e();
        sl.reserve(n + 1);
        sl.push_back(x);
