        assert(sl.size() != 1 || ar.size() != 0);
        if (sl.size() != 1) {
            sl.pop_back();
        } else {
            const int n = ar.size();
            S x = e();
            for (int i = n - 1; i >= 1; i--) {
                x = op(ar[i], x);
                sl.push_back(x);
            }
            ar.resize(0);
            sr.resize(1);
        }
    }

    S all_prod() { return op(sl.back(), sr.back()); }

    int size() { return (int)sl.size() - 1 + ar.size(); }
};

