class Solution {
private:
    int getAND(int L, int R, vector<int>& LG, vector<int>& nums, vector<vector<int>>& SP) {
        if (L == R)
            return nums[L];

        int d = LG[R - L];
        return SP[d][L] & SP[d][R - (1 << d)];
    }
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        vector<int> LG(n + 1);
        vector< vector<int> > SP(17, vector<int>(n));

        for (int i = 2; i <= n; i++)
            LG[i] = LG[i / 2] + 1;

        for (int i = 0; i + 1 < n; i++)
            SP[0][i] = (nums[i] & nums[i + 1]);

        for (int i = 1; i < 17; i++)
            for (int j = 0; j + (1 << (i - 1)) < n; j++)
                SP[i][j] = (SP[i - 1][j] & SP[i - 1][j + (1 << (i - 1))]);

        long long ans = 0;

        for (int i = 0; i < n; i++)
        {
            int ptr = i;

            while (ptr < n)
            {
                int left = ptr, right = n - 1, curr = 0;
                int target = getAND(i, ptr, LG, nums, SP);

                while (left <= right)
                {
                    int mid = (left + right) / 2;

                    if (getAND(i, mid, LG, nums, SP) == target)
                        curr = mid, left = mid + 1;
                    else
                        right = mid - 1;
                }

                if (target == k)
                    ans += curr - ptr + 1;

                ptr = curr + 1;
            }
        }

        return ans;
    }
};

