struct segt{
    ll sm,mx;
};  

class Segtree{
    vector<segt> seg;
    vector<int> a;
    public:

    void init(ll n,vector<int> b){
        seg.resize(4*n+1);
        a=b;
    }

    void build(ll i,ll l,ll r){
        if(l==r){
            seg[i].sm=a[l];
        }
        else{
            ll mid=(l+r)/2;
            build(2*i,l,mid);
            build(2*i+1,mid+1,r);
            seg[i].sm=seg[2*i].sm & seg[2*i+1].sm;
        }
    }

    ll help(ll i,ll l,ll r,ll st,ll end){
        if (r<st || l>end){
            return (1<<30)-1;
        }
        if(l>=st && r<=end){
            return seg[i].sm;
        }

        ll mid=(l+r)/2;

        return help(2*i,l,mid,st,end) & help(2*i+1,mid+1,r,st,end);
    }
};
class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        ll n=nums.size();
        Segtree ob;
        ob.init(n,nums);
        ob.build(1,0,n-1);
        ll ans=0;
        for(ll i=0;i<n;i++){
            ll l=i,r=n-1,first=-1;
            while(l<=r){
                ll mid=(l+r)/2;
                ll val=ob.help(1,0,n-1,i,mid);
                if(val>k){
                    l=mid+1;
                }
                else if(val<k){
                    r=mid-1;
                }
                else{
                    first=mid;
                    r=mid-1;
                }
            }
            ll last=-1;
            l=i,r=n-1;
            while(l<=r){
                ll mid=(l+r)/2;
                ll val=ob.help(1,0,n-1,i,mid);
                if(val>k){
                    l=mid+1;
                }
                else if(val<k){
                    r=mid-1;
                }
                else{
                    last=mid;
                    l=mid+1;
                }
            }
            if(first!=-1){
                ans+=last-first+1;
            }
        }
        return ans;
    }
};

