            if(l < i) l = i;
            int tmp = sumAll(i, l);
            while(l < n && tmp > k) {
                l++;
                if(l < n) tmp &= nums[l];
            }

            if(r < l) r = l;
            int tmp2 = sumAll(i, r);
            while(r < n && tmp2 >= k) {
                r++;
                if(r < n) tmp2 &= nums[r];
            }
            //cout << l << " " << r << " " << tmp << endl;
            if(tmp < k || l >= n) continue;
            ans += r - l;
        }
        return ans;
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        int has[n + 5][32];
        for(int i = 0; i < n; i++) {
            for(int j = 0; j < 32; j++) {
                if(i > 0) has[i][j] = has[i - 1][j];
                else has[i][j] = 0;
                if(nums[i] & (1 << j)) has[i][j]++;
            }
        }
        auto sum = [&has](int bit, int l, int r) -> int {
            if(l == 0) return has[r][bit];
            return has[r][bit] - has[l - 1][bit];
        };
        auto sumAll = [&sum](int l, int r) -> int {
            int ans = 0;
            for(int i = 0; i < 32; i++) {
                if(sum(i, l, r) == r - l + 1) ans += (1 << i);
            }
            return ans;
        };

        int l = 0, r = 0;
        long long ans = 0;
        for(int i = 0; i < n; i++) {
            if(l < i) l = i;
            int tmp = sumAll(i, l);
            while(l < n && tmp > k) {
                l++;
                if(l < n) tmp &= nums[l];
            }

            if(r < l) r = l;
            int tmp2 = sumAll(i, r);
            while(r < n && tmp2 >= k) {
                r++;
                if(r < n) tmp2 &= nums[r];
            }
            //cout << l << " " << r << " " << tmp << endl;
            if(tmp < k || l >= n) continue;
            ans += r - l;
        }
        return ans;
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& a, int k) {
        long long ans = 0;
        int n = a.size();
        vector<int> one[31], zero[31];
        for(int i=0; i<31; i++){
            one[i].resize(n + 1);
            zero[i].resize(n + 1);
        }

        for(int i=0; i<31; i++){
            one[i][n] = zero[i][n] = n;
        }

        for(int i=n-1; i>=0; i--){
            for(int j=0; j<31; j++){
                one[j][i] = one[j][i + 1];
                zero[j][i] = zero[j][i + 1];
                if(a[i] & (1LL << j))    one[j][i] = i;
                else zero[j][i] = i;
                // cout << zero[j][i] << " ";
            }
            // cout << "\n";
        }

        // cout << zero[0][1] << endl;

        for(int i=0; i<n; i++){
            int l = n - 1, r = i;
            for(int j=0; j<31; j++){
                if(k & (1LL << j)){
                    l = min(l, zero[j][i] - 1);
                }
                else{
                    r = max(r, zero[j][i]);
                }
                // cout << l << " " << r << "\n";
            }

            if((max(l, r) > n - 1) || (l < r) || (min(l, r) < i))  continue;
            ans += l - r + 1;
        }

        return ans;
    }
};

class Solution {
