template<typename T>
class sparseTable {
  public:
    sparseTable(vector<T>& a) {
      n = a.size();
      tab.push_back(a);
      for (int i = 1; 1 <= (n >> i); i++) {
        vector<T> v;
        for (int j = 0; j + (1 << i) <= n; j++) {
          v.push_back(op(tab[i-1][j], tab[i-1][j + (1 << (i-1))]));
        }
        tab.push_back(v);
      }
    }

    T query(int l, int r) {
      if (l > r) swap(l, r);
      int len = r - l + 1;
      int k = lg(len);
      if ((1 << k) == len) return tab[k][l];

      return op(tab[k][l], tab[k][r+1-(1 << k)]);
    }

  private:
    int n;
    vector<vector<T>> tab;

    T op(T& a, T& b) {
      return a & b;
    }

    int lg(int n) {
      return bit_width((unsigned long long) n) - 1;
    }

};


class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();

        sparseTable<int> st(nums);
        long long res = 0;
        for (int i = 0; i < n; i++) {
            int l = i, r = n - 1;

            while (r >= l) {
                int mid = (l + r) / 2;

                if (st.query(i, mid) >= k) l = mid + 1;
                else r = mid - 1;
            }

            int len = l;

            l = i; r = n - 1;

            while (r >= l) {
                int mid = (l + r) / 2;

                if (st.query(i, mid) <= k) r = mid - 1;
                else l = mid + 1;
            }

            len -= l;
            res += len;
        }

        return res;
    }
};

