class Solution {

public:
    long long countSubarrays(vector<int>& A, int k) {
        ll res = 0;
        vall3 B;
        rep(i,0,sz(A)) {
            vall3 now;
            auto add = [&](ll val, ll l, ll r) {
                if(sz(now) and now.back()[0] == val) {
                    now.back()[2] = r;
                } else now.push_back({val,l,r});
