class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        vector<vector<int>> prefixSum(n + 1, vector<int> (30, 0));
        for(int i = 0; i < n; i++) {
            for(int pos = 0; pos < 30; pos++) {
                int bit = (nums[i] & (1 << pos)) > 0 ? 1 : 0;
                prefixSum[i + 1][pos] = prefixSum[i][pos] + (bit);
            }
        }

        auto get_and = [&] (int i, int j) -> int {
            int res = 0;
            for(int pos = 0; pos < 30; pos++) {
                if(prefixSum[j + 1][pos] - prefixSum[i][pos] == (j + 1 - i)) {
                    res |= (1 << pos);
                }
            }

            return res;
        };

        auto count_gte_k = [&] (int i, int x) -> int {
            int left = i, right = n - 1, ans = i - 1;
            while(left <= right) {
                int mid = left + (right - left) / 2;
                if(get_and(i, mid) >= x) {
                    ans = mid;
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }

            return ans - i + 1;
        };

        long long count = 0;
        for(int i = 0; i < n; i++) {
            count += count_gte_k(i, k) - count_gte_k(i, k + 1);
        }
        return count;
    }
};

