class Solution {
public:
template<typename T, bool maximum_mode = false>
struct RMQ {
    static int highest_bit(unsigned x) {
        return x == 0 ? -1 : 31 - __builtin_clz(x);
    }

    int n = 0;
    vector<T> values;
    vector<vector<int>> range_low;

    RMQ(const vector<T> &_values = {}) {
        if (!_values.empty())
            build(_values);
    }

    void build(const vector<T> &_values) {
        values = _values;
        n = int(values.size());
        int levels = highest_bit(n) + 1;
        range_low.resize(levels);

        for (int k = 0; k < levels; k++)
            range_low[k].resize(n - (1 << k) + 1);

        for (int i = 0; i < n; i++)
            range_low[0][i] = _values[i];

        for (int k = 1; k < levels; k++)
            for (int i = 0; i <= n - (1 << k); i++)
                range_low[k][i] = range_low[k - 1][i] & range_low[k - 1][i + (1 << (k - 1))];
    }

    // Note: breaks ties by choosing the largest index.
    int query(int a, int b) const {
        assert(0 <= a && a < b && b <= n);
        int level = highest_bit(b - a);
        return range_low[level][a] & range_low[level][b - (1 << level)];
    }
};

    long long countSubarrays(vector<int>& nums, int k) {
        using ll = long long;

        int n = (int)nums.size();
        RMQ<int> rmq(nums);
        ll ans = 0;
        for (int i = 0; i < n; i++) {
            int lo = i, hi = n;
            while (lo < hi) {
                int mid = (lo + hi) >> 1;
                if (rmq.query(i, mid + 1) <= k)
                    hi = mid;
                else lo = mid + 1;
            }
            if (lo == n)
                continue;
            if (rmq.query(i, lo + 1) != k)
                continue;
            int lft = lo;
            lo = i, hi = n - 1;
            while (lo < hi) {
                int mid = (lo + hi + 1) >> 1;
                if (rmq.query(i, mid + 1) >= k)
                    lo = mid;
                else hi = mid - 1;
            }
            int rgt = lo;
            ans += rgt - lft + 1;
        }
        return ans;

    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& a, int k) {
            using ll = long long;
    int n = a.size();
    int L = 32;
    vector<vector<int>> pf(n, vector<int>(L, 0));
    for (int i = 0; i < n; i++) {
        for (int bit = 0; bit < L; bit++) {
            if ((a[i] >> bit) & 1)
                pf[i][bit] = 1;
        }
    }
    for (int i = 1; i < n; i++) {
        for (int bit = 0; bit < L; bit++) {
            pf[i][bit] += pf[i - 1][bit];
        }
    }
    ll ans = 0;
    for (int i = 0; i < n; i++) {
        if ((a[i] & k) != k)
            continue;
        int from = -1;
        int till = n - 1;
        int l = i, r = n - 1;
        while (l <= r) {
            int mid = l + (r - l) / 2;
            int val = 0;
            for (int bit = 0; bit < L; bit++) {
                int cnt = pf[mid][bit];
                if (i)
                    cnt -= pf[i - 1][bit];
                if (cnt == mid - i + 1)
                    val += (1ll << bit);
            }
            if (val == k)
                from = mid;
            if (val > k) {
                l = mid + 1;
            } else {
                r = mid - 1;
            }
        }
        l = i, r = n - 1;

        while (l <= r) {
            int mid = l + (r - l) / 2;
            int val = 0;
            for (int bit = 0; bit < L; bit++) {
                int cnt = pf[mid][bit];
                if (i)
                    cnt -= pf[i - 1][bit];
                if (cnt == mid - i + 1)
                    val += (1ll << bit);
            }
            if (val == k)
                till = mid;
            if (val >= k) {
                l = mid + 1;
            } else {
                r = mid - 1;
            }
        }
        if (from == -1)
            continue;
        ans += (till - from + 1);
    }
    return ans;
    }
};

class SparseTable {
 public:
    explicit SparseTable(const vector<int>& nums, const function<int(int, int)>& func, int init) : func_(func), init_(init) {
        Build(nums);
    }

    int Query(int lq, int rq) {
        if (lq > rq) return init_;
        int l = log2(rq - lq + 1);
        return func_(sparse_table_[lq][l], sparse_table_[rq - (1 << l) + 1][l]);
    }

 private:
    function<int(int, int)> func_;
    int init_;
    vector<vector<int>> sparse_table_;

    void Build(const vector<int>& nums) {
        const int n = nums.size();
        const int l = log2(n);
        sparse_table_.resize(n);
        for (int i = 0; i < n; ++i) {
            sparse_table_[i].resize(l + 1, init_);
        }
        for (int i = 0; i < n; ++i) {
            sparse_table_[i][0] = nums[i];
        }
        for (int j = 1; (1 << j) <= n; ++j) {
            for (int i = 0; (i + (1 << j)) <= n; ++i) {
                sparse_table_[i][j] = func_(sparse_table_[i][j - 1], sparse_table_[i + (1 << (j - 1))][j - 1]);
            }
        }
    }
};

