            return (x & y);
        }, INT_MAX);
        long long ans = (nums[0] == k ? 1 : 0);
        for (int r = 1; r < n; ++r) {
            int x = 0, y = r;
            while (x < y) {
                int mid = (x + y) / 2;
                int result = sparse_table.Query(mid, r);
                if (result < k) {
                    x = mid + 1;
                } else {
                    y = mid;
                }
