        Map<Integer, Long> cur = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            Map<Integer, Long> next = new HashMap<>();
            for (Map.Entry<Integer, Long> e : cur.entrySet()) {
                int r = e.getKey().intValue() & nums[i];
                if (r == k) result += e.getValue();
                next.merge(r, e.getValue(), Long::sum);
            }
            if (nums[i] == k) result++;
            next.merge(nums[i], 1L, Long::sum);
            cur = next;
        }

        return result;

    }
}

class SGTree {
  vector<int> sg;
  int n;
public:
  SGTree(int n, vector<int> &vec) {
    this->n = n;
    sg = vector<int> (4 * n);
    build(0, 0, n-1, vec);
  }
  void build(int i, int l, int r, vector<int> &vec) {
    if(l == r) {
      sg[i] = vec[l];
      return;
    }
    int m = (l + r)/2;
    build(2*i+1, l, m, vec), build(2*i+2, m+1, r, vec);
    sg[i] = (sg[2*i+1] & sg[2*i+2]);
  }
  int query(int L, int R, int i, int l, int r) {
    if(r < L || R < l) return INT_MAX;
    if(L <= l && r <= R) return sg[i];
    int m = (l + r)/2;
    return (query(L, R, 2*i+1, l, m) & query(L, R, 2*i+2, m+1, r));
  }
  int query(int L, int R) {
    return query(L, R, 0, 0, n-1);
  }
};

class Solution {
public:
  long long countSubarrays(vector<int>& nums, int k) {

    long long ans = 0;

    int n = nums.size();

    SGTree sg(n, nums);

    for(int i = 0; i < n; i++) {

      long long ind1 = -1, ind2 = -1;

      long long l = i, r = n-1;

      while(l <= r) {
        int m = (l + r)/2;

        int x = sg.query(i, m);

        if(x < k) r = m - 1;
        else if(x > k) l = m + 1;
        else {
          ind1 = m;
          r = m - 1;
        }

      }

      l = i, r = n-1;
      while(l <= r) {
        int m = (l + r)/2;

        int x = sg.query(i, m);

        if(x < k) r = m - 1;
        else if(x > k) l = m + 1;
        else {
          ind2 = m;
          l = m + 1;
        }
      }

      if(ind1 != -1) ans += ind2 - ind1 + 1;
    }

    return ans;
  }
};

