class Solution {
public:
    int query(vector<int> &tree, int l, int r) {
        l += sz(tree) / 2; r += sz(tree) / 2;
        int res = (1 << 30) - 1;
        while (l <= r) {
            if (l % 2 == 1) {
                res &= tree[l];
                l >>= 1;
                l++;
            } else {
                l >>= 1;
            }
            if (r % 2 == 0) {
                res &= tree[r];
                r >>= 1;
                r--;
            } else {
                r >>= 1;
            }
        }
        return res;
    }
    int search1(vector<int> &tree, int k, int i, int l, int r) {
        if (l > r) return -1;
        int mid = (l + r) / 2;
        if (query(tree, i, mid) <= k) {
            int m = search1(tree, k, i, l, mid - 1);
            if (m == -1) return mid;
            return m;
        }
        return search1(tree, k, i, mid + 1, r);
    }
    int search2(vector<int> &tree, int k, int i, int l, int r) {
        if (l > r) return -1;
        int mid = (l + r) / 2;
        if (query(tree, i, mid) >= k) {
            int m = search2(tree, k, i, mid + 1, r);
            if (m == -1) return mid;
            return m;
        }
        return search2(tree, k, i, l, mid - 1);
    }
    long long countSubarrays(vector<int>& nums, int k) {
        int N = sz(nums);
        int M = 1; while (M < sz(nums)) M <<= 1;
        vector<int> tree(M * 2, (1 << 30) - 1);
        for (int i = 0; i < sz(nums); i++) {
            tree[i + M] = nums[i];
        }
        for (int i = M - 1; i > 0; i--) {
            tree[i] = tree[i * 2] & tree[i * 2 + 1];
        }
        ll res = 0;
        for (int i = 0; i < N; i++) {
            int l = search1(tree, k, i, i, sz(nums) - 1);
            int r = search2(tree, k, i, i, sz(nums) - 1);
            if (l != -1 && r != -1 && l <= r) res += r - l + 1;
        }
        return res;
    }
};

