            ll low, high;
            if (vals[i] == k) low = 1;
            else low = lbd(lbd,i,n-1,i);
            if (low != -1ll && st.query(i,n) == k) high = n-1ll-i+1ll;
            else if (low != -1ll) high = ubd(ubd,i,n-1ll,i);
            else high = -1ll;
            debug(i);
            debug(low);
            debug(high);
            if (low == -1ll) continue;
            assert(low != -1ll && high != -1ll);
            assert(low <= high);
            sol += high-low+1ll;
        }
        return sol;
    }
};

class Sparse {
    vector<vector<int>> table;
    int n;
    int K;

    int combine(int l, int r) { return l & r; }

   public:
    Sparse(const vector<int> &v) {
        n = (int)v.size();
        K = log2(n) + 1;
        table.assign(n, vector<int>(K, 0));

        for (int i = 0; i < n; ++i) table[i][0] = v[i];

        for (int j = 1; j < K; ++j) {
            for (int i = 0; i + (1 << j) <= n; ++i) {
                table[i][j] = combine(table[i][j - 1], table[i + (1 << (j - 1))][j - 1]);
            }
        }
    }

    int query(int l, int r) {
        const int width = r - l + 1;
        long long k = log2(width);
        int res = combine(table[r - (1 << k) + 1][k], table[l][k]);
        return res;
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& a, int k) {
        Sparse st(a);
        long long res = 0;
        const int n = a.size();
        for (int i = 0; i < n; i++) {
            int l = i, r = n - 1, mid, j1 = -1, j2 = -1;
            while (l <= r) {
                mid = (l + r) / 2;
                if (st.query(i, mid) > k) l = mid + 1;
                else j1 = mid, r = mid - 1;
            }
            if (j1 == -1 or st.query(i, j1) != k) continue;
            l = i, r = n - 1;
            while (l <= r) {
                mid = (l + r) / 2;
                if (st.query(i, mid) >= k) l = mid + 1, j2 = mid;
                else r = mid - 1;
            }
            res += 1ll * (j2 - j1 + 1);
        }
        return res;
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = (int)nums.size();
        int pref[n][30];
        for(int b = 0; b < 30; b ++){
            int c = 0;
            for(int i = 0; i < n; i ++){
                if(nums[i] & (1<<b)){
                    c ++;
                }
                else{
                    c = 0;
                }
                pref[i][b] = c;
            }
        }
        long long ans = 0;
        for(int i = 0; i < n; i ++){
            int len1 = i + 1;
            for(int b = 0; b < 30; b ++){
                if(k & (1 << b)){
                    len1 = min(len1, pref[i][b]);
                }
            }
            int len2 = 0;
            for(int b = 0; b < 30; b ++){
                if((k & (1 << b)) == 0){
                    len2 = max(len2, pref[i][b]);
                }
            }
            ans += max(0, len1 - len2);
        }
        return ans;
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        vector<int> last(30, -1);
        long long ans = 0;
        int n = nums.size(), m = 1;
        vector<int> p(30);
        for (int j = 0; j < 30; j++) {
            p[j] = m, m <<= 1;
        }
        vector<int> kb(30);
        for (int j = 0; j < 30; j++) {
            if (k & p[j]) {
                kb[j] = true;
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 30; j++) {
                if (!(nums[i] & p[j])) {
                    last[j] = i;
                }
            }
            int l = -1, r = 1e9;
            for (int j = 0; j < 30; j++) {
                if (kb[j]) {
                    l = max(l, last[j]);
                } else {
                    r = min(r, last[j]);
                }
            }
            ans += max(0, r - l);
        }
        return ans;
    }
};

class Solution {
    public long countSubarrays(int[] nums, int k) {
        long count = 0;
        int n = nums.length;

        // Map to store the current AND results and their frequencies
        Map<Integer, Integer> andMap = new HashMap<>();

        for (int num : nums) {
            // Create a new map for the new set of AND results
            Map<Integer, Integer> newAndMap = new HashMap<>();

            // Initialize with the current number
            if (num == k) {
                count++;
            }
            newAndMap.put(num, newAndMap.getOrDefault(num, 0) + 1);

            // Update the AND results based on the previous map
            for (int key : andMap.keySet()) {
                int newAnd = key & num;
                if (newAnd == k) {
                    count += andMap.get(key);
                }
                newAndMap.put(newAnd, newAndMap.getOrDefault(newAnd, 0) + andMap.get(key));
            }

            // Move to the new map
            andMap = newAndMap;
        }

        return count;
    }
}

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        // 30

        stack<int> s[30];
        int n = nums.size();

        int R[n][30];

        for(int i = 0; i != n; ++i)
            fill(R[i], R[i] + 30, n);

        int t;
        for(int i = 0; i != n; ++i) {
            t = nums[i];
            for(int j = 0; j != 30; ++j) {
                if(~t & 1) {
                    while(!s[j].empty()) {
                        R[s[j].top()][j] = i;
                        s[j].pop();
                    }
                    R[i][j] = i;
                }
                else {
                    s[j].push(i);
                }

                t >>= 1;
            }
        }

        bitset<30> b = k;

        long res = 0;
        int l, r;
        for(int st = 0; st != n; ++st) {
            l = st, r = n - 1;

            // cout << "st = " << st << "\n";

            for(int j = 0; j != 30 && l <= r; ++j) {
                if(!b[j]) {
                    l = max(l, R[st][j]); 
                }
                else {
                    r = min(r, R[st][j] - 1);
                }
            }

            // cout << "  " << l << ", " << r << "\n";

            // cout << "  += " << r - l + 1 << "\n";
            if(l <= r)
                res += r - l + 1;
        }

        return res;
    }
};

class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        def get_nums(bits, length):
            res = 0
            for i in range(32):
                if bits[i] == length:
                    res |= (1 << i)
            return res
        c1, c2 = [0]*32, [0]*32
        p1, p2 = 0, 0
        n = len(nums)
        res = 0
        for r, num in enumerate(nums):
            if num & k != k:
                c1, c2 = [0]*32, [0]*32
                p1, p2 = r+1, r+1
                continue
            for i in range(32):
                if (num >> i) & 1:
                    c1[i] += 1
                    c2[i] += 1
            while get_nums(c2, r - p2 + 1) == k:
                for i in range(32):
                    if (nums[p2] >> i) & 1:
                        c2[i] -= 1
                p2 += 1
            if get_nums(c1, r - p1 + 1) == k:
                res += p2 - p1
        return res

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();

        vector<array<int, 30>> P(n);
        for (int i = 0; i < n; ++i) {
            auto a = nums[i];
            for (int j = 0; j < 30; ++j) {
                if (1 << j & a) ++P[i][j];
                if (i > 0) P[i][j] += P[i - 1][j];
            }
        }

        // P[i][j] = # of set j-th bits in the subarray nums[0:i + 1]

        // computes &A[l : r + 1]
        const auto get_subarray_and = [&](auto l, auto r) {
            int res = 0, required = r - l + 1;
            for (int i = 0; i < 30; ++i) {
                if (P[r][i] - (l == 0 ? 0 : P[l - 1][i]) == required)
                    res += 1 << i;
            }
            return res;
        };

        const auto bs1 = [&](auto i) {
            int l = i, r = n - 1;

            const auto ok = [&](auto m) {
                return get_subarray_and(i, m) >= k;
            };

            while (l < r) {
                auto m = l + (r - l) / 2;
                if (ok(m)) l = m + 1;
                else r = m;
            }

            return ok(l) ? l : l - 1;
        };

        const auto bs2 = [&](auto i) {
            int l = i, r = n - 1;

            const auto ok = [&](auto m) {
                return get_subarray_and(i, m) <= k;
            };

            while (l < r) {
                auto m = l + (r - l) / 2;
                if (ok(m)) r = m;
                else l = m + 1;
            }

            return l;
        };


        auto res = 0LL;
        for (int i = 0; i < n; ++i) {
            auto a = bs2(i);
            auto b = bs1(i);
            res += a >= 0 && b < n && a <= b && get_subarray_and(i, a) == k ? b - a + 1 : 0;
        }

        return res;
    }
};

class Solution {
public:
  long long countSubarrays(vector<int>& nums, int k) {
    int n = nums.size();
    vector<vector<int>> o(32, vector<int>(n + 1, n));
    vector<vector<int>> z(32, vector<int>(n + 1, n));
    for (int i = n; i-- > 0; ) {
      for (int j = 0; j < 32; ++j) {
        if ((nums[i] >> j) & 0x01) {
          o[j][i] = o[j][i + 1] + 1;
          z[j][i] = z[j][i + 1];
        } else {
          o[j][i] = 0;
          z[j][i] = i;
        }
      }
    }
    long long ret = 0;
    for (int i = 0; i < n; ++i) {
      int l = 0, r = n - i;
      for (int j = 0; j < 32; ++j) {
        if ((k >> j) & 0x01) {
          r = min(r, o[j][i]);
        } else {
          l = max(l, z[j][i]);
        }
      }
      if (r > l - i) ret += r - (l - i);
    }
    return ret;
  }
};

