class Solution {
public:

    long long Count_Less_Than(std::vector<int>& nums, int target){

        int back_idx = 0;
        int current_bit_mask = 0;
        std::vector<int> bit_counts(32, 0);
        long long result = 0;

        for(int i = 0; i < nums.size(); i++){

            int idx = 0;
            while((1 << idx) <= nums[i]){
                if((1 << idx) & nums[i]) bit_counts[idx]++;
                idx++;
            }

            for(int j = 0; j < bit_counts.size(); j++){
                if(bit_counts[j] == i - back_idx + 1){
                    current_bit_mask |= (1 << j);
                }else{
                    current_bit_mask &= ~(1 << j);
                }
            }

            while(current_bit_mask <= target && back_idx <= i){

                result += nums.size() - i;
                idx = 0;

                while((1 << idx) <= nums[back_idx]){
                    if((1 << idx) & nums[back_idx]) bit_counts[idx]--;
                    idx++;
                }

                back_idx++;

                for(int j = 0; j < bit_counts.size(); j++){
                    if(bit_counts[j] == i - back_idx + 1){
                        current_bit_mask |= (1 << j);
                    }else{
                        current_bit_mask &= ~(1 << j);
                    }
                }   
            }
        }        

        return result;
    }

    long long countSubarrays(std::vector<int>& nums, int k) {

        if(k == 0){
            return Count_Less_Than(nums, k);
        }

        return Count_Less_Than(nums, k) - Count_Less_Than(nums, k-1);
    }
};

class segtree {
public:
	vector<int> sgt;
	segtree(int n) {
		sgt.resize(4 * n + 1);
	}

	void build(int index , int low , int high , vector<int>& arr) {
		if (low == high) {
			sgt[index] = arr[low];
			return;
		}
		int mid = (low + high) >> 1;

		build(2 * index + 1 , low , mid , arr);
		build(2 * index + 2 , mid + 1, high , arr);

		sgt[index] = (sgt[2 * index + 1] & sgt[2 * index + 2]);
	}
	int query(int index , int low , int high , int l ,  int r) {
		if (low >= l and high <=  r) {
			return sgt[index];
		}
		if (l > high or r < low) {
			return INT_MAX;
		}

		int mid = (low + high) >> 1;

		int left = query(2 * index + 1 , low , mid , l , r);
		int right = query(2 * index + 2 , mid + 1 , high , l , r);

		return (left & right);
	}
};



class Solution {
public:
    long long countSubarrays(vector<int>& a, int k) {
        int n = a.size();
        segtree ob(n);
        ob.build(0 , 0 , n - 1 , a);
        long long ans = 0;
        for(int i = 0; i < n; i++) {
            int lb = -1 , ub = -1;
            int low = i;
            int high = n - 1;
            while(low <= high) {
                int mid = (low + high) >> 1;
                int rangeAnd = ob.query(0 , 0 , n - 1 , i , mid);
                if(rangeAnd > k) {
                    low = mid + 1;
                }
                else if(rangeAnd < k) {
                    high = mid - 1;
                }
                else {
                    lb = mid;
                    high = mid - 1;
                }
            }
            low = i;
            high = n - 1;
            while(low <= high) {
                int mid = (low + high) >> 1;
                int rangeAnd = ob.query(0 , 0 , n - 1 , i , mid);
