class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        long long ans = 0;
        nums.push_back(0);
        sparse_table<int, merge> sp(nums);
        for (int i = 0; i < n; i ++){
            int left1 = i, right1 = n;
            while(left1 < right1){
                int mid = (left1 + right1) / 2;
                int val = sp.query(i, mid);
                if (val == k or (val & k) < k){
                    right1 = mid;
                }
                else{
                    left1 = mid + 1;
                }
            }

            int left2 = i, right2 = n;
            while(left2 < right2){
                int mid = (left2 + right2 + 2) / 2;
                int val = sp.query(i, mid);
                if ((val & k) < k){
                    right2 = mid - 1;
                }
                else{
                    left2 = mid;
                }
            }

            int S = sp.query(i, left1);
            if (S == k and k != 0){
                ans += (left2 - left1 + 1);
            }
            else if (S == k){
                ans += (left2 - left1 + 1);
                if (left2 == n)
                    ans --;
            }
        }

        nums.pop_back();
        return ans;
    }
};

