class Solution {
    public long countSubarrays(int[] nums, int k) {
        int N = nums.length;
        BitSet[] bits = new BitSet[30];
        for (int i = 0; i < 30; ++i) {
            bits[i] = new BitSet();
        }

        for (int i = 0; i < N; ++i) {
            int v = nums[i];
            for (int p = 0; p < 30; ++p) {
                if (v % 2 == 1) bits[p].set(i);
                v >>= 1;
            }
        }

        long count = 0;
        for (int start = 0; start < N; ++start) {
            int end = N;
            int K = k;
            for (int p = 0; p < 30; ++p) {
                if (K % 2 == 1) {
                    end = Math.min(end, bits[p].nextClearBit(start));
                }
                K >>= 1;
            }
            // Verification
            int middle = start;
            K = k;
            for (int p = 0; p < 30 && end > start; ++p) {
                if (K % 2 == 0) {
                    middle = Math.max(middle, bits[p].nextClearBit(start));
                }
                K >>= 1;
            }
            if (end > middle) {
                count += end - middle;
            }
        }

        return count;
    }
}

