class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        vector<vector<int>> pref(nums.size(), vector<int>(31));
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < 31; ++j) {
                if (nums[i] & (1 << j)) pref[i][j] = 1;
                if (i) pref[i][j] += pref[i - 1][j];
            }
        }
        auto get_and = [&](int l, int r) -> int {
            int ans = 0;
            for (int i = 0; i < 31; ++i) {
                int count = pref[r][i];
                if (l) count -= pref[l - 1][i];
                if (count == r - l + 1) ans |= 1 << i;
            }
            return ans;
        };
        long long ans = 0;
        for (int i = 0; i < n; ++i) {
            // let f(i, mid) = whether AND(i,mid) is supermask of k
            // f(i, mid) is monontonic
            int l = i, r = n - 1, pos = -1;
            if ((nums[i] & k) != k) continue;
            while (l <= r) {
                int mid = (l + r) >> 1;
                int AND = get_and(i, mid);
                if ((AND & k) == k) {
                    l = mid + 1;
                    pos = mid;
                } else {
                    r = mid - 1;
                }
            }
            if (pos == -1 || get_and(i, pos) != k) continue;
            // another binary search for first true
            l = i, r = pos;
            int fin;
            while (l <= r) {
                int mid = (l + r) >> 1;
                if (get_and(i, mid) == k) {
                    r = mid - 1;
                    fin = mid;
                } else {
                    l = mid + 1;
                }
            }
            ans += pos - fin + 1;
        }
        return ans;
    }
};

