template<typename T>
class RMQ {
public:
    vector<vector<T>> st;
    function<T(T, T)> op;
    int n, m;

    RMQ(const vector<T>& a, function<T(T, T)> _op) {
        n = (int)a.size(); m = __lg(n) + 1; // ceil(log(r - l + 1))
        st = vector<vector<T>>(n, vector<T>(m));
        op = _op;
        int p = 1;
        for(int j = 0; j < m; j++) {
            for(int i = 0; i + p - 1 < n; i++) {
                if(j == 0) st[i][j] = a[i];
                else st[i][j] = op(st[i][j - 1], st[i + (p >> 1)][j - 1]);
            }
            p *= 2;
        }
    }

    T query(int l, int r) {
        int sz = __lg(r - l + 1); // floor(log(r - l + 1))
        return op(st[l][sz], st[r + 1 - (1 << sz)][sz]);
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& a, int k) {
        const int n = (int)a.size();
        RMQ<int> rmq(a, [](int x, int y) -> int { return (x & y); });

        auto gr = [&](int i) -> int64_t {
            int l = i - 1, r = n;
            while (r - l > 1) {
                int m = l + (r - l) / 2;
                if (rmq.query(i, m) > k)
                    l = m;
                else 
                    r = m;
            }
            if (l == i - 1)
                return 0;
            else
                return l - i + 1;
        };

        auto ls = [&](int i) -> int64_t {
            int l = i - 1, r = n;
            while (r - l > 1) {
                int m = l + (r - l) / 2;
                if (rmq.query(i, m) < k) 
                    r = m;
                else
                    l = m;
            }
            if (r == n)
                return 0;
            else 
                return n - r;
        };

        int64_t ans = 0;
        for (int i = 0; i < n; i++) {
            ans += max((int64_t) 0, n - i - ls(i) - gr(i));
        }
        return ans;
    }
};

