        for (int i = 0; i < n; ++i) {
            int L1 = i, R1 = n - 1;
            while (L1 < R1) {
                int x = (L1 + R1 + 1) / 2;
                if (seg.rangeQuery(i, x)._and > k) {
                    L1 = x;
                } else {
                    R1 = x - 1;
                }
            }
            int L2 = i, R2 = n - 1;
            while (L2 < R2) {
                int x = (L2 + R2) / 2;
                if (seg.rangeQuery(i, x)._and < k) {
                    R2 = x;
                } else {
                    L2 = x + 1;
                }
            }
            if (seg.rangeQuery(i, L1)._and > k) {
                L1++;
            }
            if (seg.rangeQuery(i, L2)._and < k) {
                L2--;
            }
            // cout << L1 << " " << L2 << "\n";
            if (L1 <= L2 && seg.rangeQuery(i, L1)._and == k && seg.rangeQuery(i, L2)._and == k) {
                ans += L2 - L1 + 1;
            }
        }
        return ans;
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = (int)nums.size();
        const int K = 20;

        vector<vector<int>> a(n, vector<int>(K));
        for (int i = 0; i < n; i++) {
            a[i][0] = nums[i];
        }
        for (int j = 1; j < K; j++) {
            for (int i = 0; i + (1 << j) - 1 < n; i++) {
                a[i][j] = (a[i][j - 1] & a[i + (1 << (j - 1))][j - 1]);
            }
        }

        auto get = [&](int l, int r) -> int {
            int len = r - l + 1;
            int L = __lg(len);
            return (a[l][L] & a[r - (1 << L) + 1][L]);
        };

        long long ans = 0;
        int r1 = 0, r2 = 0;
        for (int l = 0; l < n; l++) {
            r1 = max(r1, l);
            while (r1 < n && get(l, r1) > k) r1++;
            r2 = max(r2, r1);
            while (r2 < n && get(l, r2) >= k) r2++;

            if (r1 < n && get(l, r1) == k) {
                ans += r2 - r1;
            }
        }

        return ans;
    }
};

class SegmentTree {
private:
    std::vector<int> tree;
    int n;

    void buildTree(const std::vector<int>& nums, int start, int end, int node) {
        if (start == end) {
            tree[node] = nums[start];
        } else {
            int mid = start + (end - start) / 2;
            buildTree(nums, start, mid, 2 * node + 1);
            buildTree(nums, mid + 1, end, 2 * node + 2);
            tree[node] = tree[2 * node + 1] & tree[2 * node + 2];
        }
    }

    int query(int start, int end, int L, int R, int node) {
        if (start > R || end < L) {
            return -1;
        }
        if (start >= L && end <= R) {
            return tree[node];
        }
        int mid = start + (end - start) / 2;
        int left = query(start, mid, L, R, 2 * node + 1);
        int right = query(mid + 1, end, L, R, 2 * node + 2);
        if (left == -1) return right;
        if (right == -1) return left;
        return left & right;
    }

public:
    SegmentTree(const std::vector<int>& nums) {
        n = nums.size();
        tree.resize(4 * n);
        buildTree(nums, 0, n - 1, 0);
    }

    int rangeAnd(int L, int R) {
        return query(0, n - 1, L, R, 0);
    }
};


