class SegmentTree {
private:
    vector<int> tree;
    int n;

public:
    SegmentTree(vector<int>& nums) {
        n = nums.size();
        tree.resize(2 * n);

        // Build the segment tree
        // Initialize leaves of the tree
        for (int i = 0; i < n; ++i) {
            tree[n + i] = nums[i];
        }

        // Build the rest of the tree by calculating bitwise AND of parents
        for (int i = n - 1; i > 0; --i) {
            tree[i] = tree[2 * i] & tree[2 * i + 1];
        }
    }

    // Update the value at index idx to val
    void update(int idx, int val) {
        // Update the leaf node
        idx += n;
        tree[idx] = val;

        // Update the rest of the tree
        while (idx > 1) {
            idx /= 2;
            tree[idx] = tree[2 * idx] & tree[2 * idx + 1];
        }
    }

    // Get bitwise AND of elements from index l to r (inclusive)
    int rangeBitwiseAnd(int l, int r) {
        l += n;
        r += n;
        int res = tree[l];

        while (l <= r) {
            if (l % 2 == 1) {
                res &= tree[l];
                l++;
            }
            if (r % 2 == 0) {
                res &= tree[r];
                r--;
            }
            l /= 2;
            r /= 2;
        }

        return res;
    }
};
class Solution {
