            long long mini = nums.size();
            while(low<=high){
                int mid = (low+high)/2;
                if(st.rangeBitwiseAnd(i,mid)>k){
                    low=mid+1;
                }
                else if(st.rangeBitwiseAnd(i,mid)==k){
                    mini = mid;
                    high=mid-1;
