class SegmentTree:
    def __init__(self, n, default_val=0, combine=operator.add):
        self._n = n
        self._default_val = default_val
        self._tree = [default_val] * (2 * n)
        self._combine = combine

    def set(self, i, x):
        i += self._n
        self._tree[i] = x
        i //= 2
        while i >= 1:
            self._tree[i] = self._combine(self._tree[2 * i], self._tree[2 * i + 1])
            i //= 2

    def query(self, l, r):
        l += self._n
        r += self._n
        res = self._default_val
        while l <= r:
            if l % 2 == 1:
                res = self._combine(res, self._tree[l])
                l += 1
            if r % 2 == 0:
                res = self._combine(res, self._tree[r])
                r -= 1
            l //= 2
            r //= 2
        return res

