class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        int LOG = 20;
        using ll = long long;
        vector <vector <int>> tab (n, vector <int> (LOG));
        for (int bit = 0; bit < LOG; bit++) {
            if (bit == 0) {
                for (int i = 0; i < n; i++) tab[i][bit] = nums[i];
            }
            else {
                for (int i = 0; i + (1 << bit) <= n; i++) {
                    tab[i][bit] = (tab[i][bit - 1] & (tab[i + (1 << (bit - 1))][bit - 1]));
                }
            }
        }
        auto qry = [&] (int l, int r) -> ll {
            ll res = (1ll << 32) - 1;
            for (ll bit = LOG - 1; bit >= 0; bit--) if (l + (1 << bit) <= r + 1) {
                res = (res & tab[l][bit]);
                l += (1 << bit);
            }
            return res;
        };
        auto first = [&] (int i) -> int {
            int lo = i - 1, hi = n - 1;
            while (hi - lo > 1) {
                ll mid = lo + (hi - lo) / 2;
                ll r = qry(i, mid);
                if (r > k) lo = mid;
                else hi = mid;
            }
            return hi;
        };

        auto last = [&] (int i) -> int {
            int lo = i, hi = n;
            while (hi - lo > 1) {
                int mid = lo + (hi - lo) / 2;
                ll r = qry(i, mid);
                if (r >= k) lo = mid;
                else hi = mid;
            }
            return lo;
        };

        ll ans = 0;

        for (int i = 0; i < n; i++) {
            int l = first(i);
            int r = last(i);
            int x = qry(i, l);
            // cout << l << ' ' << r << '\n';
            if (x == k) {
                ans += (r - l + 1);
            }
        }
        return ans;
    }
};

