class Solution {
public:
    vi str;

    void build(vi &nums, int v, int tl, int tr) {
        if (tl == tr) return void(str[v] = nums[tl]);

        int tm = (tl + tr) >> 1;
        build(nums, v << 1, tl, tm); build(nums, v << 1 | 1, tm + 1, tr);
        str[v] = str[v << 1] & str[v << 1 | 1];
    }

    int getV(int l, int r, int v, int tl, int tr) {
        if (l > r) return INT_MAX;
        if (l == tl && r == tr) return str[v];
        int tm = (tl + tr) >> 1;
        return getV(l, min(r, tm), v << 1, tl, tm) & getV(max(l, tm + 1), r , v << 1 | 1, tm + 1, tr);
    }

    int binSearchFirst(int x, int k, int n) {
        int l = x, r = n - 1;
        while (r - l > 1) {
            int m = (l + r) >> 1;
            int qu = getV(x, m, 1, 0, n - 1);
            if (qu > k) l = m + 1;
            else r = m;
        }
        if (getV(x, l, 1, 0, n - 1) == k) return l;
        if (getV(x, r, 1, 0, n - 1) == k) return r;
        return -1;
    }

    int binSearchLast(int x, int k, int n) {
        int l = x, r = n - 1;
        while (r - l > 1) {
            int m = (l + r) >> 1;
            int qu = getV(x, m, 1, 0, n - 1);
            if (qu < k) r = m - 1;
            else l = m;
        }
        if (getV(x, r, 1, 0, n - 1) == k) return r;
        if (getV(x, l, 1, 0, n - 1) == k) return l;
        return -1;
    }

    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        str.resize(4 * n);
        build(nums, 1, 0, n - 1);
        ll ans = 0;
        rep(i, n) {
            int F = binSearchFirst(i, k, n);
            if (F == -1) continue;
            int L = binSearchLast(i, k, n);
            ans += (L - F  + 1);
        }
        return ans;
    }
};

