class Solution {
public:
    vi str;

    void build(vi &nums, int v, int tl, int tr) {
        if (tl == tr) return void(str[v] = nums[tl]);

        int tm = (tl + tr) >> 1;
        build(nums, v << 1, tl, tm); build(nums, v << 1 | 1, tm + 1, tr);
        str[v] = str[v << 1] & str[v << 1 | 1];
    }

    int getV(int l, int r, int v, int tl, int tr) {
        if (l > r) return INT_MAX;
        if (l == tl && r == tr) return str[v];
        int tm = (tl + tr) >> 1;
        return getV(l, min(r, tm), v << 1, tl, tm) & getV(max(l, tm + 1), r , v << 1 | 1, tm + 1, tr);
    }

    int binSearchFirst(int x, int k, int n) {
        int l = x, r = n - 1;
        while (r - l > 1) {
            int m = (l + r) >> 1;
            int qu = getV(x, m, 1, 0, n - 1);
            if (qu > k) l = m + 1;
            else r = m;
        }
        if (getV(x, l, 1, 0, n - 1) == k) return l;
        if (getV(x, r, 1, 0, n - 1) == k) return r;
        return -1;
    }

    int binSearchLast(int x, int k, int n) {
        int l = x, r = n - 1;
        while (r - l > 1) {
            int m = (l + r) >> 1;
            int qu = getV(x, m, 1, 0, n - 1);
            if (qu < k) r = m - 1;
            else l = m;
        }
        if (getV(x, r, 1, 0, n - 1) == k) return r;
        if (getV(x, l, 1, 0, n - 1) == k) return l;
        return -1;
    }

    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        str.resize(4 * n);
        build(nums, 1, 0, n - 1);
        ll ans = 0;
        rep(i, n) {
            int F = binSearchFirst(i, k, n);
            if (F == -1) continue;
            int L = binSearchLast(i, k, n);
            ans += (L - F  + 1);
        }
        return ans;
    }
};

class Solution {
    int getBit(int mask,int b){
        return (mask>>b)&1;
    }
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n=nums.size();
        int B=30;
        vector<vector<int>>last(n+1,vector<int>(B,n));
        for(int i=n-1;i>=0;i--){
            for(int j=0;j<B;j++){
                last[i][j]=last[i+1][j];
                if(!getBit(nums[i],j))last[i][j]=i;
            }
        }
        auto getVal=[&](int l,int r){
            int ans=(1<<B)-1;
            for(int j=0;j<B;j++){
                if(last[l][j]<=r)ans^=(1<<j);
            }
            return ans;
        };
        auto getMin=[&](int s){
            int start=s,end=n-1,ans=1;
            while(start<=end){
                int mid=start+(end-start)/2;
                int v=getVal(s,mid);
                if(v<k){
                    end=mid-1;
                }else if(v>k){
                    start=mid+1;
                }else{
                    ans=mid;
                    end=mid-1;
                }
            }
            return ans;
        };
        auto getMax=[&](int s){
            int start=s,end=n-1,ans=0;
            while(start<=end){
                int mid=start+(end-start)/2;
                int v=getVal(s,mid);
                if(v<k){
                    end=mid-1;
                }else if(v>k){
                    start=mid+1;
                }else{
                    ans=mid;
                    start=mid+1;
                }
            }
            return ans;
        };
        long long ans=0;
        for(int i=n-1;i>=0;i--){
            int minR=getMin(i),maxR=getMax(i);
            ans+=maxR-minR+1;
        }
        return ans;
    }
};

