auto BuildSparseTableFunc = [](const vector<int>& arr, auto binary_op) {
    const int n = arr.size();

    vector<vector<long long>> dp(n);
    for (int i = n - 1; i >= 0; --i) {
        dp[i].push_back(arr[i]);
        while (i + (1 << dp[i].size()) <= n) {
            int k = dp[i].size();
            dp[i].push_back(binary_op(dp[i][k - 1], dp[i + (1 << (k - 1))][k - 1]));
        }
    }

    return [dp = std::move(dp), binary_op](int from, int to) {
        assert(from <= to);
        int len = log2(to - from + 1);
        return binary_op(dp[from][len], dp[to - (1 << len) + 1][len]);
    };
};

