using ll = long long;
class SegmentTree {
public:
    vector<int> tree;
    int n;
    SegmentTree(vector<int>& arr)
    {
        n = arr.size();
        tree.resize(4 * n);
        build(arr, 0, 0, n - 1);
    }
    void build(vector<int>& arr, int node, int start,
               int end)
    {
        if (start == end) {
            tree[node] = arr[start];
        }
        else {
            int mid = (start + end) / 2;
            build(arr, 2 * node + 1, start, mid);
            build(arr, 2 * node + 2, mid + 1, end);
            tree[node]
                = tree[2 * node + 1] & tree[2 * node + 2];
        }
    }
    int query(int l, int r)
    {
        return query(0, 0, n - 1, l, r);
    }
    int query(int node, int start, int end, int l, int r)
    {
        if (r < start || end < l) 
            return INT_MAX;
        if (l <= start && end <= r)
            return tree[node];
        int mid = (start + end) / 2;
        int p1 = query(2 * node + 1, start, mid, l, r);
        int p2 = query(2 * node + 2, mid + 1, end, l, r);
        return p1 & p2;
    }
};
class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        //bitwise AND is a non-increasing function
        //we can perform binary search
        //find first index and find last index when the subarray has this bitwise AND
        int n = (int)nums.size();
        SegmentTree st(nums);
        ll ans = 0;
        for (int i = 0;i<n;i++){
            int l = i, r = n - 1, posLeft = -1;
            while (l <= r){
                int mid = (l + r)/2;
                int val = st.query(i,mid);
                if (val < k)r = mid - 1;
                if (val > k)l = mid + 1;
                if (val == k){
                    posLeft = mid;
                    r = mid - 1;
                }
            }
            l = i, r = n - 1;
            int posRight = -1;
            while (l <= r){
                int mid = (l + r)/2;
                int val = st.query(i,mid);
                if (val < k)r = mid - 1;
                if (val > k)l = mid + 1;
                if (val == k){
                    posRight = mid;
                    l = mid + 1;
                }
            }
            if (posLeft == -1)continue;
            ans += 1ll * (posRight - posLeft + 1);
        }
        return ans;
    }
};

class Solution {
public:
    typedef long long ll;
    class SegtreeAnd {
    public:
        SegtreeAnd(vector<int> arr) {
            int n = arr.size();
            size = 1;
            while(size < n)
                size *= 2;
            agg = vector<int>(size*2, (1<<30)-1); // 1073741823 > 1e9
            build(arr, 0, 0, size);
        }
        void build(vector<int>& arr, int nd_id, int lb, int rb) {
            if (rb - lb == 1) { // top-down assignment
                if (lb < (int)(arr.size())) {
                    agg[nd_id] = arr[lb];
                }
                return;
            }
            int mid = lb + (rb-lb) / 2;
            build(arr, nd_id*2+1, lb, mid);
            build(arr, nd_id*2+2, mid, rb);
            agg[nd_id] = (agg[nd_id*2+1] & agg[nd_id*2+2]);
        }

            // notice: range [lb, rb)
        void update(int i, int val, int nd_id, int lb, int rb) {
            if (rb-lb == 1) {
                agg[nd_id] = val;
                return;
            }
            int mid = lb + (rb-lb) / 2;
            if (i < mid) {
                update(i, val, nd_id*2+1, lb, mid);
            } else {
                update(i, val, nd_id*2+2, mid, rb);
            }
            agg[nd_id] = (agg[nd_id*2+1] & agg[nd_id*2+2]);
        }
        void update(int i, int val) {
            update(i, val, 0, 0, size);
        }
        int get_and(int l, int r, int nd_id, int lb, int rb) {
            if (lb >= r || l >= rb) // total outer
                return INT_MAX;
            if (lb >= l && rb <= r) // total inner
                return agg[nd_id];
            int mid = lb + (rb-lb) / 2;
            int agg_l = get_and(l, r, nd_id*2+1, lb, mid);
            int agg_r = get_and(l, r, nd_id*2+2, mid, rb);
            return (agg_l & agg_r);
        }
        int get_and(int l, int r) {
            return get_and(l, r, 0, 0, size);
        }
    private:
        int size;
        vector<int> agg;
    };
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        ll ans = 0;
        SegtreeAnd* st = new SegtreeAnd(nums);
        for(int i = 0; i < n; i++) {
            if (nums[i] < k) continue;
            // start
            int lo = i, hi = n;
            while (lo < hi) {
                int mid = lo + (hi - lo) / 2;
                if (st->get_and(i, mid+1) > k) {
                    lo = mid+1;
                } else {
                    hi = mid;
                }
            }
            int beg = lo;

            // end
            lo = i, hi = n;
            while (lo < hi) {
                int mid = lo + (hi - lo) / 2;
                if (st->get_and(i, mid+1) >= k) {
                    lo = mid+1;
                } else {
                    hi = mid;
                }
            }
            int ed = lo;
            // cout << "i = " << i << ", beg = " << beg << ", ed = " << ed << endl;
            ans += ll(ed - beg);
        }
        return ans;
    }
};

