class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        st = [[0] * 20 for _ in range(n)]
        for i in range(n):
            st[i][0] = nums[i]
        j = 1
        while (1 << j) <= n:
            i = 0
            while (i + (1 << j) - 1) < n:
                st[i][j] = st[i][j - 1] & st[i + (1 << (j - 1))][j - 1]
                i += 1
            j += 1

        def range_and(l, r):
            log = (r - l + 1).bit_length() - 1
            return st[l][log] & st[r - (1 << log) + 1][log]

        ans = 0
        for s in range(n):
            left = -1
            l, r = s, n - 1
            while l <= r:
                mid = (l + r) // 2
                if range_and(s, mid) >= k:
                    if range_and(s, mid) == k:
                        left = mid
                    l = mid + 1
                else:
                    r = mid - 1

            right = -1
            l, r = s, n - 1
            while l <= r:
                mid = (l + r + 1) // 2
                if range_and(s, mid) <= k:
                    if range_and(s, mid) == k:
                        right = mid
                    r = mid - 1
                else:
                    l = mid + 1

            if left != -1 and right != -1 and range_and(s, left) == k and range_and(s, right) == k:
                ans += (left - right + 1)

        return ans

