        for (int i = 0; i < N; i++) {
            while (l <= i && ST.get(l, i) < K) {
                l++;
            }
            while (r <= i && ST.get(r, i) <= K) {
                r++;
            }
            ans+=r-l;
        }
        return ans;
    }
};

