class Solution {
    final int bitLen = 32;
    long calc(int[] bit,int val,int delta,int x){
        long value = 0;
        for(int i=0;i<bitLen;i++){
            long xx = (1<<i);
            if((val&xx) != 0){
                bit[i] += delta;
            }
            if(bit[i] == x){
                value |= xx;
            }
        }
        return value;
    }
    public long countSubarrays(int[] nums, int k) {
        int n = nums.length;
        int[] pre = new int[n+1];
        for(int i=n-1;i>=0;i--){
            if((nums[i] & k) == k){
                pre[i] = 1;
                pre[i] += pre[i+1];
            }
        }
        //System.out.println(Arrays.toString(pre));
        int[] bit = new int[bitLen];
        long ans = 0;
        for(int i=0,j=0;i<n;i++){
            long val = calc(bit,nums[i],1,i-j+1);
            while(j <= i && val < k){
                val = calc(bit,nums[j],-1,i-j);
                j++;
            }
            while(j <= i && val == k){
                ans += pre[i+1] + 1;
                val = calc(bit,nums[j],-1,i-j);
                j++;
            }
        }
        return ans;
    }
}

class Solution {
public:
    long long countSubarrays(vector<int>& a, int k) {
        int n = a.size();
        vector<vector<int>> b(n + 1, vector<int> (31));
        for (int i = 0; i < n; ++i) {
            b[i+1] = b[i];
            for (int j = 0; j < 31; ++j) {
                b[i+1][j] += ((a[i] >> j) & 1);
            }
        }
        long long ans = 0;
        for (int i = 0; i < n; ++i) {
            int mask = 0;
            for (int j = 0; j < 31; ++j) {
                if (b[i + 1][j] == i + 1) {
                    mask += (1 << j);
                }
            }

            if (mask > k) {
                continue;
            }
            if (a[i] < k) {
                continue;
            }
            int left, right;
            {
                int l = -1, r = i;
                // r: msk >= k
                while (l + 1 < r) {
                    int m = (l + r) / 2;
                    int msk = 0;
                    for (int j = 0; j < 31; ++j) {
                        if (b[i+1][j] - b[m][j] == (i + 1 - m)) {
                            msk += (1 << j);
                        }
                    }
                    if (msk >= k) {
                        r = m;
                    } else {
                        l = m;
                    }
                }
                left = r;
            }

            {
                int l = 0, r = i + 1;
                // l: msk <= k
                while (l + 1 < r) {
                    int m = (l + r) / 2;
                    int msk = 0;
                    for (int j = 0; j < 31; ++j) {
                        if (b[i+1][j] - b[m][j] == (i + 1 - m)) {
                            msk += (1 << j);
                        }
                    }
                    if (msk <= k) {
                        l = m;
                    } else {
                        r = m;
                    }
                }
                right = l;
            }
            int msk = 0;
            for (int j = 0; j < 31; ++j) {
                if (b[i+1][j] - b[left][j] == i + 1 - left) {
                    msk += (1 << j);
                }
            }

            if (msk == k) {
                ans += (right - left + 1);
            }

        }
        return ans;
    }
};

