            for (int j = 0; j < 31; ++j) {
                if (b[i+1][j] - b[left][j] == i + 1 - left) {
                    msk += (1 << j);
                }
            }

            if (msk == k) {
                ans += (right - left + 1);
            }

        }
        return ans;
