#define ll int

class Node{
    public:

    ll d;
    Node *l, *r;

    Node(ll data){
        d = data;
        l = NULL;
        r = NULL;
    }
};

class SegmentTree {
    Node *root;
    ll n;
public:
    ll op(ll num1, ll num2){
        return num1 & num2;
    }

    Node* make(ll l, ll r, vector<ll> &a){
        if(l == r){
            Node* newNode = new Node(a[l]);
            return newNode;
        }

        ll m = (l+r)/2;

        Node* left = make(l, m, a);
        Node* right = make(m+1, r, a);

        ll ans = op(left->d, right->d);

        Node* newNode = new Node(ans);
        newNode->l = left;
        newNode->r = right;
        return newNode;
    }

    SegmentTree(vector<ll>& a) {
        n = a.size();
        if(n == 0){
            //cout << "You_are_passing_empty_vector_in_Segment_Tree\n";
            return;
        }
        root = make(0, a.size() - 1, a);
    }

    ll update(Node* t, ll l, ll r, ll index, ll val) {
        if(l == r){
            ll ans = val;
            t->d = val;
            return ans;
        }

        ll m = (l+r)/2;

        if(index > m){
            ll ans = op(update(t->r, m+1, r, index, val), t->l->d);
            t->d = ans;
        }
        else{
            ll ans = op(update(t->l, l, m, index, val), t->r->d);
            t->d = ans;
        }
        return t->d;
    }

    ll query(Node* t, ll currL, ll currR, ll reqL, ll reqR) {

        if(currL == reqL && currR == reqR){
            return t->d;
        }

        ll m = (currL + currR)/2;

        ll ans;

        if(reqL <= min(m, reqR) && max(m+1, reqL) <= reqR){
            ll ansL = query(t->l, currL, m, reqL, min(m, reqR));
            ll ansR = query(t->r, m+1, currR, max(m+1, reqL), reqR);

            ans = op(ansL, ansR);
        }
        else if(reqL <= min(m, reqR)){
            ll ansL = query(t->l, currL, m, reqL, min(m, reqR));
            ans = ansL;
        }
        else{//case of max(m+1, reqL) <= reqR
            ll ansR = query(t->r, m+1, currR, max(m+1, reqL), reqR);
            ans = ansR;
        }

        return ans;
    }

    void update(ll index, ll val) {
        update(root, 0, n-1, index, val);
    }

    ll query(ll left, ll right) {
        return query(root, 0, n-1, left, right);
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& a, int k) {
        ll n = a.size();

        SegmentTree st (a);

        long long ans = 0;

        for(ll i = 0; i<a.size(); i++){
            long long l = i;
            long long r = n - 1;

            long long m1 = n;

            while(l <= r){
                long long m = (l + r)/2;

                long long c = st.query(i, m);

                if(c <= k){
                    m1 = m;
                    r = m - 1;
                }
                else{
                    l = m + 1;
                }
            }

            l = i;
            r = n - 1;

            long long m2 = n;

            while(l <= r){
                long long m = (l + r)/2;

                long long c = st.query(i, m);

                if(c <= k - 1){
                    m2 = m;
                    r = m - 1;
                }
                else{
                    l = m + 1;
                }
            }

            ans += m2 - m1;
        }

        return ans;
    }
};

