class Solution {
public:
    int findAND(int l, int r, vector<vector<int>> &bits) {
        int ans = 0;
        for (int i = 0; i < 32; i++) {
            int x = bits[r][i];
            if(l) x -= bits[l-1][i];
            if(x==(r-l+1)) ans += (1<<i);
        }
        return ans;
    }

    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        vector<vector<int>> bits(n,vector<int>(32));
        for(int i = 0; i < n; i++) {
            for(int j = 0; j < 32; j++) {
                if(i) bits[i][j] += bits[i-1][j];
                if((1LL<<j)&nums[i]) bits[i][j]++;
            }
        }
        long long ans = 0;
        for(int i = 0; i < n; i++) {
            int l = 0, r = i, mid, L = -1, R = -1;
            while(l<=r) {
                mid = l+(r-l)/2;
                int ad = findAND(mid,i,bits);
                if(ad>=k) {
                    L = mid;
                    r = mid-1;
                }
                else l = mid+1;
            }
            l = 0, r = i;
            while(l<=r) {
                mid = l+(r-l)/2;
                int ad = findAND(mid,i,bits);
                if(ad<=k) {
                    R = mid;
                    l = mid+1;
                }
                else r = mid-1;
            }
            if(L==-1||R==-1||L>R) continue;
            ans += (R-L+1);
            // cout << i << " -> " << L << " " << R << " " << R-L+1 << " " << ans << endl;
        }
        return ans;
    }
};

