            ll st=n,en=i-1;
            while(l<=r){
                ll mid=l+(r-l)/2;
                ll cur=rangeAnd(i,mid);
                if(cur==k){
                    en=max(en,mid);
                    l=mid+1;
                }
                else if(cur>k) l=mid+1;
                else r=mid-1;
