from math import log2


class SP:

    def func(self, a, b):
        return a & b

    def __init__(self, a):
        self.n = len(a)
        self.st = [[0 for _ in range(self.n + 1)] for _ in range(20)]

        self.st[0] = a.copy()
        for i in range(1, self.n + 1):
            j = 0
            while j + (1 << i) <= self.n:
                self.st[i][j] = self.func(self.st[i - 1][j], self.st[i - 1][j + (1 << (i - 1))])
                j += 1

    def query(self, L, R):
        i = int(log2(R - L + 1))
        return self.func(self.st[i][L], self.st[i][R - (1 << i) + 1])

class Solution:
    def countSubarrays(self, a: List[int], k: int) -> int:
        st = SP(a)
        n = len(a)
        ans = 0

        for i in range(n):

            l, h = 0, i

            while l <= h:
                m = (l + h) // 2

                if st.query(m, i) < k:
                    l = m + 1
                else:
                    h = m - 1

            L = h + 1

            l, h = 0, i

            while l <= h:
                m = (l + h) // 2

                if st.query(m, i) <= k:
                    l = m + 1
                else:
                    h = m - 1

            R = l - 1

            # print(i, L, R)

            ans += max(0, R - L + 1)

        return ans

