class Solution {
public:
    #define ll long long
    int ff(int l,int r,vector<vector<int>> &pre){
        int len=(r-l+1);
        int ans=0;
        for(int i=0;i<30;i++){
            int cnt=pre[r][i];
            if(l>0) cnt-=pre[l-1][i];
            if(cnt==len){
                ans+=(1<<i);
            }
        }
        return ans;
    }
    int f(int i,vector<vector<int>> &pre,int n,int k){
        int lo=i,hi=n-1;
        int ind=-1;
        if(ff(lo,lo,pre)<k) return -1;
        while(lo<=hi){
            int mid=(lo+hi)/2;
            int val=ff(i,mid,pre);
            if(val>k){
                lo=mid+1;
            }
            else if(val==k){
                ind=mid;
                hi=mid-1;
            }
            else{
                // val<k
                hi=mid-1;
            }
        }
        return ind;
    }
     int fin(int i,vector<vector<int>> &pre,int n,int k){
        int lo=i,hi=n-1;
        int ind=-1;
        if(ff(lo,lo,pre)<k) return -1;

        while(lo<=hi){
            int mid=(lo+hi)/2;
            int val=ff(i,mid,pre);
            // cout<<"lo: "<<lo<<" mid: "<<mid<<" hi: "<<hi<<" val: "<<val<<"\n";
            if(val>k){
                lo=mid+1;
            }
            else if(val==k){
                ind=mid;
                lo=mid+1;
            }
            else{
                // val<k
                hi=mid-1;
            }
        }
        return ind;
    }
    long long countSubarrays(vector<int>& nums, int k) {
       int n=(int)nums.size();
       vector<vector<int>> bits(n,vector<int>(30,0));
        for(int i=0;i<n;i++){
            for(int j=0;j<30;j++){
                bits[i][j]=(nums[i]>>j)&1;
                if(i){
                    bits[i][j]+=bits[i-1][j];
                }
            }
        } 
        ll ans=0LL;
        for(int i=0;i<n;i++){
            int start=f(i,bits,n,k);
            int end=fin(i,bits,n,k);
            if(start==-1 or end==-1) continue;
            ans+=1LL*end-1LL*start+1LL;
        }
        return ans;
    }
};

