#define ll long long
class Solution {
public:
    static ll bitAnd(ll a, ll b) {return a & b;}
    template<typename T>
    struct SparseTable{
        ll n;
        vector<vector<T>> table;
        function<T(const T&, const T&)> merge;
        SparseTable(vector<T> a, const function<T(const T&, const T&)> &_merge){
            ll n = a.size();
            merge = _merge;
            int max_size = 31 - __builtin_clz(n);
            table.assign(max_size + 1, vector<T>(n, (T)0));
            for(int i = 0; i < n; ++i) table[0][i] = a[i];
            for(int i = 1; i <= max_size; ++i) 
                for(int j = 0; j <= n - (1 << i); ++j) 
                    table[i][j] = merge(table[i - 1][j],table[i - 1][j + (1 << (i - 1))]);
        }

        T query(ll l, ll r) {
            int dist = 31 - __builtin_clz(r - l + 1);
            return merge(table[dist][l], table[dist][r - (1 << dist) + 1]);
        }
    };
    long long countSubarrays(vector<int>& nums, int k) {
        vector<ll> v;
        for(auto p : nums) v.push_back(p);
        ll n = nums.size();
        SparseTable<ll> st(v, bitAnd);
        ll ans = 0;
        for(ll i = 0;i<n;i++){
            ll l = i, h = n - 1;
            ll mi = n + 1 , mx = -1;
            while(l <= h){
                ll m = (l + h) / 2;
                ll start = i , last = m;
                ll val = st.query(start, last);
                if(val < k){
                    h = m - 1;
                }
                else{
                    if(val == k){
                        mi = min(mi, m);
                        h = m - 1;
                    }
                    else{
                        l = m + 1;
                    }
                }
            }
            l = i, h = n - 1;
            while(l <= h){
                ll m = (l + h) / 2;
                ll start = i , last = m;
                ll val = st.query(start, last);
                if(val < k){
                    h = m - 1;
                }
                else{
                    if(val == k){
                        mx = max(mx, m);
                        l = m + 1;
                    }
                    else{
                        l = m + 1;
                    }
                }
            }
            if(mx != -1){
                ll diff = mx - mi + 1;
                // cout << mi << " " << mx << " " << diff << endl;
                ans += diff;
            }
        }
        // cout << "---\n";
        return ans;
    }
};

