#define ll long long

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        vector<int> cnt1(32), cnt2(32);
        auto off = [&](vector<int>& cnt, int j, int delta) {
            for (int i = 0; i < 31; ++i) {
                if ((nums[j] & (1 << i)) == 0) {
                    cnt[i] += delta;
                }
            }
        };
        auto getv = [&](vector<int>& cnt) {
            int v = 0;
            for (int i = 0; i < 31; ++i) {
                if (cnt[i] == 0) {
                    v |= (1 << i);
                }
            }
            return v;
        };

        int l1 = 0, l2 = 0;
        ll ans = 0;
        for (int r = 0; r < n; ++r) {
            off(cnt1, r, 1);
            int v1 = INT_MIN;
            while ((v1 = getv(cnt1)) < k) {
                off(cnt1, l1, -1);
                l1++;
            }

            off(cnt2, r, 1);
            int v2 = INT_MIN;
            while ((v2 = getv(cnt2)) <= k) {
                off(cnt2, l2, -1);
                l2++;
            }

            if (v1 == k) {
                ans += (l2 - l1);
            }

            // printf("%d %d %d %d %d %d\n", r, l1, l2, v1, v2, ans);
        }
        return ans;
    }
};

