#include <bits/stdc++.h>

using namespace std;

namespace impl {

template <typename DataType, class Operator, bool LazyAssignment>
struct LazyAssignmentComponent {};

template <typename DataType, class Operator>
struct LazyAssignmentComponent<DataType, Operator, true> {
  DataType lazy_assignment = Operator::Identity();
};

template <typename DataType, class Operator, bool LazyIncrement>
struct LazyIncrementComponent {};

template <typename DataType, class Operator>
struct LazyIncrementComponent<DataType, Operator, true> {
  DataType lazy_increment = Operator::Identity();
};

template <bool Persistent>
struct PersistentComponent {};

template <>
struct PersistentComponent<true> {
  int left_child;
  int right_child;
};

template <typename DataType, class Operator, bool LazyAssignment, bool LazyIncrement,
          bool Persistent>
struct SegmentTreeNode : public LazyAssignmentComponent<DataType, Operator, LazyAssignment>,
                         public LazyIncrementComponent<DataType, Operator, LazyIncrement>,
                         public PersistentComponent<Persistent> {
  DataType value;
};

}  // namespace impl

template <typename DataType, class Operator, bool LazyAssignment = false,
          bool LazyIncrement = false, bool Persistent = false>
class SegmentTree {
  using Node = impl::SegmentTreeNode<DataType, Operator, LazyAssignment, LazyIncrement, Persistent>;

 public:
  template <class RawContainer>
  inline void Build(const RawContainer& raw_container) noexcept
    requires (!Persistent)
  {
    data_size_ = static_cast<int>(raw_container.size());
    tree_.resize(4 * data_size_);
    BuildRecursive(raw_container, 1, 0, data_size_ - 1);
  }

  template <class RawContainer>
  inline int Build(const RawContainer& raw_container, int number_of_future_operations) noexcept
    requires (Persistent)
  {
    data_size_ = static_cast<int>(raw_container.size());
    int size = data_size_;
    int height = 1;
    while (size > 1) {
      height++;
      size /= 2;
    }
    tree_.resize(2 * data_size_ + 4 * height * number_of_future_operations);
    next_valid_index_ = 1;
    BuildRecursive(raw_container, 0, 0, data_size_ - 1);
    return 0;
  }

  inline DataType Query(int left, int right) noexcept
    requires (!Persistent)
  {
    if (left > right) {
      return Operator::Identity();
    }
    return QueryRecursive(1, 0, data_size_ - 1, left, right);
  }

  inline std::pair<DataType, int> Query(int left, int right, int root) noexcept
    requires (Persistent)
  {
    if (left > right) {
      return { Operator::Identity(), root };
    }
    int new_root;
    if constexpr (LazyAssignment || LazyIncrement) {
      new_root = CopyRoot(root);
    } else {
      new_root = root;
    }
    return { QueryRecursive(new_root, 0, data_size_ - 1, left, right), new_root };
  }

  inline void Assign(int position, const DataType& assignment) noexcept
    requires (!Persistent)
  {
    AssignRecursive(1, 0, data_size_ - 1, position, assignment);
  }

  inline int Assign(int position, const DataType& assignment, int root) noexcept
    requires (Persistent)
  {
    const int new_root = CopyRoot(root);
    AssignRecursive(new_root, 0, data_size_ - 1, position, assignment);
    return new_root;
  }

  inline void RangeAssign(int left, int right, const DataType& assignment) noexcept
    requires (LazyAssignment && !Persistent)
  {
    if (left > right) {
      return;
    }
    RangeAssignRecursive(1, 0, data_size_ - 1, left, right, assignment);
  }

  inline int RangeAssign(int left, int right, const DataType& assignment, int root) noexcept
    requires (LazyAssignment && Persistent)
  {
    const int new_root = CopyRoot(root);
    if (left <= right) {
      RangeAssignRecursive(new_root, 0, data_size_ - 1, left, right, assignment);
    }
    return new_root;
  }

  inline void Increase(int position, const DataType& increment) noexcept
    requires (!Persistent)
  {
    IncreaseRecursive(1, 0, data_size_ - 1, position, increment);
  }

  inline int Increase(int position, const DataType& increment, int root) noexcept
    requires (Persistent)
  {
    const int new_root = CopyRoot(root);
    IncreaseRecursive(new_root, 0, data_size_ - 1, position, increment);
    return new_root;
  }

  inline void RangeIncrease(int left, int right, const DataType& increment) noexcept
    requires (LazyIncrement && !Persistent)
  {
    if (left > right) {
      return;
    }
    RangeIncreaseRecursive(1, 0, data_size_ - 1, left, right, increment);
  }

  inline int RangeIncrease(int left, int right, const DataType& increment, int root) noexcept
    requires (LazyIncrement && Persistent)
  {
    const int new_root = CopyRoot(root);
    if (left <= right) {
      RangeIncreaseRecursive(new_root, 0, data_size_ - 1, left, right, increment);
    }
    return new_root;
  }

  template <typename Predicate>
  inline int FindFirstRightIndex(int left_boundary, const Predicate& predicate) noexcept
    requires (!Persistent)
  {
    DataType cumulative_value = Operator::Identity();
    return FindFirstRightIndexRecursive(1, 0, data_size_ - 1, left_boundary, predicate,
                                        cumulative_value);
  }

  template <typename Predicate>
  inline std::pair<int, int> FindFirstRightIndex(int left_boundary, const Predicate& predicate,
                                                 int root) noexcept
    requires (Persistent)
  {
    int new_root;
    if constexpr (LazyAssignment || LazyIncrement) {
      new_root = CopyRoot(root);
    } else {
      new_root = root;
    }
    DataType cumulative_value = Operator::Identity();
    return { FindFirstRightIndexRecursive(new_root, 0, data_size_ - 1, left_boundary, predicate,
                                          cumulative_value),
             new_root };
  }

  template <typename Predicate>
  inline int FindFirstLeftIndex(int right_boundary, const Predicate& predicate) noexcept
    requires (!Persistent)
  {
    DataType cumulative_value = Operator::Identity();
    return FindFirstLeftIndexRecursive(1, 0, data_size_ - 1, right_boundary, predicate,
                                       cumulative_value);
  }

  template <typename Predicate>
  inline std::pair<int, int> FindFirstLeftIndex(int right_boundary, const Predicate& predicate,
                                                int root) noexcept
    requires (Persistent)
  {
    int new_root;
    if constexpr (LazyAssignment || LazyIncrement) {
      new_root = CopyRoot(root);
    } else {
      new_root = root;
    }
    DataType cumulative_value = Operator::Identity();
    return { FindFirstLeftIndexRecursive(new_root, 0, data_size_ - 1, right_boundary, predicate,
                                         cumulative_value),
             new_root };
  }

  inline int RangeCopy(int root, int old_root, int left, int right) noexcept
    requires (Persistent)
  {
    const int new_root = CopyRoot(root);
    if (left <= right) {
      RangeCopyRecursive(new_root, old_root, 0, data_size_ - 1, left, right);
    }
    return new_root;
  }

 private:
  template <class RawContainer>
  inline void BuildRecursive(const RawContainer& raw_container, int vertex, int segment_left,
                             int segment_right) noexcept {
    if constexpr (LazyAssignment) {
      tree_[vertex].lazy_assignment = Operator::Identity();
    }
    if constexpr (LazyIncrement) {
      tree_[vertex].lazy_increment = Operator::Identity();
    }
    if (segment_left == segment_right) {
      tree_[vertex].value = raw_container[segment_left];
    } else {
      if constexpr (Persistent) {
        tree_[vertex].left_child = next_valid_index_;
        next_valid_index_++;
        tree_[vertex].right_child = next_valid_index_;
        next_valid_index_++;
      }
      const int segment_middle = (segment_left + segment_right) / 2;
      BuildRecursive(raw_container, LeftChild(vertex), segment_left, segment_middle);
      BuildRecursive(raw_container, RightChild(vertex), segment_middle + 1, segment_right);
      PushUp(vertex);
    }
  }

  inline DataType QueryRecursive(int vertex, int segment_left, int segment_right, int left,
                                 int right) noexcept {
    if (segment_left == left && segment_right == right) {
      return tree_[vertex].value;
    }
    PushDown(vertex, segment_left, segment_right);
    const int segment_middle = (segment_left + segment_right) / 2;
    if (right <= segment_middle) {
      return QueryRecursive(LeftChild(vertex), segment_left, segment_middle, left, right);
    }
    if (left >= segment_middle + 1) {
      return QueryRecursive(RightChild(vertex), segment_middle + 1, segment_right, left, right);
    }
    return Operator::Combine(
        QueryRecursive(LeftChild(vertex), segment_left, segment_middle, left, segment_middle),
        QueryRecursive(RightChild(vertex), segment_middle + 1, segment_right, segment_middle + 1,
                       right));
  }

  inline void AssignRecursive(int vertex, int segment_left, int segment_right, int position,
                              const DataType& assignment) noexcept {
    if (segment_left == segment_right) {
      tree_[vertex].value = assignment;
      return;
    }
    PushDown(vertex, segment_left, segment_right);
    const int segment_middle = (segment_left + segment_right) / 2;
    if (position <= segment_middle) {
      CopyLeftChild<false>(vertex);
      AssignRecursive(LeftChild(vertex), segment_left, segment_middle, position, assignment);
    } else {
      CopyRightChild<false>(vertex);
      AssignRecursive(RightChild(vertex), segment_middle + 1, segment_right, position, assignment);
    }
    PushUp(vertex);
  }

  inline void RangeAssignRecursive(int vertex, int segment_left, int segment_right, int left,
                                   int right, const DataType& assignment) noexcept {
    if (segment_left == left && segment_right == right) {
      ReceiveLazyAssignment(vertex, segment_left, segment_right, assignment);
      return;
    }
    PushDown(vertex, segment_left, segment_right);
    const int segment_middle = (segment_left + segment_right) / 2;
    if (right <= segment_middle) {
      CopyLeftChild<false>(vertex);
      RangeAssignRecursive(LeftChild(vertex), segment_left, segment_middle, left, right,
                           assignment);
    } else if (left >= segment_middle + 1) {
      CopyRightChild<false>(vertex);
      RangeAssignRecursive(RightChild(vertex), segment_middle + 1, segment_right, left, right,
                           assignment);
    } else {
      CopyLeftChild<false>(vertex);
      CopyRightChild<false>(vertex);
      RangeAssignRecursive(LeftChild(vertex), segment_left, segment_middle, left, segment_middle,
                           assignment);
      RangeAssignRecursive(RightChild(vertex), segment_middle + 1, segment_right,
                           segment_middle + 1, right, assignment);
    }
    PushUp(vertex);
  }

  inline void IncreaseRecursive(int vertex, int segment_left, int segment_right, int position,
                                const DataType& increment) noexcept {
    if (segment_left == segment_right) {
      tree_[vertex].value = Operator::Combine(tree_[vertex].value, increment);
      return;
    }
    PushDown(vertex, segment_left, segment_right);
    const int segment_middle = (segment_left + segment_right) / 2;
    if (position <= segment_middle) {
      CopyLeftChild<false>(vertex);
      IncreaseRecursive(LeftChild(vertex), segment_left, segment_middle, position, increment);
    } else {
      CopyRightChild<false>(vertex);
      IncreaseRecursive(RightChild(vertex), segment_middle + 1, segment_right, position, increment);
    }
    PushUp(vertex);
  }

  inline void RangeIncreaseRecursive(int vertex, int segment_left, int segment_right, int left,
                                     int right, const DataType& increment) noexcept {
    if (segment_left == left && segment_right == right) {
      ReceiveLazyIncrement(vertex, segment_left, segment_right, increment);
      return;
    }
    PushDown(vertex, segment_left, segment_right);
    const int segment_middle = (segment_left + segment_right) / 2;
    if (right <= segment_middle) {
      CopyLeftChild<false>(vertex);
      RangeIncreaseRecursive(LeftChild(vertex), segment_left, segment_middle, left, right,
                             increment);
    } else if (left >= segment_middle + 1) {
      CopyRightChild<false>(vertex);
      RangeIncreaseRecursive(RightChild(vertex), segment_middle + 1, segment_right, left, right,
                             increment);
    } else {
      CopyLeftChild<false>(vertex);
      CopyRightChild<false>(vertex);
      RangeIncreaseRecursive(LeftChild(vertex), segment_left, segment_middle, left, segment_middle,
                             increment);
      RangeIncreaseRecursive(RightChild(vertex), segment_middle + 1, segment_right,
                             segment_middle + 1, right, increment);
    }
    PushUp(vertex);
  }

  template <typename Predicate>
  inline int FindFirstRightIndexRecursive(int vertex, int segment_left, int segment_right,
                                          int left_boundary, const Predicate& predicate,
                                          DataType& cumulative_value) noexcept {
    if (segment_left == left_boundary) {
      const DataType combined = Operator::Combine(cumulative_value, tree_[vertex].value);
      if (!predicate(combined)) {
        cumulative_value = combined;
        return -1;
      }
      if (segment_left == segment_right) {
        return segment_left;
      }
    }
    PushDown(vertex, segment_left, segment_right);
    const int segment_middle = (segment_left + segment_right) / 2;
    if (left_boundary <= segment_middle) {
      const int result_left =
          FindFirstRightIndexRecursive(LeftChild(vertex), segment_left, segment_middle,
                                       left_boundary, predicate, cumulative_value);
      if (result_left != -1) {
        return result_left;
      }
      return FindFirstRightIndexRecursive(RightChild(vertex), segment_middle + 1, segment_right,
                                          segment_middle + 1, predicate, cumulative_value);
    }
    return FindFirstRightIndexRecursive(RightChild(vertex), segment_middle + 1, segment_right,
                                        left_boundary, predicate, cumulative_value);
  }

  template <typename Predicate>
  inline int FindFirstLeftIndexRecursive(int vertex, int segment_left, int segment_right,
                                         int right_boundary, const Predicate& predicate,
                                         DataType& cumulative_value) noexcept {
    if (segment_right == right_boundary) {
      const DataType combined = Operator::Combine(tree_[vertex].value, cumulative_value);
      if (!predicate(combined)) {
        cumulative_value = combined;
        return -1;
      }
      if (segment_left == segment_right) {
        return segment_left;
      }
    }
    PushDown(vertex, segment_left, segment_right);
    const int segment_middle = (segment_left + segment_right) / 2;
    if (right_boundary >= segment_middle + 1) {
      const int result_right =
          FindFirstLeftIndexRecursive(RightChild(vertex), segment_middle + 1, segment_right,
                                      right_boundary, predicate, cumulative_value);
      if (result_right != -1) {
        return result_right;
      }
      return FindFirstLeftIndexRecursive(LeftChild(vertex), segment_left, segment_middle,
                                         segment_middle, predicate, cumulative_value);
    }
    return FindFirstLeftIndexRecursive(LeftChild(vertex), segment_left, segment_middle,
                                       right_boundary, predicate, cumulative_value);
  }

  inline void RangeCopyRecursive(int vertex, int old_vertex, int segment_left, int segment_right,
                                 int left, int right) noexcept {
    if (segment_left == left && segment_right == right) {
      tree_[vertex] = tree_[old_vertex];
      return;
    }
    PushDown(old_vertex, segment_left, segment_right);
    PushDown(vertex, segment_left, segment_right);
    const int segment_middle = (segment_left + segment_right) / 2;
    if (right <= segment_middle) {
      CopyLeftChild<false>(vertex);
      RangeCopyRecursive(LeftChild(vertex), LeftChild(old_vertex), segment_left, segment_middle,
                         left, right);
    } else if (left >= segment_middle + 1) {
      CopyRightChild<false>(vertex);
      RangeCopyRecursive(RightChild(vertex), RightChild(old_vertex), segment_middle + 1,
                         segment_right, left, right);
    } else {
      CopyLeftChild<false>(vertex);
      CopyRightChild<false>(vertex);
      RangeCopyRecursive(LeftChild(vertex), LeftChild(old_vertex), segment_left, segment_middle,
                         left, segment_middle);
      RangeCopyRecursive(RightChild(vertex), RightChild(old_vertex), segment_middle + 1,
                         segment_right, segment_middle + 1, right);
    }
    PushUp(vertex);
  }

  [[nodiscard]] inline int LeftChild(int vertex) const noexcept {
    if constexpr (Persistent) {
      return tree_[vertex].left_child;
    } else {
      return 2 * vertex;
    }
  }

  [[nodiscard]] inline int RightChild(int vertex) const noexcept {
    if constexpr (Persistent) {
      return tree_[vertex].right_child;
    } else {
      return 2 * vertex + 1;
    }
  }

  [[nodiscard]] inline int CopyRoot(int root) noexcept {
    const int new_root = next_valid_index_;
    tree_[new_root] = tree_[root];
    next_valid_index_++;
    return new_root;
  }

  template <bool BeforePushDown>
  inline void CopyLeftChild(int vertex) noexcept {
    if constexpr (Persistent && (BeforePushDown == (LazyAssignment || LazyIncrement))) {
      tree_[next_valid_index_] = tree_[LeftChild(vertex)];
      tree_[vertex].left_child = next_valid_index_;
      next_valid_index_++;
    }
  }

  template <bool BeforePushDown>
  inline void CopyRightChild(int vertex) noexcept {
    if constexpr (Persistent && (BeforePushDown == (LazyAssignment || LazyIncrement))) {
      tree_[next_valid_index_] = tree_[RightChild(vertex)];
      tree_[vertex].right_child = next_valid_index_;
      next_valid_index_++;
    }
  }

  inline void PushUp(int vertex) noexcept {
    tree_[vertex].value =
        Operator::Combine(tree_[LeftChild(vertex)].value, tree_[RightChild(vertex)].value);
  }

  inline void PushDown(int vertex, int segment_left, int segment_right) noexcept {
    if constexpr (!LazyAssignment && !LazyIncrement) {
      return;
    } else {
      CopyLeftChild<true>(vertex);
      CopyRightChild<true>(vertex);
      const int segment_middle = (segment_left + segment_right) / 2;
      if constexpr (LazyAssignment) {
        if (tree_[vertex].lazy_assignment != Operator::Identity()) {
          ReceiveLazyAssignment(LeftChild(vertex), segment_left, segment_middle,
                                tree_[vertex].lazy_assignment);
          ReceiveLazyAssignment(RightChild(vertex), segment_middle + 1, segment_right,
                                tree_[vertex].lazy_assignment);
          tree_[vertex].lazy_assignment = Operator::Identity();
          return;
        }
      }
      if constexpr (LazyIncrement) {
        if (tree_[vertex].lazy_increment != Operator::Identity()) {
          ReceiveLazyIncrement(LeftChild(vertex), segment_left, segment_middle,
                               tree_[vertex].lazy_increment);
          ReceiveLazyIncrement(RightChild(vertex), segment_middle + 1, segment_right,
                               tree_[vertex].lazy_increment);
          tree_[vertex].lazy_increment = Operator::Identity();
        }
      }
    }
  }

  inline void ReceiveLazyAssignment(int vertex, int segment_left, int segment_right,
                                    const DataType& lazy_assignment) noexcept {
    tree_[vertex].lazy_assignment = lazy_assignment;
    tree_[vertex].value =
        Operator::CombineMultiple(lazy_assignment, segment_right - segment_left + 1);
    if constexpr (LazyIncrement) {
      tree_[vertex].lazy_increment = Operator::Identity();
    }
  }

  inline void ReceiveLazyIncrement(int vertex, int segment_left, int segment_right,
                                   const DataType& lazy_increment) noexcept {
    if constexpr (LazyAssignment) {
      if (tree_[vertex].lazy_assignment == Operator::Identity()) {
        tree_[vertex].lazy_increment =
            Operator::Combine(tree_[vertex].lazy_increment, lazy_increment);
      } else {
        tree_[vertex].lazy_assignment =
            Operator::Combine(tree_[vertex].lazy_assignment, lazy_increment);
        tree_[vertex].lazy_increment = Operator::Identity();
      }
    } else {
      tree_[vertex].lazy_increment =
          Operator::Combine(tree_[vertex].lazy_increment, lazy_increment);
    }
    tree_[vertex].value = Operator::IncrementMultiple(tree_[vertex].value, lazy_increment,
                                                      segment_right - segment_left + 1);
  }

  int next_valid_index_{};
  int data_size_{};
  std::vector<Node> tree_{};
};

struct OperatorAnd {
  static int Combine(int a, int b) {
    return a & b;
  }

  static int Identity() {
    return numeric_limits<int>::max();
  }
};

class Solution {
 public:
  long long countSubarrays(vector<int>& nums, int k) {
    int n = nums.size();
    SegmentTree<int, OperatorAnd> tree;
    tree.Build(nums);
    auto Compare1 = [&](int a) -> bool {
      return (k & a) == a;
    };
    auto Compare2 = [&](int a) -> bool {
      return ((k & a) == a) && a != k;
    };
    long long ret = 0;
    for (int i = 0; i < n; ++i) {
      int l = tree.FindFirstRightIndex(i, Compare1);
      if (l == -1) {
        l = n;
      }
      int r = tree.FindFirstRightIndex(i, Compare2);
      if (r == -1) {
        r = n;
      }
      ret += r - l;
      //cout << i << ' ' << l << ' ' << r << endl;
    }
    return ret;
  }
};

