class SegmentTree {
private:
    vector<int> tree;
    int n;

    void build(const vector<int> &arr, int start, int end, int node) {
        if (start == end) {
            tree[node] = arr[start];
        } else {
            int mid = (start + end) / 2;
            build(arr, start, mid, 2 * node + 1);
            build(arr, mid + 1, end, 2 * node + 2);
            tree[node] = tree[2 * node + 1] & tree[2 * node + 2];
        }
    }

    int query(int start, int end, int l, int r, int node) {
        if (r < start || end < l) { // no overlap
            return INT_MAX;
        }
        if (l <= start && end <= r) { // total overlap
            return tree[node];
        }
        // partial overlap
        int mid = (start + end) / 2;
        int left_query = query(start, mid, l, r, 2 * node + 1);
        int right_query = query(mid + 1, end, l, r, 2 * node + 2);
        return left_query & right_query;
    }

    void update(int start, int end, int idx, int value, int node) {
        if (start == end) {
            tree[node] = value;
        } else {
            int mid = (start + end) / 2;
            if (start <= idx && idx <= mid) {
                update(start, mid, idx, value, 2 * node + 1);
            } else {
                update(mid + 1, end, idx, value, 2 * node + 2);
            }
            tree[node] = tree[2 * node + 1] & tree[2 * node + 2];
        }
    }

public:
    SegmentTree(const vector<int> &arr) {
        n = arr.size();
        tree.resize(4 * n);
        build(arr, 0, n - 1, 0);
    }

    int query(int l, int r) {
        return query(0, n - 1, l, r, 0);
    }

    void update(int idx, int value) {
        update(0, n - 1, idx, value, 0);
    }
};


