typedef long long LL;
const int N = 100010, M = 20;
int st[N][M], a[N];

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        for(int i = 0; i < n; i++) {
            a[i + 1] = nums[i];
        }
        for(int j = 0; j < M; j++) {
            for(int i = 1; i + (1 << j) - 1 <= n; i++) {
                if(!j) {
                    st[i][j] = a[i];
                }else {
                    st[i][j] = st[i][j - 1] & st[i + (1<<(j - 1))][j - 1];
                }
            }
        }
        auto query = [&](int l, int r) {
            int k = log2(r - l + 1);
            return st[l][k] & st[r - (1<<k) + 1][k];
        };
        LL ans = 0;
        for(int i = 1; i <= n; i++) {
            int l = 1, r = i, left = 0, right = 0;
            while(l <= r) {
                int mid = l + r >> 1, res = query(mid, i);
                if(res > k) {
                    r = mid - 1;
                }else if(res < k) {
                    l = mid + 1;
                }else {
                    right = mid;
                    l = mid + 1;
                }
            }
            l = 1, r = i;
            while(l <= r) {
                int mid = l + r >> 1, res = query(mid, i);
                if(res > k) {
                    r = mid - 1;
                }else if(res < k) {
                    l = mid + 1;
                }else {
                    left = mid;
                    r = mid - 1;
                }
            }
            if(right > 0) ans += right - left + 1;
        }
        return ans;
    }
};

class Solution {
public:
