        return (f[k][l] & f[k][r - (1 << k) + 1]); 
    }

    int binSearch1(int l, int r, int k) {
        int i = l;  
        int ans = r + 1; 
        while (l <= r) {
            int mid = (l + r) >> 1; 
            if (get(i, mid) <= k) {
                ans = mid;  
                r = mid - 1; 
            }
            else {
                l = mid + 1; 
            }
        }
        return ans; 
    }

    int binSearch2(int l, int r, int k) {
        int i = l;  
        int ans = r + 1; 
        while (l <= r) {
            int mid = (l + r) >> 1; 
            if (get(i, mid) < k) {
                ans = mid;  
                r = mid - 1; 
            }
            else {
                l = mid + 1; 
            }
        }
        return ans; 
    }

    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size(); 
        for (int i = 1; i <= n; i++) a[i] = nums[i - 1]; 

        for (int i = 1; i <= n; i++) f[0][i] = a[i];  

        for (int k = 1; (1 << k) <= n; k++) {
            for (int i = 1; i + (1 << k) - 1 <= n; i++) {
                f[k][i] = (f[k - 1][i] & f[k - 1][i + (1 << (k - 1))]); 
            }
        }

        long long ans = 0;  
        for (int i = 1; i <= n; i++) {
            int l = binSearch1(i, n, k);  
            int r = binSearch2(i, n, k); 
            ans += r - l;  
        }

        return ans; 
    }
};

