class Solution {
public:
    long long countSubarrays(vector<int>& v, int k) {
        int dp[32] = {};
        for(int i = 0; i < 32; i++) dp[i] = -1;
        long long ans{};
        int n = v.size();
        for(int i = 0; i < n; i++){
            for(int j = 0; j < 32; j++){
                if((v[i]>>j) & 1) continue;
                dp[j] = i;
            }
            int st = 0, en = i;
            for(int j = 0; j < 32; j++){
                if((k>>j) & 1){
                    st = max(dp[j] + 1, st);
                }else{
                    if(dp[j] < st) {
                        st = i + 1;
                        break;
                    }
                    en = min(en, dp[j]);
                }
            }
            ans = ans + max(0, en - st + 1);
        }
        return ans;
    }
};

fn and_sum(count: &[i32; 32]) -> i32 {
    let mut result = 0;
    for i in 0..32 {
        if count[i] == 0 {
            result |= 1 << i;
        }
    }
    result
}

impl Solution {
    pub fn count_subarrays(nums: Vec<i32>, k: i32) -> i64 {
        let mut result = 0;
        let mut l1 = 0;
        let mut l2 = 0;
        let mut count1 = [0; 32];
        let mut count2 = [0; 32];
        for r in 0..nums.len() {
            for i in 0..32 {
                if (nums[r] >> i) & 1 == 0 {
                    count1[i] += 1;
                    count2[i] += 1;
                }
            }
            // println!("{:?}", &count1);
            while l1 <= r && and_sum(&count1) < k {
                for i in 0..32 {
                    if (nums[l1] >> i) & 1 == 0 {
                        count1[i] -= 1;
                    }
                }
                l1 += 1;
            }
            while l2 <= r && and_sum(&count2) <= k {
                for i in 0..32 {
                    if (nums[l2] >> i) & 1 == 0 {
                        count2[i] -= 1;
                    }
                }
                l2 += 1;
            }
            // println!("{} {} {}", r, l1, l2);
            result += (l2 - l1) as i64;
        }
        result
    }
}

