// https://github.com/kth-competitive-programming/kactl/blob/main/content/data-structures/RMQ.h
template<class T>
struct RMQ {
	vector<vector<T>> jmp;
	RMQ(const vector<T>& V) : jmp(1, V) {
		for (int pw = 1, k = 1; pw * 2 <= sz(V); pw *= 2, ++k) {
			jmp.emplace_back(sz(V) - pw * 2 + 1);
			rep(j,0,sz(jmp[k]))
				jmp[k][j] = jmp[k - 1][j] & jmp[k - 1][j + pw];
		}
	}
	T query(int a, int b) {
		assert(a < b); // or return inf if a == b
		int dep = 31 - __builtin_clz(b - a);
		return jmp[dep][a] & jmp[dep][b - (1 << dep)];
	}
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        const int n = nums.size();
        RMQ rmq(nums);

        long long ans = 0;
        for (int i = 0; i < n; ++i) {
            int lo, hi, mid;
            // find lower bound of x for nums[i:x] st AND-sum is k
            int lower = n+5;
            lo = i+1, hi = n;
            while (lo <= hi) {
                mid = lo + (hi - lo) / 2;
                if (rmq.query(i, mid) <= k) hi = (lower = mid) - 1;
                else lo = mid + 1;
            }
            // find upper bound of x for nums[i:x] st AND-sum is k
            int upper = n+1;
            lo = i+1, hi = n;
            while (lo <= hi) {
                mid = lo + (hi - lo) / 2;
                // printf("[%i,%i] m=%i \n", lo, hi, mid);
                if (rmq.query(i, mid) < k) hi = (upper = mid) - 1;
                else lo = mid + 1;
            }

            // std::cout << "i=" << i << " [" << lower << "," << upper << ")\n";

            ans += std::max(0, upper - lower);
        }
        // std::cout << std::endl;

        return ans;
    }
};

class Solution {
