class SparseTable {
    public:
    int** table;
    int LOGN;
    int size;

    int func(int a, int b) {
        return (a & b);
    }

    SparseTable(int a[], int n) {
        size = n;
        LOGN = 31 - __builtin_clz(n);
        table = new int* [LOGN + 1];

        table[0] = new int[n];
        for (int j = 0; j < n; j++) {
            table[0][j] = a[j];
        }

        for (int i = 1; i <= LOGN; i++) {
            int p = (1 << i);
            table[i] = new int[n - p + 1];
            for (int j = 0; j < n - p + 1; j++) {
                table[i][j] = func(table[i - 1][j], table[i - 1][j + (p >> 1)]);
            }
        }
    }

    SparseTable(vector<int> a) {
        int n = a.size();
        size = n;
        LOGN = 31 - __builtin_clz(n);
        table = new int* [LOGN + 1];

        table[0] = new int[n];
        for (int j = 0; j < n; j++) {
            table[0][j] = a[j];
        }

        for (int i = 1; i <= LOGN; i++) {
            int p = (1 << i);
            table[i] = new int[n - p + 1];
            for (int j = 0; j < n - p + 1; j++) {
                table[i][j] = func(table[i - 1][j], table[i - 1][j + (p >> 1)]);
            }
        }
    }

    ~SparseTable() {
        for (int i = 0; i <= LOGN; i++) {
            delete[] table[i];
        }
        delete[] table;
    }

    int query(int l, int r) {
        int k = 31 - __builtin_clz(r - l + 1);
        return func(table[k][l], table[k][r - (1 << k) + 1]);

    }

    void display() {
        for (int i = 0; i <= LOGN; i++) {
            cout << '{';
            for (int j = 0; j < size - (1 << i) + 1; j++) {
                cout << table[i][j] << ",}"[j == size - (1 << i)];
            }
            cout << '\n';
        }
    }

};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        long long ans = 0;
        int n = nums.size();
        SparseTable st(nums);

        for (int i = 0; i < n; i++) {
            if ((nums[i] & k) < k) continue;
            int in1 = -1, in2 = -1;
            int l = i - 1, r = n, mid;

            while (r - l > 1) {
                mid = (l + r) / 2;
                int res = st.query(i, mid);

                if (res >= k) l = mid;
                else r = mid;
            }

            in1 = l;

            l = i - 1;
            r = n;

            while (r - l > 1) {
                mid = (l + r) / 2;
                int res = st.query(i, mid);

                if (res > k) l = mid;
                else r = mid;
            }
            in2 = l;

            ans += in1 - in2;
        }

        return ans;
    }
};

