        r++;
        while (l < r) {
            int m = l + (r - l) / 2;

            if (predicate.test(m)) r = m;
            else l = m + 1;
        }

        return r;
    }

    public static long firstTrue(long l, long r, java.util.function.LongPredicate predicate) {
        r++;
        while (l < r) {
            long m = l + (r - l) / 2;

