class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        vector<array<int, 33>> cnt(n + 1);
        array<int, 31> m;
        long long ans = 0;
        for(int i = 0; i <= 30; i++){
            if(k & 1) m[i] = 1;
            else m[i] = 0;
            k >>= 1;
        }
        for(int i = 1; i <= n; i++){
            int now = nums[i - 1];
            int l = i, r = 0;
            for(int j = 0; j <= 30; j++){
                if(now & 1){
                    cnt[i][j] = cnt[i - 1][j] + 1;
                }else{
                    cnt[i][j] = 0;
                }
                if(m[j] == 1) l = min(l, cnt[i][j]);
                else if(m[j] != 1 && cnt[i][j] - cnt[i - 1][j] == 1) r = max(r, cnt[i][j]);
                now >>= 1;
            }
            if(l >= r) ans += l - r;
        }
        return ans;
    }
};

class Solution {
public:
    using ll = long long;
    const int kLog = 20;

    long long countSubarrays(vector<int>& a, int k) {
        int n = a.size();

        vector<vector<int>> st(n, vector<int>(kLog));
        for (int j = 0; j < kLog; j++) {
          for (int i = 0; i + (1 << j) <= n; i++) {
            if (j == 0) {
              st[i][j] = a[i];
              continue;
            }
            st[i][j] = st[i][j - 1] & st[i + (1 << (j - 1))][j - 1];
          }
        }

        auto Get = [&](int l, int r) {
          int k = __lg(r - l);
          return st[l][k] & st[r - (1 << k)][k];
        };

        ll ans = 0;
        for (int i = 0; i < n; i++) {
          int l = i - 1, r = n;
          while (r - l > 1) {
            int m = (l + r) / 2;
            if (Get(i, m + 1) > k) {
              l = m;
            } else {
              r = m;
            }
          }
          if (r == n) {
            continue;
          }
          if (Get(i, r + 1) != k) {
            continue;
          }
          int L = r;
          l = i - 1, r = n;
          while (r - l > 1) {
            int m = (l + r) / 2;
            if (Get(i, m + 1) >= k) {
              l = m;
            } else {
              r = m;
            }
          }
          int R = l;
          cout << L << " " << R << endl;
          ans += (R - L + 1);
        }

        return ans;
    }
};

