class Solution {
public:
  long long countSubarrays(vector<int>& a, int k) {
    int n = int(a.size());
    vector<int> last(30, -1);
    long long ans = 0;
    for (int i = 0; i < n; i++) {
      if ((a[i] & k) != k) {
        for (int j = 0; j < 30; j++) {
          if (((a[i] >> j) & 1) == 0) {
            last[j] = i;
          }
        }
        continue;
      }
      int l = -1;
      int r = i;
      for (int j = 0; j < 30; j++) {
        int bit_ai = ((a[i] >> j) & 1);
        int bit_k = ((k >> j) & 1);
        if (bit_ai == 0) {
          last[j] = i;
        }
        if (bit_ai != bit_k) {
          r = min(r, last[j]);
        } else if (bit_k == 1) {
          l = max(l, last[j]);
        }
      }
      ans += max(0, r - l);
    }
    return ans;
  }
};

class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        ret = 0

        index = [-1] * 31
        bits = []
        bits_ = []

        for i in range(len(nums)):
            a, b = -1, -1

            v = nums[i]
            if v == k:
                a = i

            for j in range(31):
                if not 1 << j & nums[i]:
                    bits_.append(j)
                    index[j] = i

            for j in bits:
                if 1 << j & nums[i]:
                    bits_.append(j)

            for j in bits:
                v &= nums[index[j]]
                if a < 0 and v == k:
                    a = index[j]
                elif v & k != k:
                    b = index[j]
                    break

            if a != -1:
                ret += a - b

            bits, bits_ = bits_, bits
            bits_.clear()

        return ret

