from typing import List
from collections import defaultdict

class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        t = 0
        pr = defaultdict(int)

        for i in range(n):
            cr = defaultdict(int)
            if nums[i] == k:
                t += 1
            cr[nums[i]] = 1
            for v, f in pr.items():
                nar = v & nums[i]
                if nar == k:
                    t += f
                cr[nar] += f

            pr = cr

        return t

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        const int n = (int)nums.size();
        vector<int> cnts(31, 0);
        long long ans = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < 31; ++j) {
                if (nums[i] & (1 << j)) {
                    cnts[j] = cnts[j] + 1;
                } else {
                    cnts[j] = 0;
                }
            }
            int l = 0, r=i+1;
            for (int j = 0; j < 31; ++j) {
                if (k & (1 << j)) {
                    r = min(r, cnts[j]);
                } else {
                    l = max(l, cnts[j] + 1);
                }
            }
            if (r - l + 1 > 0) {
                ans += (long long)(r-l+1);
            }
        }
        return ans;
    }
};

class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        ans = 0
        lastIter = defaultdict(int)
        thisIter = defaultdict(int)
        for x in nums:
            if x == k:
                ans += 1
            thisIter[x] += 1
            for y, cnt in lastIter.items():
                if x & y == k:
                    ans += cnt
                thisIter[x & y] += cnt
            lastIter, thisIter = thisIter, defaultdict(int)
        return ans

