class Solution {
    int B = 31;

    void update(vector<int>& f, int& x, int val) {
        for (int i = 0; i < B; i++) {
            if ((x >> i) & 1) {
                f[i] += val;
            }
        }
    }

    int get(vector<int>& f, int dis) {
        int res = 0;

        for (int i = 0; i < B; i++) {
            assert(f[i] <= dis);

            if (f[i] == dis) {
                res |= (1 << i);
            }
        }

        return res;
    }
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = (int) nums.size();
        long long res = 0;
        vector<int> f1(B), f2(B);
        int i = 0, l = 0, r = 0;
        int v1 = 0;

        // cout << v1 << " " << v2 << "\n";

        while (i < n) {
            l = max(l, i);
            v1 = get(f1, l - i);

            while (l < n && v1 != k && ((nums[l] & k) == k)) {
                update(f1, nums[l], 1);
                v1 &= nums[l];
                l++;
            }

            if (v1 == k) {
                r = max(r, l);

                while (r < n && ((nums[r] & k) == k)) {
                    // update(f2, nums[r], 1);
                    r++;
                }

                // cout << i << " " << l << "  "<< r << "\n";
                res += 1LL * (r - l + 1);
            }

            if (l != i) {
                update(f1, nums[i], -1);
            }

            i++;
        }

        return res;
    }
};

class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        groups = []
        cur = []
        for num in nums:
            if num & k == k:
                cur.append(num)
            else:
                if cur:
                    groups.append(cur)
                cur = []
        if cur:
            groups.append(cur)

        def count_subarrays(arr):
            res = 0
            # for each i-th bit, save the latest index with ith bit set to 0
            # we can start the subarray any place before (inclusive)
            num_bits = max(arr).bit_length()
            latest_zero_bit = [-1] * num_bits
            for index, num in enumerate(arr):
                for bit_index in range(num_bits):
                    if k & (1 << bit_index):
                        latest_zero_bit[bit_index] = index
                    elif not (num & (1 << bit_index)):
                        latest_zero_bit[bit_index] = index
                if -1 not in latest_zero_bit:
                    res += min(latest_zero_bit) + 1
            return res

        # print(f'{groups=}')
        return sum(count_subarrays(group) for group in groups)

