const ll SZ = 1e6;
ll inf;

vector<node> sgt(SZ);

void build(ll v , ll tl , ll tr , vector<int> &a){
    if(tl == tr){
        sgt[v].ad = a[tl];
    }
    else{
        ll tm = (tl + tr)>>1;

        build(2*v , tl , tm , a);
        build(2*v + 1 , tm + 1 , tr , a);

        sgt[v] = combine(sgt[2*v] , sgt[2*v+1]);
    }
}

ll query(ll v ,ll tl ,ll tr ,ll l , ll r){
    if(l > r) return inf;

    if(tl == l && tr == r){
        return sgt[v].ad;
    }
    ll tm = (tl + tr)>>1;

    ll num1 = query(2*v , tl , tm , l , min(tm , r));
    ll num2 = query(2*v + 1 , tm+1 , tr , max(l , tm + 1) , r);

    return (num1&num2);
}


class Solution {
public:
    long long countSubarrays(vector<int>& a, int k) {
        sgt.clear();
        ll n = a.size();
        sgt.resize(6*n + 50);

        inf = (1LL<<40) - 1;

        build(1 , 0 , n-1 , a);

        ll ans = 0;

        for(ll i = 0 ; i < n ; i++){
            if(a[i] < k) continue;


            ll mini = i , maxi = i-1;

            ll low = i , high = n-1;

            while(low <= high){
                ll mid = (low + high)>>1;

                ll num = query(1 , 0 , n-1 , i , mid);
                if(num == k){
                    mini = mid;
                    high = mid-1;
                    continue;
                }
                if(num > k && num != inf){
                    low = mid+1;
                }
                else{
                    high = mid-1;
                }
            }

            low = i ;
            high = n-1;

            while(low <= high){
                ll mid = (low + high)>>1;

                ll num = query(1 , 0 , n-1 , i , mid);
