class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        long long ans=0;
        int n=nums.size();
        vector<vector<int>> pref(n+1, vector<int>(31,0));
        for(int i=0;i<n;++i){
            for(int j=0;j<31;++j){
                if((nums[i]>>j)&1){
                    pref[i+1][j]=pref[i][j]+1;
                }
                else{
                    pref[i+1][j]=pref[i][j];
                }
            }
        }
        for(int i=0;i<n;++i){
            if(nums[i]<k) continue;
            int low=i,mid,high=n-1,lower=n,higher=n;
            while(low<=high){
                mid=(low+high)/2;
                int val=0;
                for(int j=0;j<31;++j){
                    int one=pref[mid+1][j]-pref[i][j];
                    int zero=mid-i+1-one;
                    if(one>0 && zero==0) val|=(1<<j);
                }
                if(val<=k){
                    lower=mid;
                    high=mid-1;
                } 
                else low=mid+1;
            }
            low=i;high=n-1;
            while(low<=high){
                mid=(low+high)/2;
                int val=0;
                for(int j=0;j<31;++j){
                    int one=pref[mid+1][j]-pref[i][j];
                    int zero=mid-i+1-one;
                    if(one>0 && zero==0) val|=(1<<j);
                }
                if(val>=k) low=mid+1;
                else{
                    higher=mid;
                    high=mid-1;
                }
            }
            //cout<<higher<<" "<<lower<<" ";
            ans+=higher-lower;

        }
        //cout<<endl;
        return ans;
    }
};

