class Solution {
public:
    long long countSubarrays(vector<int>& v, int K) {
         ll n=v.size();
         vector<vl>dp(n+1,vl(31,0));
         rep(i,0,31){
              for(int j=0;j<n;j++){
                   dp[j+1][i]=dp[j][i]+((v[j]>>i)&1);
              }
         } 

         auto check=[&](ll l,ll r,ll k){
              ll ans=0;
              for(int i=0;i<31;i++){
                   if((dp[r][i]-dp[l-1][i])==r-l+1){
                        ans+=(1<<i);
                   }
              }
              return ans>=k;
         };
        ll ret=0;
         for(int i=0;i<n;i++){
              ll l=i+1,k=K;
              ll lo=l,hi=n+1,ans=i;
              while(lo<hi){
                   ll mid=(lo+hi)/2;
                   if(check(l,mid,k)){
                        ans=mid;
                        lo=mid+1;
                   }
                   else{
                        hi=mid;
                   }
              }
              ll x=ans;
              k=K+1;
              l=i+1;
              lo=l,hi=n+1,ans=i;
              while(lo<hi){
                   ll mid=(lo+hi)/2;
                   if(check(l,mid,k)){
                        ans=mid;
                        lo=mid+1;
                   }
                   else{
                        hi=mid;
                   }
              }
             // cout<<i<<" "<<x<<" "<<ans<<endl;
             ret+=(x-ans);
         }
        return ret;
    }
};

class Solution {
public:
    bool issuper(int num, int k) {
        for (int i = 0; i < 32; i++) {
            if ((1 << i) & k) {
                if (((1 << i) & num) == 0) {
                    return false;
                }
            }
        }
        return true;
    }

    long long countSubarrays(vector<int>& nums, int k) {
        long long ans = 0;
        int l = 0;
        vector<int> zeros(32, 1e9);
        for (int r = 0; r < nums.size(); r++) {
            int x = nums[r];
            if (!issuper(x, k)) {
                l = r + 1;
                for (auto &i : zeros) i = 1e9;
                continue;
            }

            for (int i = 0; i < 32; i++) {
                if ((x & (1 << i)) == 0) {
                    zeros[i] = r;
                }
            }

            int maxi = 1e9;
            for (int i = 0; i < 32; i++) {
                if ((k & (1 << i)) == 0) {
                    maxi = min(maxi, zeros[i]);
                }
                if ((k & (1 << i)) == 0 && zeros[i] == 1e9) {
                    maxi = 1e9;
                    break;
                }
            }
            cout << l << " " << r << " " << maxi << endl;
            if (maxi < 1e9) ans += (long long)maxi - l + 1;
        }
        return ans;
    }
};

class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        prev_sub_arrays=Counter()
        res=0
        for n in nums:
            if n==k:res+=1
            prev_sub_arrays_temp=Counter([n])
            for key,v in prev_sub_arrays.items():
                prev_sub_arrays_temp[key&n]+=v
                if key&n==k:res+=v
            prev_sub_arrays=prev_sub_arrays_temp

        return res

