template<class S, S (*op)(S, S)>
struct sparse_table {
public:
	sparse_table() {}
	explicit sparse_table(const std::vector<S>& a) {
		n = (int) a.size();
		int max_log = std::__lg(n) + 1;
		mat.resize(max_log);
		mat[0] = a;
		for(int j = 1; j < max_log; ++j) {
			mat[j].resize(n - (1 << j) + 1);
			for(int i = 0; i <= n - (1 << j); ++i) {
				mat[j][i] = op(mat[j - 1][i], mat[j - 1][i + (1 << (j - 1))]);
			}
		}
	}

	S prod(int from, int to) const {
		assert(0 <= from && from <= to && to <= n - 1);
		int lg = std::__lg(to - from + 1);
		return op(mat[lg][from], mat[lg][to - (1 << lg) + 1]);
	}

private:
	int n;
	std::vector<std::vector<S>> mat;
};

using S = int;

S op(S a, S b) { return a & b; }

class Solution {
public:
    long long countSubarrays(vector<int>& a, int k) {
        int n = a.size();
        sparse_table<S, op> st(a);
        long long ans = 0;
        for(int i = 0; i < n; i++) {
            if(a[i] < k) {
                continue;
            }
            if(st.prod(i, n - 1) > k) {
                continue;
            }
            int l = i, start = i;
            if(a[i] > k) {
                int ng = i, ok = n;
                while(ok - ng > 1) {
                    int mid = (ng + ok) / 2;
                    if(st.prod(i, mid) > k) {
                        ng = mid;
                    } else {
                        ok = mid;
                    }
                }
                l = ng;
                start = ok;
            }
            int r = n;
            while(r - l > 1) {
                int mid = (l + r) / 2;
                if(st.prod(i, mid) >= k) {
                    l = mid;
                } else {
                    r = mid;
                }
            }
            ans += r - start;
            // cout << i << " " << start << " " << r << endl;
        }
        return ans;
    }
};

import math
from typing import List

class SparseTable:
    def __init__(self, array: List[int]):
        self.n = len(array)
        self.maxLog = int(math.log2(self.n)) + 1
        self.table = [[0] * self.maxLog for _ in range(self.n)]
        self.build(array)

    def combine(self, a: int, b: int) -> int:
        return a & b

    def build(self, array: List[int]):
        for i in range(self.n):
            self.table[i][0] = array[i]
        j = 1
        while (1 << j) <= self.n:
            i = 0
            while (i + (1 << j) - 1) < self.n:
                self.table[i][j] = self.combine(self.table[i][j - 1], self.table[i + (1 << (j - 1))][j - 1])
                i += 1
            j += 1

    def query(self, left: int, right: int) -> int:
        log = int(math.log2(right - left + 1))
        return self.combine(self.table[left][log], self.table[right - (1 << log) + 1][log])

class Solution:
    def countSubarrays(self, nums: List[int], target: int) -> int:
        st = SparseTable(nums)
        total_subarrays = 0
        n = len(nums)

        for start in range(n):
            left, right = start, n - 1
            min_index, max_index = -1, -1

            # Binary search for the minimum valid index
            while left <= right:
                mid = (left + right) // 2
                if st.query(start, mid) > target:
                    left = mid + 1
                else:
                    min_index = mid
                    right = mid - 1

            if min_index == -1 or st.query(start, min_index) != target:
                continue

            # Binary search for the maximum valid index
            left, right = start, n - 1
            while left <= right:
                mid = (left + right) // 2
                if st.query(start, mid) >= target:
                    left = mid + 1
                    max_index = mid
                else:
                    right = mid - 1

            total_subarrays += (max_index - min_index + 1)

        return total_subarrays

class SegmentTree {
    vector <int> ST;
    int n;

    void UPD(int id, int l, int r, int u, int g) {
        if (u < l || u > r) {
            return;
        }
        if (l == r) {
            ST[id] = g;
            return;
        }

        int mid = (l + r) / 2;
        UPD(id * 2, l, mid, u, g);
        UPD(id * 2 + 1, mid + 1, r, u, g);
        ST[id] = (ST[id * 2] & ST[id * 2 + 1]);
    }

    int GET(int id, int l, int r, int u, int v) {
        if (v < l || u > r) {
            return -1;
        }
        if (u <= l && r <= v) {
            return ST[id];
        }

        int mid = (l + r) / 2;
        int r1 = GET(id * 2, l, mid, u, v);
        int r2 = GET(id * 2 + 1, mid + 1, r, u, v);
        return (r1 & r2);
    }
public:
    SegmentTree(vector <int> v) {
        n = v.size();
        ST.assign(n * 4, 0);
        for (int i = 0; i < n; i++) {
            this->update(i, v[i]);
        }
    }

    void update(int u, int g) {
        UPD(1, 1, n, u + 1, g);
    }

    int get(int u, int v) {
        return GET(1, 1, n, u + 1, v + 1);
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        SegmentTree st(nums);
        int n = nums.size();
        long long res = 0;
        for (int i = 0; i < n; i++) {
            if ((nums[i] & k) < k) {
                continue;
            }
            int l = i, r = n;
            while (r > l) {
                int mid = (l + r) / 2;

                int andSum = st.get(i, mid);
                if ((andSum & k) == k) {
                    l = mid + 1;
                } else {
                    r = mid;
                }
            }
            res += l;
            l = i, r = n;
            while (r > l) {
                int mid = (l + r) / 2;
                int andSum = st.get(i, mid);
                if ((andSum & k) == k && andSum > k) {
                    l = mid + 1;
                } else {
                    r = mid;
                }
            }
            res -= l;
        }
        return res;
    }
};

typedef long long int ll;
class SegmentTree {
private:
    vector<int> t;

public:
    SegmentTree(int n) {
        t.resize(4*n);
    }

    void build(vector<int>& a, int v, int tl, int tr) {
        if (tl == tr) {
            t[v] = a[tl];
        } else {
            int tm = (tl + tr) / 2;
            build(a, v*2, tl, tm);
            build(a, v*2+1, tm+1, tr);
            t[v] = t[v*2] & t[v*2+1];
        }
    }

    int getAnd(int v, int tl, int tr, int l, int r) {
        if (l > r) {
            return ((1<<30) - 1);
        }
        if (l == tl && r == tr) {
            return t[v];
        }
        int tm = (tl + tr) / 2;
        int left = getAnd(v*2, tl, tm, l, min(r, tm));
        int right = getAnd(v*2+1, tm+1, tr, max(l, tm+1), r);
        // cout<<left<<" "<<right<<" "<<(left&right)<<endl;
        return left & right;
    }
};

