class Solution {
public:
    long long calc(vector<int> &ar) {
        if(ar.empty()) return 0;
        int b[32] = {};
        long long a = ar[0];
        int n = ar.size();
        int r = -1;
        for(int i = 0; i < n; i++) {
            a = (a & ar[i]);
            long long t = 1;
            for(int j = 0; j < 32; j++) {
                if((ar[i] & t) == t) {
                    b[j]++;
                }
                t *= 2;
            }
            if(a == 0) {
                r = i;
                break;
            }
        }
        if(r == -1) return 0;
        long long ans = n-r;
        for(int i = 1; i < n; i++) {
            long long t = 1;
            a = 0;
            for(int j = 0; j < 32; j++) {
                if((ar[i-1] & t) == t) {
                    b[j]--;
                }
                if(b[j] == r-i+1) {
                    a += t;
                }
                t *= 2;
            }

            if(a == 0) {
                ans += (n-r);
            } else {
                for(int k = r+1; k < n; k++) {
                    a = (a & ar[k]);
                    long long t1 = 1;
                    for(int j = 0; j < 32; j++) {
                        if((ar[k] & t1) == t1) {
                            b[j]++;
                        }
                        t1 *= 2;
                    }
                    if(a == 0) {
                        r = k;
                        break;
                    }
                }
                if(a == 0) {
                    ans += (n-r);
                } else {
                    break;
                }
            }
        }
        return ans;
    }
    long long countSubarrays(vector<int>& ar, int k) {
        int n = ar.size();
        vector<vector<int>> v;
        vector<int> c;
        for(int i = 0; i < n; i++) {
            if((ar[i]&k) == k) {
                c.push_back(ar[i]-k);
            } else {
                v.push_back(c);
                c = vector<int>();
            }
        }
        v.push_back(c);
        long long ans = 0;
        for(vector<int> &cc: v) {
            ans += calc(cc);
        }
        return ans;
    }
};

