struct sparse_table {
  vector<vector<int>> dp;
  int k = 0;
  sparse_table(int n, vector<int> &v) : k(__lg(n)) {
    dp.resize(k + 1, vector<int>(n));
    ranges::copy(v, dp[0].begin());
    for (int i = 1; i <= k; i++)
      for (int j = 0; j + (1 << i) <= n; j++) {
        auto a = dp[i - 1][j];
        auto b = dp[i - 1][j + (1 << (i - 1))];
        dp[i][j] = a & b;
      }
  }
  int query(int l, int r) {
    int ans = (1LL << 31) - 1;
    for (int i = k; i >= 0; i--) {
      if ((1 << i) <= r - l + 1) {
        auto a = ans;
        auto b = dp[i][l];
        ans = a & b;
        l += 1 << i;
      }
    }
    return ans;
  }
  int query_fast(int l, int r) { // only use if operation is idempotent!
    int i = __lg(r - l + 1);
    auto a = dp[i][l];
    auto b = dp[i][r - (1 << i) + 1];
    return min(a, b);
  }
};

template <typename T, typename U>
T first_true(T lo, T hi, U f) {
  ++hi;
  while (lo < hi) {
    T mid = lo + (hi - lo) / 2;
    f(mid) ? hi = mid : lo = mid + 1;
  }
  return lo;
}

template <typename T, typename U>
T last_true(T lo, T hi, U f) {
  --lo;
  while (lo < hi) {
    T mid = lo + (hi - lo + 1) / 2;
    f(mid) ? lo = mid : hi = mid - 1;
  }
  return lo;
}

class Solution {
public:
  long long countSubarrays(vector<int> &a, int k) {
    int n = a.size();
    sparse_table sp(n, a);
    long long ans = 0;
    for (int i = 0; i < n; i++) {
      int l = first_true(i, n - 1, [&](int m) {
        return sp.query(i, m) <= k;
      });
      int r = last_true(i, n - 1, [&](int m) {
        return sp.query(i, m) >= k;
      });
      if (l == n || r < i || sp.query(i, l) != k) {
        continue;
      }
      ans += r - l + 1;
    }
    return ans;
  }
};
