#include "bits/stdc++.h"
using namespace std;
using ll = long long int;

class Solution {
public:
    ll countSubarrays(vector<int>& nums, int k) {
        const int MAXBIT = 31;
        int n = nums.size();
        vector<vector<int>> pref(n, vector<int>(MAXBIT));
        for (int i = 0; i < n; i++) {
            for (int p = 0; p < MAXBIT; p++) {
                bool bit = nums[i] >> p & 1;
                pref[i][p] += bit;
                if (i - 1 >= 0) {
                    pref[i][p] += pref[i - 1][p];
                }
            }
        }
        ll ans = 0;
        for (int i = 0; i < n; i++) {
            int LOW = -1;
            {
                int lo = i;
                int hi = n - 1;
                while (lo <= hi) {
                    int mid = lo + hi >> 1;
                    ll num = 0;
                    for (int p = 0; p < MAXBIT; p++) {
                        int cnt = pref[mid][p];
                        if (i - 1 >= 0) {
                            cnt -= pref[i - 1][p];
                        }
                        if (cnt == mid - i + 1) {
                            num += 1LL << p;
                        }
                    }
                    if (num == k) {
                        LOW = mid;
                        hi = mid - 1;
                    } else if (num < k) {
                        hi = mid - 1;
                    } else {
                        lo = mid + 1;
                    }
                }
            }
            if (LOW == -1) {
                continue;
            }
            int HIGH = -1;
            {
                int lo = i;
                int hi = n - 1;
                while (lo <= hi) {
                    int mid = lo + hi >> 1;
                    ll num = 0;
                    for (int p = 0; p < MAXBIT; p++) {
                        int cnt = pref[mid][p];
                        if (i - 1 >= 0) {
                            cnt -= pref[i - 1][p];
                        }
                        if (cnt == mid - i + 1) {
                            num += 1LL << p;
                        }
                    }
                    if (num == k) {
                        HIGH = mid;
                        lo = mid + 1;
                    } else if (num < k) {
                        hi = mid - 1;
                    } else {
                        lo = mid + 1;
                    }
                }
            }
            assert(HIGH != -1);
            ll range = HIGH - LOW + 1;
            ans += range;
        }
        return ans;
    }
};

class Solution {
public:
  long long countSubarrays(vector<int>& nums, int k) {
    int64_t res = 0;
    unordered_map<int, int> prv_and, cur_and;
    for (auto num : nums) {
      if (num & k != k) {
        prv_and.clear();
        cur_and.clear();
        continue;
      }
      cur_and[num]++;
      for (auto [key, val] : prv_and) {
        if ((key & num & k) == k) {
          cur_and[key & num] += val;
        }
      }
      res += cur_and[k];
      swap(prv_and, cur_and);
      cur_and.clear();
    }
    return res;
  }
};

