class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        int la[n][31];
        FOR(i,0,n){
            FOR(j,0,31){
                if(!(nums[i]&(1<<j))){
                    la[i][j] = i;
                }else{
                    if(i == 0){
                        la[i][j] = -1;
                    }else{
                        la[i][j] = la[i-1][j];
                    }
                }
            }
        }
        ll ans = 0;
        FOR(i,0,n){
            int pl1 = -1;
            int pl2 = i+1;
            FOR(j,0,31){
                if(k&(1<<j)){
                    remax(pl1,la[i][j]+1);
                }else{
                    remin(pl2,la[i][j]);
                }
            }
            if(pl2 >= pl1 && pl2 >= 0 && pl1 <= i){
                pl1 = max(0,pl1);
                pl2 = min(pl2,i);
                ans += pl2-pl1+1;
            }
        }
        return ans;
    }
};

