class segtree{//1 based indexed segtree (point update,range query)  type-1
public:
  vector<ll> tree;
  segtree(ll n){
    tree.resize(4*n);
  }
  void build(ll ind,ll st,ll ed,vi &v){//(1,0,n-1,v)
     if(st==ed){
       tree[ind]=v[st];
       return;
     }
     ll mid=(st+ed)>>1;
     build(2*ind,st,mid,v);
     build(2*ind+1,mid+1,ed,v);
     tree[ind]=tree[2*ind]&tree[2*ind+1];
  }
  ll query(ll ind,ll st,ll ed,ll l,ll r){//range query, write @l,r; like update in type-2
     if(l<=st && ed<=r){
      return tree[ind];
     }
     if(r<st || l>ed){
        return LLONG_MAX;//Take care of this it will differ for diff types of queris
     }
     ll mid=(st+ed)>>1;
     ll left = query(2*ind,st,mid,l,r);
     ll right =query(2*ind+1,mid+1,ed,l,r);
     return left&right;
  }
};

class Solution {
public:
    ll getmx(segtree &s,ll ind,ll k,ll n){
       ll ans=ind-1;
       ll st=ind,ed=n-1;
       while(st<=ed){
         ll mid=(st+ed)>>1;
         ll val=s.query(1,0,n-1,ind,mid);
         if(val>k){
            ans=mid;
            st=mid+1;
         }
         else{
           ed=mid-1;
         }
       }
       return ans;
    }
    ll getmn(segtree &s,ll ind,ll k,ll n){
       ll ans=n;
       ll st=ind,ed=n-1;
       while(st<=ed){
         ll mid=(st+ed)>>1;
         ll val=s.query(1,0,n-1,ind,mid);
         if(val>=k){
            st=mid+1;
         }
         else{
          //  de(val)
           ans=mid;
           ed=mid-1;
         }
       }
       return ans;
    }
    long long countSubarrays(vector<int>& v, int k) {
        ll n=v.size(),ans=0;
        segtree st(n);
        st.build(1,0,n-1,v);
        for(int i=0;i<n;i++){
          ll chk=st.query(1,0,n-1,i,n-1);
          if(v[i]<k || chk>k) continue;
          ll x=getmn(st,i,k,n),y=getmx(st,i,k,n);
          // cout<<i<<" "<<x<<" "<<y<<endl;
          ll val=x-y-1;
          ans+=val;
        }
        return ans;
    }
};

impl Solution {
        pub fn count_subarrays(nums: Vec<i32>, k: i32) -> i64 {
            const UB: usize = 30;
            const OO: i32 = (1 << UB) - 1;
            let n = nums.len();
            let sb = {
                let mut sb = vec![Vec::with_capacity(n + 1); UB];
                for b_i in 0..UB {
                    let mut s = 0;
                    sb[b_i].push(s);
                    for (i, v) in nums.iter().enumerate() {
                        s += (v >> b_i) & 1;
                        sb[b_i].push(s);
                    }
                }
                sb
            };
            let get_and = |i: usize, j: usize| -> i32 {
                let w = (j - i) as i32;
                if w == 0 {
                    return OO;
                }
                let mut d = 0;
                for b_i in 0..UB {
                    let c = sb[b_i][j] - sb[b_i][i];
                    if c == w {
                        d |= 1 << b_i;
                    }
                }
                d
            };
            // for i in 0..n { for j in i..=n { println!("{i} {j}: {}", get_and(i, j)); } }
            let (mut r, mut i, mut j_s, mut j_t) = (0, 0, 0, 0);
            while i < n {
                if j_s < i {
                    j_s = i;
                }
                let mut cur_s = get_and(i, j_s);
                while j_s < n {
                    let v = cur_s & nums[j_s];
                    if v <= k {
                        break;
                    }
                    j_s += 1;
                    cur_s = v;
                }
                if j_t < j_s {
                    j_t = j_s;
                }
                let mut cur_t = get_and(i, j_t);
                while j_t < n {
                    let v = cur_t & nums[j_t];
                    if v < k {
                        break;
                    }
                    j_t += 1;
                    cur_t = v;
                }
                r += (j_t - j_s) as i64;
                // println!("[{i}] {} | {j_s} ({cur_s}) | {j_t} ({cur_t}) => {r}", nums[i]);
                i += 1;
            }
            r
        }

}

