class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:

        n = len(nums)
        vmax = max(max(nums), k)
        m = len(bin(vmax)) - 2

        loc = [[] for _ in range(m)]
        for i,x in enumerate(nums):
            bin_x = bin(x)[2:].zfill(m)
            for j,y in enumerate(bin_x):
                if y == '0': loc[j].append(i)
        #print('loc =', loc)
        bin_k = bin(k)[2:].zfill(m)

        ans = 0
        for i,x in enumerate(nums):
            bin_x = bin(x)[2:].zfill(m)
            #print(i, bin_x, bin_k)
            lb, ub = i, n
            for j in range(m):
                xj, kj = bin_x[j], bin_k[j]
                if kj == '0':
                    if xj == '1':
                        idx = bisect_right(loc[j], i)
                        if idx < len(loc[j]):
                            lb = max(lb, loc[j][idx])
                        else: lb = n
                else:
                    if xj == '0': lb = n
                    else:
                        idx = bisect_right(loc[j], i)
                        if idx < len(loc[j]):
                            ub = min(ub, loc[j][idx])
                if lb >= ub: break
            #print(lb, ub)
            if lb < ub: ans += ub - lb
        return ans

