class Solution {
    public long countSubarrays(int[] nums, int k) {

        int [][] zero = new int [nums.length][30];

        int [] current = new int [30];
        Arrays.fill(current, nums.length);

        for (int i = nums.length - 1; i >= 0; --i) {

            for (int j = 0; j < current.length; ++j) {
                int bit = ((1 << j) & nums[i]) == 0 ? 0 : 1;
                if (bit == 0) {
                    current[j] = i;
                }
                zero[i][j] = current[j];
            }
        }

        int min, max, mid;

        long result = 0;

        for (int i = 0; i < nums.length; ++i) {
            if (nums[i] < k)
                continue;

            min = i - 1;
            max = nums.length;

            while (max - min > 1) {
                mid = (max + min) / 2;

                if (getAnd(zero, i, mid) > k)
                    min = mid;
                else
                    max = mid;
            }

            min++;

            if (min == nums.length || getAnd(zero, i, min) != k)
                continue;

            int start = min;

            //System.out.println(i + " " + min);

            min = start;
            max = nums.length;

            while (max - min > 1) {
                mid = (max + min) / 2;

                if (getAnd(zero, i, mid) != k)
                    max = mid;
                else
                    min = mid;
            }

            //System.out.println(i + " " + max + " " + start);

            result += max - start;
        }

        return result;
    }


    private int getAnd(int [][] zero, int l, int r) {

        int result = (int)Math.pow(2, 30);
        --result;

        for (int i = 0; i < 30; ++i) {
            if (zero[l][i] <= r)
                result ^= 1 << i;
        }


        return result;
    }
}

