type SparseTable struct {
	func_ func(int, int) int
	st    [][]int
}

// NewSparseTable initializes and returns a new SparseTable
func NewSparseTable(nums []int, function func(int, int) int) *SparseTable {
	st := [][]int{nums}
	n := len(nums)
	i := 1
	for (i << 1) <= n {
		pre := st[len(st)-1]
		next := make([]int, n-(i<<1)+1)
		for j := 0; j < len(next); j++ {
			next[j] = function(pre[j], pre[j+i])
		}
		st = append(st, next)
		i <<= 1
	}
	return &SparseTable{func_: function, st: st}
}

// Query performs a range query on the sparse table
func (st *SparseTable) Query(begin, end int) int {
	lg := int(math.Log2(float64(end-begin+1)))
	return st.func_(st.st[lg][begin], st.st[lg][end-(1<<lg)+1])
}


func countSubarrays(nums []int, k int) int64 {
	funcAnd := func(a, b int) int { return a & b }
	st := NewSparseTable(nums, funcAnd)
	n := len(nums)
	ans := 0

	for i := 0; i < n; i++ {
		left, right := i, n-1
		for left <= right {
			mid := (left + right) / 2
			if st.Query(i, mid) <= k {
				right = mid - 1
			} else {
				left = mid + 1
			}
		}
		l := left

		left, right = i, n-1
		for left <= right {
			mid := (left + right) / 2
			if st.Query(i, mid) <= k-1 {
				right = mid - 1
			} else {
				left = mid + 1
			}
		}
		r := right

		ans += r - l + 1
	}

	return int64(ans)
}

