                  if(query == k) {
                    lb = mid;
                    R = mid - 1;
                  } else {
                    R = mid - 1;
                  }
                }
            }
            L = i;
            R = nums.size() - 1;
            int ub = -1;
            while(L <= R) {
                int mid = L + (R - L) / 2;
                int query = st.prod(i, mid + 1);
                if(query > k) {
                  L = mid + 1;
                } else {
                  if(query == k) {
                    ub = mid;
                    L = mid + 1;
                  } else {
                    R = mid - 1;
                  }
                }
            }
            // cout << i << " " << lb << " " << ub << endl;
            if(lb == -1) {
              continue;
            } else {
              ans += (ll)(ub - lb + 1);
            }
        }
        return ans;
    }
};

using LL = long long;
class Solution {
public:
    long long countSubarrays(vector<int>& a, int k) {
        const int n = a.size();
        // for (int &x : a) x &= k;
        vector<array<uint32_t,20>> d(n);
        for (int j = 0; j < 20; ++j) {
            for (int i = 0; i < n; ++i) {
                if (j == 0) {
                    d[i][j] = a[i];
                } else if (i + (1 << j) <= n) {
                    d[i][j] = d[i][j-1] & d[i+(1<<(j-1))][j-1];
                }
                // cout << "d " << i << ' ' << j << ' ' << d[i][j] << endl;
            }
        }
        auto S = [&](int i, int len) {
            uint32_t r = a[i];
            for (int j = 19; j >= 0 && len > 0; --j) {
                int t = 1 << j;
                if (len >= t) {
                    r &= d[i][j];
                    len -= t;
                    i += t;
                }
            }
            return r;
        };
        long long ans = 0;
        for (int i = 0; i < n; ++i) {
            if ((a[i] & k) < k) continue;
            int l = 1, r = n - i, lb = -1;
            while (l <= r) {
                const int m = (l + r) >> 1;
                int t = S(i, m);
                if ((t & k) < k) r = m - 1;
                else {
                    if (t == k) {
                        lb = i + m - 1;
                        r = m - 1;
                    } else {
                        l = m + 1;
                    }
                }
            }
            if (lb == -1) continue;

            l = 1, r = n - lb;
            int rb = lb;
            while (l <= r) {
                const int m = (l + r) >> 1;
                int t = S(lb, m);
                if ((t & k) < k) r = m - 1;
                else {
                    rb = lb + m - 1;
                    l = m + 1;
                }
            }
            // cout << i << ": " << lb << " - " << rb << endl;
            ans += rb - lb + 1;
        }
        return ans;
    }
};

typedef long long ll;
struct sparseTable
 {
     //sparseTable sp1;
     //sp1.init(n(size));
     //sp1.build(left(array));
     ll n,k;
     vector< vector<ll> > table;
     vector<ll> logs;

     void init1(ll x)
     {
             n=x;
             logs.resize(n+1);
             logs[1]=0;
             for(ll i=2;i<=n;i++)
                     logs[i]=logs[i/2]+1;
             k=*max_element(logs.begin(),logs.end());
             table.resize(k+1,vector<ll> (n+1,-1e9) );
     }

     ll operation(ll x,ll y)
     {
         return x&y;
     }

     void build(vector<ll> &arr)
     {
         for(ll i=0;i<n;i++)
                 table[0][i]=arr[i];

         for(ll j=1;j<=k;j++)
         {
             for(ll i=0;i+(1<<j)<=n;i++)
                 table[j][i]=operation(table[j-1][i],table[j-1][i+(1<<(j-1))]);
         }
     }

     ll query(ll l , ll r)
     {
         ll j = logs[r - l + 1];
         ll answer = operation(table[j][l], table[j][r-(1<<j)+1]);
         return answer;
     }
 }; 

