class Solution {
public:


    #define ll long long 


    void build(int nl, int nr, int tidx, vector<ll> &tree, vector<int> &nums) {
        if(nl == nr) {
            tree[tidx] = (ll)nums[nl];
            return;
        }
        int mid = (nl+nr)/2; 
        build(nl, mid, 2*tidx+1, tree, nums);
        build(mid+1, nr, 2*tidx+2, tree, nums);

        tree[tidx] = (tree[2*tidx+1] & tree[2*tidx+2]); 
    }

    ll powe(ll a, ll b) {
        ll res = 1;
        while(b) {
            if(b%2) {
                res *= a; 
            }
            b/=2;
            a*=a;
        }
        return res;
    }

    ll query(int nl, int nr, int tidx, int l, int r, vector<ll> &tree) {
        if(nl > r or nr < l) {
            ll a = 2;
            ll b = 31;
            ll temp = powe(a, b) - 1;
            return temp;
        }
        if(nl >= l and nr <= r) return tree[tidx];

        int mid = (nl+nr)/2;
        ll left = query(nl, mid, 2*tidx+1, l, r, tree);
        ll right = query(mid+1, nr, 2*tidx+2, l, r, tree);

        return (left & right);
    }

    ll countSubarrays(vector<int>& nums, int k) {

        int n = nums.size();
        vector<ll> tree(4*n+1, 0);
        build(0, n-1, 0, tree, nums);

        ll res = 0;

        for(int i = 0; i < n; i++) {

            int lo = 0, hi = i;

            ll idx1 = -1, idx2 = -1; 
            // finding AND just greater than k
            while(lo <= hi) {
                int mid = (lo+hi)/2; 

                ll a = query(0, n-1, 0, mid, i, tree);
                if(a > k) {
                    idx1=mid;
                    hi = mid-1;
                } else {
                    lo=mid+1;
                }
            }
            // findind AND just smaller than k

            lo = 0, hi = i;
            while(lo <= hi) {
                int mid = (lo+hi)/2;
                int a = query(0, n-1, 0, mid, i, tree);

                if(a < k) {
                    idx2 = mid;
                    lo = mid+1;
                } else { 
                    hi = mid-1; 
                }
            }

            if(idx1 == -1 and idx2 == -1) {
                res += (ll)(i+1); 
            } else if(idx1 == -1) {
                res += (ll)(i-idx2);
            } else if(idx2 == -1) {
                res += (ll)(idx1);
            } else {
                res += (ll)(idx1-idx2-1);
            }

        }

        return res;
    }
};

