class Solution {
public:
struct SparseTable {
    vector<vector<int> > sp;
    vector<int> LOG;
    vector<int> arr;
    int n, LG;
    SparseTable(vector<int> &_arr) : arr(_arr) {
        n = (int)_arr.size();

        LOG = vector<int>(n + 1);
        LOG[0] = LOG[1] = 0;

        for (int i = 2; i <= n; ++i) {
            LOG[i] += LOG[i - 1] + !(i & (i - 1));
        }

        LG = LOG[n];
        sp = vector<vector<int> >(LG + 1, vector<int>(n));

        build();
    }

    int f(int lfV, int rtV) {
        return lfV& rtV;
    }

    void build() { // O( n log(n) )
        sp[0] = arr;

        for (int lvl = 1; lvl <= LG; ++lvl) {
            for (int j = 0; j + (1 << lvl) <= n; ++j) {
                sp[lvl][j] = f(sp[lvl - 1][j], sp[lvl - 1][j + (1 << (lvl - 1))]);
            }
        }
    }

    int Query1(int l, int r) { // O( 1 )
        int lg = LOG[r - l + 1];

        return f(sp[lg][l], sp[lg][r - (1 << lg) + 1]);
    }

    int Query2(int l, int r) { // O( LogN )
        int lg = LOG[n];
        int ans = 0;

        for (int j = lg; ~j; --j) {
            if ((1 << j) <= (r - l + 1)) {
                ans = f(ans, sp[j][l]);
                l += (1 << j);
            }
        }

        return ans;
    }
};

    long long countSubarrays(vector<int>& nums, int k) {
        long long res = 0;
        SparseTable sp(nums);
        int n = nums.size();
        for(int i = 0;i<nums.size();i++){
            int left = i , right = n - 1;
            if(nums[i] < k)continue;
            int f1 = -1;
            while(left <= right){
                int mid = left + (right - left) / 2;
                if(sp.Query1(i , mid) > k){
                    left = mid + 1;
                }else
                    right = mid - 1 , f1 = mid;
            }
            if(f1 == -1 || sp.Query1(i , f1) != k)continue;
            int f2 = -1;
            left = i , right = n - 1;
            while(left <= right){
                int mid = left + (right - left) / 2;
                if(sp.Query1(i , mid) >= k){
                    left = mid + 1;
                    f2 = mid;
                }else
                    right = mid - 1;
            }
            assert(f2 != -1);
            res += (f2 - f1 + 1);
        }
        return res;
    }
};

