class Solution {
public:
    ll calc(ll from, ll to, vector<vector<ll>>& pref) {
        ll res = 0;
        REP(j, 32) if (pref[to+1][j] - pref[from][j] == to-from+1) res |= (1<<j);
        return res;
    }

    long long countSubarrays(vector<int>& nums, int k) {
        ll n = nums.size();
        vector<vector<ll>> pref(n+1, vector<ll>(32, 0));
        REP(i, n) {
            REP(j, 32) pref[i+1][j] = pref[i][j];
            REP(j, 32) if (nums[i] & (1<<j)) pref[i+1][j]++;
        }

        vector<ll> v(n, 0); REP(i, n) if ((nums[i] & k) == k) v[i] = 1;
        vector<ll> len(n+1, 0); 
        for (ll i = n-1; i >= 0; i--) if (v[i] == 1) len[i] = 1 + len[i+1];

        ll res = 0;
        REP(i, n) {
            if (v[i] == 0) continue;
            if (nums[i] == k) { res += len[i]; continue; }
            ll l = i; ll h = i+len[i]-1; if (calc(i, h, pref) > k) continue;
            while (l < h) {
                ll m = (l+h)/2;
                calc(i, m, pref) == k ? h = m : l = m+1;
            }
            res += (i+len[i]-1 - l + 1);
        }
        return res;
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        long long ans = 0;
        int n = nums.size();
        vector<vector<int>> bits(n + 1, vector<int> (31));
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 31; j++) {
                bits[i + 1][j] = (nums[i] >> j) & 1;
                bits[i + 1][j] += bits[i][j];
            }
        }

        map<long long, long long> prev;
        for (int i = 0; i < n; i++) {
            map<long long, long long> last = {{nums[i], 1}};
            ans += (nums[i] == k);
            for (auto &x : prev) {
                if ((x.first & nums[i]) == k) ans += x.second;
                last[x.first & nums[i]] += x.second;
            }
            prev = last;
        }
        return ans;
    }
};

