class Solution {
public:
    int rangeAndQuery(vector<vector<int>>& AndArr , int l , int r){
        int num = 0;
        for(int i = 0 ; i < 32 ; ++i){
            if((AndArr[r][i] - (l == 0 ? 0 : AndArr[l - 1][i])) == (r - l + 1)){
                num |= (1 << i);
            }
        }
        return num;
    }
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        vector<vector<int>> v(n , vector<int> (32 , 0));
        for(int i = 0 ; i < n ; ++i){
            for(int j = 0 ; j < 32 ; ++j){
                if(i != 0){
                    v[i][j] = v[i - 1][j];
                }
                if((nums[i] >> j) & 1){
                        v[i][j]++;
                }
            }
        }
        long long ans = 0;
        for(int i = 0 ; i < n ; ++i){
            int b = i , e = n - 1;
            int at = -1;
            while(b <= e){
                int mid = b + (e - b) / 2;
                int val = rangeAndQuery(v , i , mid);
                if(val == k){
                    at = mid;
                    e = mid - 1;
                }
                else if(val > k){
                    b = mid + 1;
                }
                else{
                    e = mid - 1;
                }
            }
            if(at == -1)continue;
            int at2 = at;
            b = at;
            e = n - 1;
            while(b <= e){
                int mid = b + (e - b) / 2;
                int val = rangeAndQuery(v , i , mid);
                if(val == k){
                    at2 = mid;
                    b = mid + 1;
                }
                else if(val < k){
                    e = mid - 1;
                }
                else{
                    b = mid + 1;
                }
            }
            ans += (at2 - at + (long long)1);
        }
        return ans;
    }
};

