class SegTree{
private:
    int n;
    vector<int> tr;
public:
    SegTree(int N){
        n = N;
        tr.resize(4*n+1,0);
    }
    void update(int ind,int val,int low,int high,int i){
        if(low == high){
            tr[ind] = val;
            return;
        }
        int mid = (low+high)/2;
        if(i<=mid)  update(2*ind+1,val,low,mid,i);
        else    update(2*ind+2,val,mid+1,high,i);
        tr[ind] = (tr[2*ind+1]&tr[2*ind+2]);
    }
    int query(int ind,int low,int high,int l,int r){
        // low high l r     l r low high
        if(high < l || r < low) return INT_MAX;
        // l low high r
        if(low >=l && high <= r)    return tr[ind];
        int mid = (low+high)/2;
        return (query(2*ind+1,low,mid,l,r)&query(2*ind+2,mid+1,high,l,r));
    }
};
class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n=nums.size();
        long long res = 0;
        SegTree tr(n);
        for(int i=0;i<n;i++){
            tr.update(0,nums[i],0,n-1,i);
            // cout<<tr.query(0,0,n-1,i,i)<<" ";
        }
        for(int i=0;i<n;i++){
            int l=i,u=n-1;
            if(nums[i] < k) continue;
            int ans = -1;
            while(l<=u){
                int mid = (l+u)/2;
                int qr = tr.query(0,0,n-1,i,mid);
                if(qr == k){
                    ans = mid;
                    u = mid-1;
                }
                else if(qr < k){
                    u = mid-1;
                }
                else{
                    l = mid+1;
                }
            }
            int low = ans;
            l = i,u = n-1;
            ans = -1;
            while(l<=u){
                int mid = (l+u)/2;
                int qr = tr.query(0,0,n-1,i,mid);
                // cout<<mid<<" "<<qr<<endl;
                if(qr == k){
                    ans = mid;
                    l = mid+1;
                }
                else if(qr < k){
                    u = mid-1;
                }
                else{
                    l = mid+1;
                }
            }
            int high = ans;
            // cout<<low<<" "<<high<<endl;
            if(high != -1)
                res += high-low+1;
        }
        return res;
    }
};

#define TMID (tl + (tr - tl) / 2)
#define TLEFT (tn + 1)
#define TRIGHT (tn + 2 * (TMID - tl + 1))
class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        using ll = long long;
        int n = nums.size();
        ll all =  (1ll << 32) - 1;
        std::vector<int> tree(2 * n, all);
        auto rangeAnd = [&](ll rq, ll x) {
            ll lq = 0;
            auto f = [&](auto &&f, ll tn, ll tl, ll tr) -> void {
                if (rq < tl || tr < lq) {
                } else if (lq <= tl && tr <= rq) {
                    tree[tn] &= x;
                } else {
                    f(f, TLEFT, tl, TMID);
                    f(f, TRIGHT, TMID + 1, tr);
                }
            };
            return f(f, 0, 0, n - 1);
        };

        auto query = [&](ll i) {
            auto f = [&](auto &&f, ll tn, ll tl, ll tr) -> ll {
                if (tl == tr) {
                    return nums[tl];
                } else if (i <= TMID) {
                    return tree[tn] & f(f, TLEFT, tl, TMID);
                }
                return tree[tn] & f(f, TRIGHT, TMID + 1, tr);
            };
            return f(f, 0, 0, n - 1);
        };

        ll ans = 0;
        for (int i = 0; i < n; ++i) {
            rangeAnd(i, nums[i]);
            int l = 0, r = i + 1;
            while (l < r) {
                int m = l + (r - l) / 2;
                if (query(m) > k) {
                    r = m;
                } else {
                    l = m + 1;
                }
            }
            int gt = l;
            l = -1, r = i;
            while (l < r) {
                int m = l + (r - l + 1) / 2;
                if (query(m) < k) {
                    l = m;
                } else {
                    r = m - 1;
                }
            }
            int lt = l;
            ans += std::max(0, gt - lt - 1);
        }

        return ans;
    }
};

