class Solution {
public:
    long long countSubarrays(vector<int>& a, int k) {
        using ll = long long;
        ll n = a.size(), ans =0;
        vector<ll>latestZero(32, -1);
        vector<ll>runningOnes(32, 0);
        for(int i=0; i<n; i++) {
            ll oneBound = 0, zeroBound = i;
            for(int bit = 0; bit<32; bit++) {
                if(a[i]&(1<<bit)) {
                    runningOnes[bit]++;
                }
                else {
                    runningOnes[bit]=0;
                    latestZero[bit] = i;
                }

                int kbit = (k>>bit)&1;
                if(kbit) {
                    oneBound = max(oneBound, i+1-runningOnes[bit]); 
                    // 0, 1         , 1, 1, 1, 1, 1
                    //  , i+1-runBit, .........., i
                } else {
                    zeroBound = min(zeroBound, latestZero[bit]);
                }
            }
            ans += max(0ll, zeroBound - oneBound + 1);
        }
        return ans;
    }
};

