class Solution {
public:
    int t[400050];
    void build(vector<int>&a, int v, int tl, int tr) {
        if (tl == tr) {
            t[v] = a[tl];
        } else {
            int tm = (tl + tr) / 2;
            build(a, v*2, tl, tm);
            build(a, v*2+1, tm+1, tr);
            t[v] = (t[v*2] & t[v*2+1]);
        }
    }
    int sum(int v, int tl, int tr, int l, int r) {
        if (l > r) 
            return ((1ll<<31) -1);
        if (l == tl && r == tr) {
            return t[v];
        }
        int tm = (tl + tr) / 2;
        return (sum(v*2, tl, tm, l, min(r, tm)) & sum(v*2+1, tm+1, tr, max(l, tm+1), r));
    }

    int findLowest(int index, int k, int n){
        int lo = index,  hi = n-1;
        int ans = -1;
        while(lo<=hi){
            int mid = (lo+hi)/2;
            int val = sum(1,0,n-1,index,mid);
            if(val == k){
                ans = mid;
                hi = mid-1;
            }
            else if(val>k){
                lo = mid+1;
            }else{
                hi = mid-1;
            }
        }
        return ans;
    }
    int findLargest(int index, int k, int n){
        int lo = index,  hi = n-1;
        int ans = -1;
        while(lo<=hi){
            int mid = (lo+hi)/2;
            int val = sum(1,0,n-1,index,mid);

            if(val == k){
                ans = mid;
                lo = mid+1;
            }
            else if(val>k){
                lo = mid+1;
            }else{
                hi = mid-1;
            }
        }
        return ans;
    }
