template <typename T> class SegmentTreeIterative {
public:
    T seg[800080],segBase;
    int n,sz,lsz;
    function<T(T, T)> compare_operation;
    SegmentTreeIterative(function<T(T, T)> given_compare_op, T newSegBase) {
        compare_operation = given_compare_op;
        segBase = newSegBase;
    }
    void reset(int newN) {
        n = newN;
        assert(n * 4 <= sizeof(seg)/sizeof(seg[0]));
        sz = 1; while (sz < n) sz *= 2;
        lsz = __builtin_ctzll(sz);
        for (int i= 0; i<(sz*2); i++) {seg[i] = segBase;}
    }
    void update(int pos, T x) {doUpdate(pos-1, x);}
    void doUpdate(int pos0index, T x) {
        assert(pos0index >= 0 && pos0index < n);
        int p = pos0index + sz; seg[p] = x;
        for (int i = 1; i <= lsz; i++) modify(p >> i);
    }
    T query(int l, int r) {return doQuery(l-1, r);}
    T doQuery(int l0index, int r0index) {
        assert(l0index >= 0 && l0index <= r0index && r0index <= n);
        int l = l0index + sz, r = r0index + sz;
        T lans = segBase, rans = segBase;
        while (l < r) {
            if (l & 1) lans = compare_operation(lans, seg[l++]);
            if (r & 1) rans = compare_operation(seg[--r], rans);
            l = (l >> 1); r = (r >> 1);
        }
        return compare_operation(lans, rans);
    }
    void modify(int k) {seg[k] = compare_operation(seg[2*k], seg[2*k + 1]);}
    T trueValue(int index) {assert(index >= 1 && index <= n); return seg[index-1+sz];}
    T true0indexValue(int index0) {assert(index0 >= 0 && index0 < n); return seg[index0 + sz];}
};
