int st[1 << 20];

void build(const vector<int>& a, int l, int r, int idx){
    if(l == r){
        st[idx] = a[l];
        return;
    }
    int m = l + r >> 1;
    build(a, l, m, idx * 2 + 1);
    build(a, m + 1, r, idx * 2 + 2);
    st[idx] = st[idx * 2 + 1] & st[idx * 2 + 2];
}

int qry(int l, int r, int tl, int tr, int idx){
    if(tl > r || tr < l) return INT_MAX;
    if(tl >= l && tr <= r) return st[idx];
    int tm = tl + tr >> 1;
    return qry(l, r, tl, tm, idx * 2 + 1) & qry(l, r, tm + 1, tr, idx * 2 + 2);
}

class Solution {
public:
    long long countSubarrays(vector<int>& a, int k) {
        int n = a.size();
        build(a, 0, n - 1, 0); 

        long long res = 0;
        for(int i = 0; i < n; ++i){
            int left = -1, right = -1;
            for(int l = i, r = n - 1; l <= r; ){
                int m = l + r >> 1;
                int x = qry(i, m, 0, n - 1, 0);
                if(x == k){
                    left = m;
                    r = m - 1;
                }else{
                    if(x < k){
                        r = m - 1;
                    }else
                        l = m + 1;
                }
            }

            for(int l = i, r = n - 1; l <= r; ){
                int m = l + r >> 1;
                int x = qry(i, m, 0, n - 1, 0);
                if(x == k){
                    right = m;
                    l = m + 1;
                }else{
                    if(x < k){
                        r = m - 1;
                    }else
                        l = m + 1;
                }
            }
            if(left != -1){
                res += 1ll * (right - left + 1);
            }
        }
        return res;
    }
};

