class Solution {
public:
    long long countSubarrays(vector<int>& arr, int k) {
        ll n = arr.size();
        vector<vector<ll>> pre(n + 1, vector<ll>(31, 0));
        for(ll i = 1; i <= n; i++){
            for(ll bit = 0; bit < 31; bit++){
                if((1LL << bit) & arr[i - 1]){
                    pre[i][bit]++;
                }
            }
            for(ll bit = 0; bit < 31; bit++){
                pre[i][bit] += pre[i-1][bit];
            }
        }
        auto check = [&](ll j, ll i) -> ll{
            if(j > i){
                return -1;
            }
            ll curr = 0;
            for(ll bit = 0; bit < 31; bit++){
                if(pre[i][bit] - pre[j - 1][bit] == (i - j + 1)){
                    curr += (1LL << bit);
                }
            }
            return curr;
        };
        ll ans = 0;
        for(ll i = 1; i <= n; i++) {
            ll low = 1, high = i;
            ll id = 0;
            while(low <= high) {
                ll mid = (low + high) >> 1;
                if(check(mid, i) >= k) {
                    id = mid;
                    high = mid - 1;
                } else {
                    low = mid + 1;
                }
            }
            low = 1, high = i;
            ll id1 = 0;
            while(low <= high) {
                ll mid = (low + high) >> 1;
                if(check(mid, i) <= k) {
                    id1 = mid;
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }
            if(id != 0) ans += (id1 - id + 1);
        }
        return ans;
    }
};

