            int l = i, r = n - 1, L = -1, R = n;
            while (l <= r) {
                int mid = (l + r) / 2;
                int x = sp.query(i, mid);
                if ((k & x) != k) {
                    r = mid - 1;
                } else if (k == x) {
                    L = mid;
                    r = mid - 1;
                } else {
                    l = mid + 1;
                }
            }
            if (L == -1) continue;
            l = i, r = n - 1;
            while (l <= r) {
                int mid = (l + r) / 2;
                int x = sp.query(i, mid);
                if ((k & x) != k) {
                    R = mid;
                    r = mid - 1;
                } else {
                    l = mid + 1;
                }
            }
            ans += R - L;
        }
        return ans;
    }
};

