    void upd(int p,int l,int r,int k,int x){
        if(l==r){
            st[p]=x;
            return;
        }
        int mid=(l+r)/2;
        if(k<=mid)  upd(2*p,l,mid,k,x);
        else    upd(2*p+1,mid+1,r,k,x);
        st[p]=st[2*p]&st[2*p+1];
    }
    int get(int p,int l,int r,int i,int j){
        if(j<i) return (1<<30)-1;
        if(l>j || r<i)  return (1<<30)-1;
        if(i<=l && r<=j){
            return st[p];
        }
        int mid=(l+r)/2;
        return get(2*p,l,mid,i,j)&get(2*p+1,mid+1,r,i,j);
    }
    long long countSubarrays(vector<int>& nums, int k) {
        int n=nums.size();
        st.assign(4*n,(1<<30)-1);
        for(int i=0;i<n;i++){
            upd(1,0,n-1,i,nums[i]);
        }
        long long val=0;
        for(int i=0;i<n;i++){
            if((nums[i]&k)!=k)  continue;
            int low=i;
            int high=n-1;
            int ans=n;
            while(low<=high){
                int mid=(low+high)/2;
                if((get(1,0,n-1,i,mid)&k)!=k){
                    ans=mid;
                    high=mid-1;
                }
                else{
                    low=mid+1;
                }
            }
            if(get(1,0,n-1,i,ans-1)!=k) continue;
            if(nums[i]==k){
                val+=ans-i;
            }
            else{
                int low=i,high=ans-1,curr=ans-1;
                while(low<=high){
                    int mid=(low+high)/2;
                    if(get(1,0,n-1,i,mid)==k){
                        curr=mid;
                        high=mid-1;
                    }
                    else{
                        low=mid+1;
                    }
                }
                val+=ans-curr;
            }
        }
        return val;
    }
};

