        vector<unordered_map<long long, long long>> intermediateResults(2);
        int currentMap = 0;

        for (int i = 0; i < sequenceLength; ++i) {
            int nextMap = 1 - currentMap;
            intermediateResults[nextMap].clear();

            if (nums[i] == k) {
                ++totalCount;
