const int N = 1e5 + 5;
class Solution {
public:
    int rmq[17][N];

    int sumAnd(int L, int R) {
        int h = 31 - __builtin_clz(R - L + 1);
        return rmq[h][L] & rmq[h][R - (1 << h) + 1];
    }

    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        for (int i = 1; i <= n; i++) {
            rmq[0][i] = nums[i - 1];
        }
        for (int j = 1; j < 17; j++) {
            for (int i = 1; i + (1 << j) <= n + 1; i++)
                rmq[j][i] = rmq[j - 1][i] & rmq[j - 1][i + (1 << (j - 1))];
        }
        long long ans = 0;
        for (int i = 1; i <= n; i++) {
            int L = i, R = n;
            while (L <= R) {
                int mid = (L + R) >> 1;
                if (sumAnd(i, mid) <= k) R = --mid;
                else L = ++mid;
            }
            if (L > n || sumAnd(i, L) != k) continue;
            int L2 = L; R = n;
            while (L2 <= R) {
                int mid = (L2 + R) >> 1;
                if (sumAnd(i, mid) < k) R = --mid;
                else L2 = ++mid;
            }
            // cout << L << ' ' << L2 << '\n';
            ans += L2 - L;
        }
        return ans;
    }
};

class Solution {
public:
