        for(int i=0;i<n;i++)
        {
             int leftIndex=n;
             int rightIndex=i;
             int l=i;
             int r=n-1;
             while(l<=r)
             {
                int mid=(l+r)/2;
                if(query(1,0,n-1,i,mid)>=k)
                {    
                     rightIndex=max(rightIndex,mid);
                     l=mid+1;
                }
                else{
                    r=mid-1;
