             }

             int range=max(0,rightIndex-leftIndex+1);
      //       cout<<i<<" , "<<leftIndex<<" "<<rightIndex<<" -> "<<range<<endl;
             if(range==1)
             {
               if(v[i]==k ||  (leftIndex!=i))
