class Solution {
public:
    #define ll long long

    int calculateSubarrayValue(int left, int right, vector<vector<int>>& prefixSums) {
        int length = (right - left + 1);
        int result = 0;

        for (int bit = 0; bit < 30; ++bit) {
            int count = prefixSums[right][bit];
            if (left > 0) {
                count -= prefixSums[left - 1][bit];
            }
            if (count == length) {
                result += (1 << bit);
            }
        }
        return result;
    }

    int findStartIndex(int currentIndex, vector<vector<int>>& prefixSums, int arraySize, int targetValue) {
        int low = currentIndex, high = arraySize - 1;
        int index = -1;

        if (calculateSubarrayValue(low, low, prefixSums) < targetValue) {
            return -1;
        }

        while (low <= high) {
            int mid = (low + high) / 2;
            int value = calculateSubarrayValue(currentIndex, mid, prefixSums);

            if (value > targetValue) {
                low = mid + 1;
            } else if (value == targetValue) {
                index = mid;
                high = mid - 1;
            } else {
                high = mid - 1;
            }
        }
        return index;
    }

    int findEndIndex(int currentIndex, vector<vector<int>>& prefixSums, int arraySize, int targetValue) {
        int low = currentIndex, high = arraySize - 1;
        int index = -1;

        if (calculateSubarrayValue(low, low, prefixSums) < targetValue) {
            return -1;
        }

        while (low <= high) {
            int mid = (low + high) / 2;
            int value = calculateSubarrayValue(currentIndex, mid, prefixSums);

            if (value > targetValue) {
                low = mid + 1;
            } else if (value == targetValue) {
                index = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return index;
    }

    long long countSubarrays(vector<int>& nums, int targetValue) {
        int arraySize = nums.size();
        vector<vector<int>> prefixSums(arraySize, vector<int>(30, 0));

        // Calculate prefix sums for each bit position
        for (int i = 0; i < arraySize; ++i) {
            for (int bit = 0; bit < 30; ++bit) {
                prefixSums[i][bit] = (nums[i] >> bit) & 1;
                if (i > 0) {
                    prefixSums[i][bit] += prefixSums[i - 1][bit];
                }
            }
        }

        ll totalSubarrays = 0LL;

        for (int i = 0; i < arraySize; ++i) {
            int startIndex = findStartIndex(i, prefixSums, arraySize, targetValue);
            int endIndex = findEndIndex(i, prefixSums, arraySize, targetValue);

            if (startIndex == -1 || endIndex == -1) {
                continue;
            }

            totalSubarrays += 1LL * endIndex - 1LL * startIndex + 1LL;
        }

        return totalSubarrays;
    }
};

