                            mn = dp[index][i];
                        } else {
                            mn = min(mn, dp[index][i]);
                        }
                    }
                }
                if (mn == -1) {
                    if (now == m) {
                        ans += n - index;
                    }
                    index = n;
                } else {
                    if (now == m) {
                        ans += mn - index;
                    }
                    now &= nums[mn];
                    index = mn;
                }
            }
        }
        return ans;
    }
};

