#define INF INT32_MAX
class SegmentTree {
public:
    vector<int> tree;
    int n;

    SegmentTree(vector<int>& arr) {
        n = arr.size();
        tree.resize(4 * n);
        build(arr, 0, 0, n - 1);
    }

    void build(vector<int>& arr, int node, int start, int end) {
        if (start == end) {
            tree[node] = arr[start];
        } else {
            int mid = (start + end) / 2;
            build(arr, 2 * node + 1, start, mid);
            build(arr, 2 * node + 2, mid + 1, end);
            tree[node] = tree[2 * node + 1] & tree[2 * node + 2];
        }
    }

    int query(int l, int r) {
        return query(0, 0, n - 1, l, r);
    }

    int query(int node, int start, int end, int l, int r) {
        if (r < start || end < l) {
            return INF;
        }
        if (l <= start && end <= r) {
            return tree[node];
        }
        int mid = (start + end) / 2;
        int p1 = query(2 * node + 1, start, mid, l, r);
        int p2 = query(2 * node + 2, mid + 1, end, l, r);
        return p1 & p2;
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
       int n = nums.size();
        SegmentTree st(nums);
        long long int ans= 0;

        for (int i = 0; i < n; i++) {
            int left = i, right = n - 1;
            int li=-1,ri=-1;

            while (left <= right) {
                int mid = left + (right - left) / 2;
                int gg = st.query(i, mid);
                if(gg>k)
                {
                    left=mid+1;
                }
                else if(gg<k)
                {
                    right=mid-1;
                }
                else if(gg==k)
                {
                    li=mid;
                    right=mid-1;
                }

            }
            left=i,right=n-1;
               while (left <= right) {
                int mid = left + (right - left) / 2;
                int gg= st.query(i, mid);
                if(gg>k)
                {
                    left=mid+1;
                }
                else if(gg<k)
                {
                    right=mid-1;
                }
                else if(gg==k)
                {
                    ri=mid;
                    left=mid+1;
                }

            }
            if(li!=-1)
            ans+=(ri-li+1);
        }

        return ans;
    }
};

class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        pref = [[0] for _ in range(31)]
        for i in range(n):
            for b in range(31):
                pref[b].append(pref[b][-1] + ((nums[i] >> b) & 1))
        def get_larger(limit):
            l = 0
            curr = -1
            ans = 0
            for r in range(n):
                curr &= nums[r]
                while curr < limit:
                    curr = 0
                    for b in range(31):
                        if pref[b][r + 1] - pref[b][l + 1] == r - l:
                            curr |= (1 << b)
                    l += 1
                    if l > r:
                        curr = -1
                        break
                ans += (r - l + 1)
            return ans
        return get_larger(k) - get_larger(k + 1)

