class Solution {
    fun countSubarrays(nums: IntArray, k: Int): Long {
    var res = 0L
    var start = 0
    var minn = 0
    val kBits = toBits(k)
    val kZeros = kBits.count { it == 0 }
    val zeroMap = IntArray(32)
    for (i in 0 until nums.size){
        if (nums[i] and k < k){
            start = i + 1
            minn = i + 1
            for (j in 0 until 32) {
                zeroMap[j] = 0
            }
        } else {
            val next = toBits(nums[i])
            for (j in 0 until 32){
                if (next[j] == 0) zeroMap[j]++
            }
            val zeros = zeroMap.count {it > 0}
            if (zeros == kZeros) {
                var z = true
                while (z) {
                    val prev = toBits(nums[minn])
                    for (j in 0 until 32){
                        if (prev[j] == 0 && zeroMap[j] <= 1){
                            z = false
                            break
                        }
                    }
                    if (z) {
                        for (j in 0 until 32){
                            if (prev[j] == 0 ){
                                zeroMap[j]--
                            }
                        }
                        minn++
                    }
                }
                res += (minn - start + 1)
            }
        }
    }
    return res
}

fun toBits(num: Int): IntArray{
    val res = IntArray(32)
    var n = num
    for (i in 0 until 32){
        if (n == 0) break
        res[i] = n % 2
        n /= 2
    }
    return res
}
}

class Solution {
public:
    int pref[100005][32];

    int get(int l, int r, int n) {
        int ans = 0;
        for (int j = 0; j < 31; j++) {
            int ct = pref[r][j];
            if (l > 0) {
                ct -= pref[l - 1][j];
            }
            if (ct == r - l + 1) {
                ans += 1 << j;
            }
        }
        return ans;
    }

    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 31; j++) {
                int b = 1 << j;
                int c = nums[i] & b;
                if (c != 0) {
                    pref[i][j] = 1;
                } else {
                    pref[i][j] = 0;
                }
                if (i != 0) {
                    pref[i][j] += pref[i - 1][j];
                }
            }
        }
        long long ans = 0;
        for (int i = 0; i < n; i++) {
            int l = 0, r = i, rt = -1, lf = n;
            while (l <= r) {
                int mid = (l + r) / 2;
                int sum = get(mid, i, n);
                //cout << i << " " << l << " " << r << " " << sum << endl;
                if (sum > k) {
                    r = mid - 1;

                } else if (sum == k) {
                    rt = max(rt, mid);
                    l = mid + 1;

                } else {
                    l = mid + 1;
                }
            }

            if (rt == -1) {
                continue;
            }
            l = 0, r = i;

            while (l <= r) {
                int mid = (l + r) / 2;
                int sum = get(mid, i, n);
                if (sum > k) {
                    r = mid - 1;
                } else if (sum == k) {
                    lf = min(lf, mid);
                    r = mid - 1;

                } else {
                    l = mid + 1;
                }
            }
            if (lf == n) {
                continue;
            }
            //cout << i << " " << rt << " " << lf << endl;
            ans += rt - lf + 1;
        }
        return ans;

    }
};

class Solution {
    fun countSubarrays(nums: IntArray, k: Int): Long {
    var res = 0L
    var start = 0
    var minn = 0
    val kBits = toBits(k)
    val kZeros = kBits.count { it == 0 }
    val zeroMap = IntArray(32)
    for (i in 0 until nums.size){
        if (nums[i] and k < k){
            start = i + 1
            minn = i + 1
            for (j in 0 until 32) {
                zeroMap[j] = 0
            }
        } else {
            val next = toBits(nums[i])
            for (j in 0 until 32){
                if (next[j] == 0) zeroMap[j]++
            }
            val zeros = zeroMap.count {it > 0}
            if (zeros == kZeros) {
                var z = true
                while (z) {
                    val prev = toBits(nums[minn])
                    for (j in 0 until 32){
                        if (prev[j] == 0 && zeroMap[j] <= 1){
                            z = false
                            break
                        }
                    }
                    if (z) {
                        for (j in 0 until 32){
                            if (prev[j] == 0 ){
                                zeroMap[j]--
                            }
                        }
                        minn++
                    }
                }
                res += (minn - start + 1)
            }
        }
    }
    return res
}

fun toBits(num: Int): IntArray{
    val res = IntArray(32)
    var n = num
    for (i in 0 until 32){
        if (n == 0) break
        res[i] = n % 2
        n /= 2
    }
    return res
}
}

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        long long result = 0;
        int const N = nums.size();
        vector<int> A(30, -1);
        for (int i = 0; i < N; ++i)
        {
            int const x = nums[i];
            for (int j = 0; j < 30; ++j)
                if ((x & (1 << j)) == 0)
                    A[j] = i;
            if ((x & k) == k)
            {
                int L = -1, R = i;
                for (int j = 0; j < 30; ++j)
                    if (k & (1 << j))
                        L = max(L, A[j]);
                    else
                        R = min(R, A[j]);
                if (L < R)
                    result += R - L;
            }
        }
        return result;
    }
};

