class Solution {
public:
    long long countSubarrays(vector<int>& array, int target) {
        int size = array.size();
        long long total = 0;
        unordered_map<long long, long long> previousResults;
        for (int index = 0; index < size; ++index) {
            unordered_map<long long, long long> currentResults; 
            if (array[index] == target) {
                ++total;
            }
            currentResults[array[index]] = 1;
            for (auto& [value, frequency] : previousResults) {
                long long newAndResult = value & array[index];
                if (newAndResult == target) {
                    total += frequency;
                }
                currentResults[newAndResult] += frequency;
            }

            previousResults = currentResults;
        }
        return total;
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        long long n = nums.size();
    long long count = 0;
    unordered_map<long long, long long> prefixCount;

    // Iterate through the array
    for (int i = 0; i < n; ++i) {
        long long currentAND = nums[i];
        if (currentAND == k) {
            count++;
        }
        unordered_map<long long, long long> newPrefixCount;
        newPrefixCount[currentAND]++;

        for (auto& entry : prefixCount) {
            long long newAND = entry.first & currentAND;
            newPrefixCount[newAND] += entry.second;
            if (newAND == k) {
                count += entry.second;
            }
        }

        prefixCount = newPrefixCount;
    }

    return count;
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& v, int k) {
        int idx[30];
        multiset<int> st;
        for (int i = 0; i < 30; ++i) {
            idx[i] = -1;
        }
        int cnt = 0;
        for (int i = 0; i < 30; ++i) {
            if ((k & (1 << i)) == 0)
                ++cnt;
        }
        int l = -1;
        long long ans = 0;
        for (int i = 0; i < v.size(); ++i) {
            for (int j = 0; j < 30; ++j) {
                if (k&(1<<j)) {
                    if ((v[i]&(1<<j)) == 0) {
                        l = i;
                        break;
                    }
                } else {
                    if ((v[i]&(1<<j)) == 0) {
                        if (idx[j] != -1)
                            st.erase(st.find(idx[j]));
                        idx[j] = i;
                        st.insert(idx[j]);
                    }
                }
            }
            if (st.size() == cnt && *st.begin() > l) {
                ans += *st.begin()-l;
            }
        }
        return ans;
    }
};

