template<typename T>
class SparseTable {
    using F = function<T(const T&, const T&)>;
public :
    int n;
    F func;
    vector<vector<int>> v;

    SparseTable(const vector<int> &a, F function) : func(function) {
        n = static_cast<int>(a.size());
        int LOG = 32 - __builtin_clz(n);
        v.resize(LOG);
        v[0] = a;
        for (int i = 1; i < LOG; i++) {
            v[i].resize(n - (1 << i) + 1);
            for (int j = 0; j <= (n - (1 << i)); j++) {
                v[i][j] = func(v[i - 1][j], v[i - 1][j + (1 << (i - 1))]);
            }
        }
    }

    T get(int l, int r) {
        int L = (r - l + 1);
        int lg = 31 - __builtin_clz(L);
        return func(v[lg][l], v[lg][r - (1 << lg) + 1]);
    }
};


class Solution {
public:
    long long countSubarrays(vector<int>& v, int k) {
        int n = (int) v.size();

        SparseTable<int> st(v, [&] (int x, int y) { return (x & y); });

        auto getL = [&] (int id) {
            int lo = id, hi = n - 1, ans = id - 1;
            while (lo <= hi) {
                int mid = (hi + lo) / 2;
                if ((st.get(id, mid) & k) == k and st.get(id, mid) > k) {
                    ans = mid;
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }
            return ans;
        };

        auto getR = [&] (int id) {
            int lo = id, hi = n - 1, ans = id;
            while (lo <= hi) {
                int mid = (hi + lo) / 2;
                if ((st.get(id, mid) & k) == k) {
                    ans = mid;
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }
            return ans;
        };

        long long ans = 0;
        for (int i = 0; i < n; i++) {
            if ((v[i] & k) != k) {
                continue;
            }
            int L = getL(i);
            int R = getR(i);
            ans += (R - L);
        }
        return ans;

    }
};

